INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('499c9d09-8a63-5499-af39-347814df7cf9', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 32, 32, 'ይህም መጥቼ ምድራችሁን ወደምትመስለው ምድር፥ እህልና የወይን ጠጅ፥ እንጀራና ወይን፥ ወይራና ማር ወዳለባት ምድር እስካፈልሳችሁ ድረስ በሕይወት እንድትኖሩ፥ እንዳትሞቱም ነው። ሕዝቅያስም፦ እግዚአብሔር ያድናችኋል ብሎ ያታልላችኋልና አትስሙት።'),
  ('91049e72-a1db-5291-a704-faac8b48769b', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 33, 33, 'በውኑ የአሕዛብ አማልክት አገሮቻቸውን ከአሦር ንጉሥ እጅ አድነዋቸዋልን?'),
  ('6b9605b1-7407-5820-aea0-f36f11105886', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 34, 34, 'የኤማትና የአርፋድ አማልክት ወዴት አሉ? የሴፋሩዋይምና የሄና የዒዋም አማልክት ወዴት አሉ? ስማርያን ከእጄ አድነዋታልን?'),
  ('ce4d9d70-5892-548c-a936-a15bfd01710e', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 35, 35, 'እግዚአብሔር ኢየሩሳሌምን ከእጄ ያድናት ዘንድ ከሀገሮቹ አማልክት ሁሉ ሀገሩን ከእጄ ያዳነ ማን ነው?”'),
  ('48961785-b12f-5f41-a6fa-cbc14b48da52', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 36, 36, 'ሕዝቡም ዝም አሉ፥ አንዳችም ቃል አልመለሱለትም፤ ንጉሡ እንዳይመልሱለት አዝዞ ነበርና።'),
  ('5e16ebdf-43f2-5e9c-a6f8-8c80cea43963', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 37, 37, 'የቤቱ አዛዥ የኬልቅዩ ልጅ ኤልያቄም፥ ጸሓፊው ሳምናስ፥ ታሪክ ጸሓፊውም የአሳፍ ልጅ ዮአስ ልብሳቸውን ቀድደው ወደ ሕዝቅያስ ገቡ፥ የራፋስቂስንም ቃል ነገሩት።'),
  ('31a86e6e-c8b1-594c-a1e3-8c0a490abb96', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '04a99d70-cb0a-5ab8-a36e-b9c308c9fe7a', 1, 1, 'ንጉሡም ሕዝቅያስ ይህን በሰማ ጊዜ ልብሱን ቀደደ፥ ማቅም ለበሰ፥ ወደ እግዚአብሔርም ቤት ገባ።'),
  ('7b0719e8-bd63-56eb-a4e1-a237d3a539f3', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '04a99d70-cb0a-5ab8-a36e-b9c308c9fe7a', 2, 2, 'የቤቱንም አዛዥ ኤልያቄምን ጸሓፊውንም ሳምናስን የካህናቱንም አለቆች ማቅ ለብሰው ወደ አሞጽ ልጅ ወደ ነቢዩ ኢሳይያስ ይሄዱ ዘንድ ላካቸው።'),
  ('7463d739-7cf1-5e42-a997-443156eeb3f8', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '04a99d70-cb0a-5ab8-a36e-b9c308c9fe7a', 3, 3, 'እነርሱም አሉት፥ “ሕዝቅያስ እንዲህ ይላል፦ ይህ ቀን የመከራና የተግሣጽ የዘለፋም ቀን ነው፤ ልጆች የሚወለዱበት ጊዜ ደርሶአል፤ እናትም ለማማጥ ኀይል የላትም።'),
  ('a394ad83-6f93-57bd-ae45-ce3b493d89ba', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '04a99d70-cb0a-5ab8-a36e-b9c308c9fe7a', 4, 4, 'ምናልባት በሕያው አምላክ ላይ ይገዳደር ዘንድ ጌታው የአሦር ንጉሥ የላከውን የራፋስቂስን ቃል ሁሉ አምላክህ እግዚአብሔር ይሰማ እንደሆነ፥ አምላክህ እግዚአብሔርም ስለ ሰማው ቃል ይገሥጸው እንደ ሆነ፥ ስለዚህ ለቀረው ቅሬታ ጸልይ።”'),
  ('a645c375-ef45-5028-a045-bb1c30a7b62d', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '04a99d70-cb0a-5ab8-a36e-b9c308c9fe7a', 5, 5, 'እንዲሁ የንጉሡ የሕዝቅያስ ብላቴኖች ወደ ኢሳይያስ መጡ።'),
  ('85999f99-15a6-5074-a9c1-c404d545b7bc', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '04a99d70-cb0a-5ab8-a36e-b9c308c9fe7a', 6, 6, 'ኢሳይያስም አላቸው፥ “ለጌታችሁ እንዲህ በሉት፦ እግዚአብሔር እንዲህ ይላል፦ የአሦር ንጉሥ ብላቴኖች ስለ ተሳደቡት፥ ስለ ሰማኸው ቃል አትፍራ።'),
  ('6c1d9803-6cd1-5127-a779-39bf5c3c0838', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '04a99d70-cb0a-5ab8-a36e-b9c308c9fe7a', 7, 7, 'እነሆ፥ በላዩ መንፈስን እሰድዳለሁ፤ ወሬንም ይሰማል፤ ወደ ምድሩም ይመለሳል፤ በምድሩም በሰይፍ እንዲወድቅ አደርገዋለሁ በሉት።”'),
  ('9cb45055-0454-5355-a869-9d60f6fbd657', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 1, 8, 'የአሦርም ንጉሥ ከለኪሶ እንደ ራቀ ሰምቶ ነበርና ራፋስቂስ ተመልሶ በሎምና ሲዋጋ አገኘው።'),
  ('c915d259-62e8-5e7d-ad1e-5bc29ebc1cb8', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 2, 9, 'እርሱም፥ “የኢትዮጵያ ንጉሥ ቲርሐቅ ሊወጋህ መጥቶአል” የሚል ወሬ በሰማ ጊዜ ተመልሶ ወደ ሕዝቅያስ መልእክተኞችን ላከ፤ እንዲህ ሲል፦'),
  ('85d7ded7-0191-5ecf-a50e-2c5c6f2789f2', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 3, 10, '“ለይሁዳ ንጉሥ ለሕዝቅያስ እንዲህ ብላችሁ ንገሩት፦ ኢየሩሳሌም በአሦር ንጉሥ እጅ አትሰጥም ብሎ የምትታመንበት አምላክህ አያታልልህ።'),
  ('3a60207d-fb7d-57c2-ae6a-6b2900576521', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 4, 11, 'እነሆ፥ የአሦር ነገሥታት በምድር ሁሉ ላይ ያደረጉትን፥ እንዴትስ እንዳጠፉአቸው ሰምተሃል፤ አንተስ ትድናለህን?'),
  ('d3befefd-c8b8-5304-a92f-64fe25351e0f', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 5, 12, 'አባቶች ያጠፉአቸውን፥ ጎዛንን፥ ካራንን፥ ራፌስን በታኤሴቴም የነበሩትንም የዔድንን ልጆች፥ የአሕዛብ አማልክት አዳኑአቸውን?'),
  ('91eb1dd5-f516-5d4a-a740-ddf03f927e07', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 6, 13, 'የሐማት ንጉሥ፥ የአርፋድ ንጉሥ፥ የሴፋሩሄም ከተማ ንጉሥ፥ የኤናና የዓዋ ንጉሥ ወዴት አሉ?”'),
  ('253da365-a07d-500e-a29c-f0b45b2db519', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 7, 14, 'ሕዝቅያስም ደብዳቤውን ከመልእክተኞች እጅ ተቀብሎ አነበበው፤ ሕዝቅያስም ወደ እግዚአብሔር ቤት ወጥቶ በእግዚአብሔር ፊት ዘረጋው።'),
  ('7a047a9e-9a7b-598c-a8fe-76cf8dab79bd', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 8, 15, 'ሕዝቅያስም ወደ እግዚአብሔር እንዲህ ብሎ ጸለየ፥ “በኪሩቤል ላይ የምትቀመጥ የእስራኤል አምላክ አቤቱ፥ አንተ ብቻህን የምድር ነገሥታት ሁሉ አምላክ ነህ፤ ሰማይንና ምድርን ፈጥረሃል ።'),
  ('80f7cbee-0a2f-517e-a052-c541d99faf8e', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 9, 16, 'አቤቱ፥ ጆሮህን አዘንብልና ስማ፥ አቤቱ፥ ዐይንህን ክፈትና እይ፤ በሕያው አምላክ ላይ ይገዳደር ዘንድ የላከውን የሰናክሬምን ቃል ስማ።'),
  ('3a38e1f5-04a6-562d-ad2b-11deccdfe76b', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 10, 17, 'አቤቱ፥ በእውነት የአሦር ነገሥት አሕዛብን አጥፍተዋል፤'),
  ('3621959d-69dd-5501-a020-5a3a32d00f36', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 11, 18, 'አማልክቶቻቸውንም በእሳት ላይ ጥለዋል፤ የእንጨትና የድንጋይ የሰው እጅ ሥራ ነበሩ እንጂ አማልክት አልነበሩምና፤ ስለዚህ አጥፍተዋቸዋል።'),
  ('615d81fe-ce4e-5ffb-a70d-5e494bbf0c90', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '51b90c28-250b-5f3d-aead-4f33dc981580', 12, 19, 'እንግዲህም አምላካችን አቤቱ፥ የምድር መንግሥታት ሁሉ አንተ ብቻ እግዚአብሔር አምላክ እንደ ሆንህ ያውቁ ዘንድ ከአሦር ንጉሥ እጅ አድነን።”'),
  ('50918351-9183-55b6-af82-af6a3614aacc', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 1, 20, 'የአሞጽም ልጅ ኢሳይያስ እንዲህ ብሎ ወደ ሕዝቅያስ ላከ፥ “የሠራዊት ጌታ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ስለ አሦር ንጉሥ ስለ ሰናክሬም ወደ እኔ የለመንኸውን ሰምቻለሁ።'),
  ('d5f7d1ba-bdbe-5f35-ad0d-96ebbadbf1e3', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 2, 21, 'ድንግሊቱ የጽዮን ልጅ፥ ሰድቦሻልና ንቆሻልምና፥ የኢየሩሳሌም ልጅ፥ በአንቺ ላይ ራሱን ነቅንቋልና እግዚአብሔር በእርሱ ላይ የተናገረው ቃል ይህ ነው፦'),
  ('5424e61a-d96b-526b-a289-1c8bb566438a', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 3, 22, 'የተገዳደርኸው፥ የሰደብኸውስ ማን ነው? ቃልህንስ ከፍ ከፍ ያደረግኸው፥ ዐይንህንም ወደ ላይ ያነሣኸው በማን ላይ ነው? በእስራኤል ቅዱስ ላይ ነው።'),
  ('60017160-6e87-56e8-a37e-dcc439a3cfd1', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 4, 23, 'አንተስ በመልእክተኞችህ እጅ በእግዚአብሔር ላይ ተገዳደርህ፤ እንዲህም አልህ፦ በሰረገላዬ ብዛት ወደ ተራሮች ከፍታ፥ ወደ ሊባኖስ ጥግ እወጣለሁ፤ ረጃጅሞችንም ዝግባዎች የተመረጡትንም ጥዶች እቈርጣለሁ፤ ወደ ሀገሩም ዳርቻና ወደ ቀርሜሎስ ዱር እገባለሁ።'),
  ('a3e0bda7-cd54-5e79-ac2f-5ba2c6711a1b', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 5, 24, 'ዕረፍት አደረግሁ፤ የባዕድ ውኃንም ጠጣሁ፥ የተገደበውንም ውኃ ሁሉ በእግሬ ጫማ አደርቃለሁ።'),
  ('702f6114-6c61-570d-a74e-068792b46462', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 6, 25, '“እኔ ጥንቱን እንደ ሠራሁት፥ ቀድሞውንም እንዳደረግሁት አልሰማህምን? አሁንም የተመሸጉትን ከተሞች የፍርስራሽ ክምር እስኪሆኑ ድረስ እንድታፈርስ አደረግሁህ።'),
  ('e99f3a46-5257-56f7-a45a-726a679e7b9e', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 7, 26, 'ስለዚህም የሚኖሩባቸው ሰዎች እጆቻቸው ዝለዋል፤ ደንግጠውም አፍረዋል፤ እንደ ምድረ በዳ ሣር፥ እንደ ለምለምም ቡቃያ፥ በሰገነትም ላይ እንዳለ ሣር፥ ሳይሸት ዋግ እንደ መታውም እህል ሆነዋል።'),
  ('ebf23a82-c2b9-557d-a0cd-8c8f787db42e', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 8, 27, 'እኔ ግን መቀመጫህንና መውጫህን መግቢያህንም፥ በእኔም ላይ የተቈጣኸውን ቍጣ ዐውቄአለሁ።'),
  ('9fbc0993-f3f5-5d2f-ad85-e3ce280beb15', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 9, 28, 'ቍጣህና ትዕቢትህ ወደ ጆሮዬ ደርሶአልና ስለዚህ ስናጋዬን በአፍንጫህ፥ ልጓሜንም በከንፈርህ አደርጋለሁ፤ በመጣህበት መንገድም እመልስሃለሁ።'),
  ('4d3ff2e7-4589-524b-ae9f-23bbc42a6591', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 10, 29, '“ይህም ለአንተ ምልክት ይሆንልሃል፤ በዚህ ዓመት የገቦውን፥ በሁለተኛውም ዓመት ከገቦው የበቀለውን ትበላለህ፤ በሦስተኛውም ዓመት ትዘራለህ፤ ታጭድማለህ፥ ወይንም ትተክላለህ፤ ፍሬውንም ትበላለህ።'),
  ('1fe8b8e7-b637-5960-a9a9-b5e740d4527b', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 11, 30, 'የዳነው የይሁዳ ቤት ቅሬታ ሥሩን ወደ ታች ይሰድዳል፤ ወደ ላይም ያፈራል።'),
  ('0c705b1b-4b14-5e3a-a6f4-855e7a9c2b05', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 12, 31, 'ከኢየሩሳሌም ቅሬታ፥ ከጽዮንም ተራራ የዳነ ይወጣልና፤ የሠራዊት ጌታ የእግዚአብሔር ቅንአት ይህን ያደርጋል።”'),
  ('c0ccc397-3a6a-5ce3-a942-ad3b448607a8', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 13, 32, 'እንደዚህ አይደለምን? እግዚአብሔር ስለ አሦር ንጉሥ እንዲህ ይላል፥ “ወደዚች ከተማ አይገባም፥ ፍላጻንም አይወረውርባትም፤ በጋሻም አይመጣባትም፥ የአፈርንም ድልድል አይደለድልባትም።'),
  ('5b239193-af5f-5feb-a239-b5edaefc6171', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 14, 33, 'በመጣበት መንገድ በዚያ ይመለሳል እንጂ፥ ወደዚህችም ከተማ አይገባም፥ ይላል እግዚአብሔር።'),
  ('334b903e-f1be-5f79-ab3e-98e87ff8c9d8', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 15, 34, 'ስለ እኔም፥ ስለ ባሪያዬ ስለ ዳዊትም ይህችን ከተማ እጋርዳታለሁ።”'),
  ('b123d345-d329-507d-a8ab-77838c9935ba', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 16, 35, 'በዚያችም ሌሊት የእግዚአብሔር መልአክ መጣ፤ ከአሦራውያንም ሰፈር መቶ ሰማንያ አምስት ሺህ ገደለ፤ ማለዳም በተነሡ ጊዜ፥ እነሆ፥ ሁሉ በድኖች ነበሩ።'),
  ('1daf58bb-dec5-5c0b-a3b5-6590985d7204', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 17, 36, 'የአሦርም ንጉሥ ሰናክሬም ተነሥቶ ሄደ፤ ተመልሶም በነነዌ ተቀመጠ።'),
  ('37c12bee-26ea-5aa6-a158-5a54e5e0ba55', 'e2b5c0a3-7f67-50ea-a9ec-54b55c57a47f', '0f72dfff-961a-5779-ad3a-0c384396d5ca', 18, 37, 'በአምላኩም በሲድራክ ቤት ሲሰግድ ልጆቹ አድራሜሌክና ሶርሶር በሰይፍ ገደሉት፤ ወደ አራራትም ሀገር ኰበለሉ። ልጁም አስራዶን በእርሱ ፋንታ ነገሠ።'),
  ('ac6a3fa5-f9ec-5a86-a286-84d6cb65ad3b', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 1, 1, 'በዚያም ወራት ሕዝቅያስ ታመመ፤ ለሞትም ደረሰ። ነቢዩም የአሞጽ ልጅ ኢሳይያስ ወደ እርሱ መጥቶ፥ “እግዚአብሔር እንዲህ ይላል፦ ትሞታለህ እንጂ በሕይወት አትኖርምና ቤትህን አስተካክል” አለው።'),
  ('0bbc647f-deaa-5f42-ad2c-7d9e6d13eecc', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 2, 2, 'ሕዝቅያስም ፊቱን ወደ ግድግዳው መልሶ እንዲህ ሲል ወደ እግዚአብሔር ጸለየ፦'),
  ('98733cdb-bbbb-5d2b-ad9d-51a26b912538', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 3, 3, '“አቤቱ፥ በፊትህ በእውነትና በፍጹም ልብ እንደ ሄድሁ፥ መልካም ነገርም እንዳደረግሁ አስብ።” ሕዝቅያስም እጅግ አለቀሰ።'),
  ('e6be9835-3dc0-545c-aa1e-abe84393a97a', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 4, 4, 'ኢሳይያስም ወደ መካከለኛው አደባባይ ሲደርስ እግዚአብሔር ተናገረው፤ እንዲህም አለው፦'),
  ('80687cbc-b21b-5b69-a9ab-e68a3a6abd08', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 5, 5, '“ተመልሰህ የሕዝቤን ንጉሥ ሕዝቅያስን እንዲህ በለው፦ የአባትህ የዳዊት አምላክ እግዚአብሔር እንዲህ ይላል፦ ጸሎትህን ሰምቻለሁ፥ እንባህንም አይቻለሁ፤ እነሆ፥ እኔ እፈውስሃለሁ፤ እስከ ሦስት ቀንም ድረስ ወደ እግዚአብሔር ቤት ትወጣለህ።'),
  ('c1dc7022-a301-573d-abed-e7b2fa33368b', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 6, 6, 'በዕድሜህም ላይ ዐሥራ አምስት ዓመት እጨምራለሁ፤ አንተንና ይህችን ከተማ ከአሦር ንጉሥ እጅ እታደጋለሁ፤ ስለ እኔ፥ ስለ ባሪያዬም ስለ ዳዊት ይህችን ከተማ አጋርዳታለሁ።”'),
  ('edc10fc4-ed55-5ac7-aa38-78f10ddbf47c', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 7, 7, 'ኢሳይያስም አለው፥ “የበለስ ጥፍጥፍ አምጥተህ በእባጭህ ላይ አድርግ ትፈወሳለህም።”'),
  ('62a11cf9-8382-5be3-ac66-e5e009f5602f', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 8, 8, 'ሕዝቅያስም ኢሳይያስን፥ “እግዚአብሔር እንዲፈውሰኝ፥ እኔስ እስከ ሦስት ቀን ድረስ ወደ እግዚአብሔር ቤት እንድወጣ ምልክቱ ምንድን ነው?” አለው።'),
  ('46496dca-3470-58b1-affc-ccde2da76bc3', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 9, 9, 'ኢሳይያስም፥ “እግዚአብሔር የተናገረውን ነገር እንዲፈጽመው ከእግዚአብሔር ዘንድ ምልክቱ ይህ ይሆንልሃል፤ ጥላው ዐሥር ደረጃ ወደ ፊት ይሂድን? ወይስ ዐሥር ደረጃ ወደ ኋላው ይመለስ?” አለ።'),
  ('813764b6-050a-57c4-a91a-e10b5b7907f8', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 10, 10, 'ሕዝቅያስም ኢሳይያስን፥ “ጥላው ዐሥር ደረጃ ቢጨምር ቀላል ነገር ነው፤ እንዲህ አይሁን፤ ነገር ግን ጥላው ዐሥር ደረጃ ወደ ኋላ ይመለሰ” አለው።'),
  ('bc0f822c-83bf-559a-a2c4-9033f881c4e4', '582e5703-9c0d-57f3-a4e2-aceced218c50', '81ffab9b-38a3-52ac-a968-ccc9d552293e', 11, 11, 'ነቢዩም ኢሳይያስ ወደ እግዚአብሔር ጮኸ፤ ጥላውም ዐሥር ደረጃ ወደ ኋላ ተመለሰ።'),
  ('56d449ff-38a2-5baa-a850-3214e92956ec', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 1, 12, 'በዚያም ወራት የባቢሎን ንጉሥ መሮዳህ ሕዝቅያስ እንደ ታመመ ሰምቶ ነበርና የበልዳንን ልጅ በልዳንን ከመጻሕፍትና እጅ መንሻ ጋር ወደ ሕዝቅያስ ላከ።'),
  ('225afde5-9912-5a98-afec-87e420e51372', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 2, 13, 'ሕዝቅያስም በእነርሱ ደስ አለው፤ ግምጃ ቤቱንም ሁሉ፥ ብሩንና ወርቁንም፥ ሽቱውንና የከበረውንም ዘይት፥ መሣሪያም ያለበትን ቤት በቤተ መዛግብቱም የተገኘውን ሁሉ አሳያቸው፤ በቤቱና በግዛቱ ሁሉ ካለው ሕዝቅያስ ያላሳያቸው የለም።'),
  ('11bbe71a-3f24-56e2-adb9-6099aa6f3b02', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 3, 14, 'ነቢዩ ኢሳይያስም ወደ ንጉሡ ወደ ሕዝቅያስ መጥቶ፥ “እነዚህ ሰዎች ምን አሉ? ከወዴትስ ወደ አንተ መጡ?” አለው። ሕዝቅያስም፥ “ከሩቅ ሀገር ከባቢሎን ወደ እኔ መጡ” አለው።'),
  ('921400d0-c59f-5410-a35e-57617f8c4a28', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 4, 15, 'እርሱም፥ “ምን አዩ?” አለው ሕዝቅያስም፥ “በቤቴ ያለውን ሁሉ አይተዋል፤ በቤተ መዛግብቴም ካለው ያላሳየኋቸው የለም” አለው።'),
  ('38610da8-5373-5b21-a169-db37deef1ea2', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 5, 16, 'ኢሳይያስም ሕዝቅያስን አለው፥ “የእግዚአብሔርን ቃል ስማ።'),
  ('892755d8-a01a-5e10-a95f-b05ab374aaf8', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 6, 17, 'እነሆ፥ በቤትህ ያለው ሁሉ፥ አባቶችህም እስከ ዛሬ ያከማቹት ሁሉ ወደ ባቢሎን የሚፈልስበት ወራት ይመጣል፤ ምንም አይቀርም፥ ይላል እግዚአብሔር።'),
  ('4949f738-29f5-5032-a3e3-abcd3018e1f5', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 7, 18, 'ከአንተም ከሚወጡት ከምትወልዳቸው ልጆችህ ማርከው ይወስዳሉ፤ በባቢሎንም ንጉሥ ቤት ውስጥ ጃንደረቦች ይሆናሉ።”'),
  ('a88f8214-d039-5cc2-a22a-e9a364718c2f', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 8, 19, 'ሕዝቅያስም ኢሳይያስን፥ “እግዚአብሔር የተናገረው ቃል መልካም ነው። ደግሞም በዘመኔ ሰላም ይሁን” አለው።'),
  ('ca0adb16-0215-51ba-a128-52c9449e0a07', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 9, 20, 'የቀረውም የሕዝቅያስ ነገር፥ ኀይሉም ሁሉ፥ ኵሬውንና መስኖውን እንደ ሠራ፥ ውኃውንም ወደ ከተማዪቱ እንዳመጣ፥ እነሆ፥ በይሁዳ ነገሥታት ታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('2fe1c96a-1f5c-5c7b-a18b-b91002e04d46', '582e5703-9c0d-57f3-a4e2-aceced218c50', '95ac0d4a-69c5-53ef-a861-c7e2be49ae2a', 10, 21, 'ሕዝቅያስም ከአባቶቹ ጋር አንቀላፋ፤ በዳዊት ከተማም ቀበሩት። ልጁ ምናሴም በእርሱ ፋንታ ነገሠ።'),
  ('9e22a9e5-881a-5738-ad74-dc11e1eb8de7', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 1, 1, 'ምናሴም በነገሠ ጊዜ ዐሥራ ሁለት ዓመት ሆኖት ነበረ፤ በኢየሩሳሌምም ኀምሳ አምስት ዓመት ነገሠ፤ የእናቱም ስም ሐፍሴባ ነበረ።'),
  ('fb69bbf3-6cf1-59bc-a946-d8662299fd2f', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 2, 2, 'እግዚአብሔርም ከእስራኤል ልጆች ፊት እንዳራቃቸው እንደ አሕዛብ ርኵሰት በእግዚአብሔር ፊት ክፉ ነገርን አደረገ።'),
  ('3f2681b6-ea61-5784-a944-463a05c3125a', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 3, 3, 'አባቱም ሕዝቅያስ ያፈረሳቸውን የኮረብታውን መስገጃዎች መልሶ ሠራ፤ የእስራኤልም ንጉሥ አክዓብ እንዳደረገው ለበዓል መሠዊያን ሠራ፤ የማምለኪያ ዐፀድንም ተከለ፤ ለሰማይም ሠራዊት ሁሉ ሰገደ አመለካቸውም።'),
  ('05aef664-e356-5b53-ad2c-eea7347ba025', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 4, 4, 'እግዚአብሔርም፥ “ስሜን በኢየሩሳሌም አኖራለሁ” ባለው በእግዚአብሔር ቤት መሠዊያን ሠራ።'),
  ('976c545b-811c-5f97-a802-7dad068e4c11', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 5, 5, 'በእግዚአብሔርም ቤት በሁለቱ ወለሎች ላይ ለሰማይ ሠራዊት ሁሉ መሠዊያን ሠራ።'),
  ('ac9493b7-81d6-5d10-a59d-374e1ccfb04c', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 6, 6, 'ልጁንም በእሳት ሠዋ፤ ሞራ ገላጭም ሆነ፤ አስማትም አደረገ፤ መናፍስት ጠሪዎችንና ጠንቋዮችንም ሰበሰበ፤ በእግዚአብሔርም ፊት እጅግ ክፉ ነገር አደረገ፤ ኣስቈጣውም።'),
  ('e0d5ef60-bd32-5c6d-a6be-95dacff8c819', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 7, 7, 'እግዚአብሔርም ለዳዊትና ለልጁ ለሰሎሞን፥ “በዚህ ቤት ከእስራኤልም ነገድ ሁሉ በመረጥኋት በኢየሩሳሌም ስሜን ለዘለዓለም አኖራለሁ፤'),
  ('1c766551-42c0-5a88-a07c-2ef459edcf06', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 8, 8, 'ያዘዝኋቸውንም ሁሉ ፥ ባሪያዬም ሙሴ ያዘዛቸውን ሕግ ሁሉ ቢያደርጉ ቢጠብቁም ለአባቶቻቸው ከሰጠኋት ምድር የእስራኤልን እግር እንደገና አላንቀሳቅስም” ባለው ቤት የሠራውን የማምለኪያ ዐፀድ የተቀረጸውንም ምስል አቆመ።'),
  ('da0993ef-b1a3-54c4-ae72-826468e6336a', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 9, 9, 'ነገር ግን አልሰሙም፤ እግዚአብሔርም ከእስራኤል ልጆች ፊት ካጠፋቸው ከአሕዛብ ይልቅ በእግዚአብሔር ዐይኖች ፊት ክፉ ይሠሩ ዘንድ ምናሴ አሳታቸው።'),
  ('c79c7158-8091-57fe-a5c8-6981463d8eb5', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 10, 10, 'እግዚአብሔርም በባሪያዎቹ በነቢያት ቃል እንዲህ ሲል ተናገረ፦'),
  ('db033850-ec72-519f-a9a0-7d33f8f54ba1', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 11, 11, '“የይሁዳ ንጉሥ ምናሴ ከእርሱ በፊት የነበሩ አሞራውያን ከሠሩት ሁሉ ይልቅ ይህን ክፉ ርኵሰት አድርጎአልና፥ ይሁዳንም ደግሞ በጣዖታቱ አስቶአልና፥'),
  ('eb0f2d03-54c6-5bcf-aba2-168786ade7c4', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 12, 12, 'ስለዚህ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ የሚሰማውን ሁሉ ሁለቱ ጆሮቹን ጭው የሚያደርግ ክፉ ነገርን በኢየሩሳሌምና በይሁዳ ላይ አመጣለሁ።'),
  ('bb563957-64d9-5e29-a96b-760997e6f6b6', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 13, 13, 'የሰማርያንም ገመድ የአክዓብንም ቤት ቱንቢ በኢየሩሳሌም ላይ እዘረጋለሁ፤ የሽቱ ዕቃ እንዲወለወል ኢየሩሳሌምን ወልውዬ በፊቷ እገለብጣታለሁ።'),
  ('db3e9834-3fe6-5de9-a34c-0cebae8fafe7', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 14, 14, 'የሕዝቡንም ቅሬታ እጥላለሁ፤ በጠላቶቻቸውም እጅ አሳልፌ እሰጣቸዋለሁ፤ ለጠላቶቻቸውም ሁሉ ምርኮና ብዝበዛ ይሆናሉ፤'),
  ('0b34203e-5072-5332-acf1-4be3c4e06481', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 15, 15, 'አባቶቻቸውን ከግብፅ ከአወጣኋቸው ቀን ጀምሮ እስከ ዛሬ ድረስ በፊቴ ክፉ ሠርተዋልና፥ አስቈጥተውኝማልና።”'),
  ('0945e467-bdb0-59dc-ab2c-d74c135f1e88', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 16, 16, 'ደግሞም ምናሴ በእግዚአብሔር ዐይኖች ፊት ክፉ ይሠራ ዘንድ ይሁዳን ካሳተበት ኀጢአት ሌላ ከዳር እስከ ዳር ኢየሩሳሌምን እስኪሞላት ድረስ እጅግ ብዙ ንጹሕ ደምን አፈሰሰ።'),
  ('d7feffe5-7ce7-5993-a796-f0e40426457c', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 17, 17, 'የምናሴም የቀረው ነገርና የሠራው ሥራ ሁሉ፥ ያደረገውም ኀጢአት፥ እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('9592863c-1022-5899-a7ea-3bf3a2f019f8', 'a0124273-abbc-5873-a29e-480683469a9f', 'ba54eaa9-b19f-52c4-a118-0362d9ccb373', 18, 18, 'ምናሴም ከአባቶቹ ጋር አንቀላፋ፥ በቤቱም አጠገብ ባለው በዖዛ አትክልት ቦታ ተቀበረ፤ ልጁም አሞጽ በእርሱ ፋንታ ነገሠ።'),
  ('6f32830f-a8a4-5176-a31f-68065c53f994', 'a0124273-abbc-5873-a29e-480683469a9f', 'ae0ded7d-30c7-5688-a222-d01865906d9b', 1, 19, 'አሞጽም በነገሠ ጊዜ ሃያ ሁለት ዓመት ሆኖት ነበረ፤ በኢየሩሳሌምም ሁለት ዓመት ነገሠ፤ እናቱም የዮጥባ ሰው የሐሩስ ልጅ ሚሱላም ነበረች።'),
  ('27406895-d67b-57cb-ac85-83c396b0426a', 'a0124273-abbc-5873-a29e-480683469a9f', 'ae0ded7d-30c7-5688-a222-d01865906d9b', 2, 20, 'አባቱ ምናሴም እንዳደረገ በእግዚአብሔር ፊት ክፉ ሠራ።'),
  ('63a50fe2-456f-52f2-a243-7ac8217c2abf', 'a0124273-abbc-5873-a29e-480683469a9f', 'ae0ded7d-30c7-5688-a222-d01865906d9b', 3, 21, 'አባቱም በሄደበት መንገድ ሁሉ ሄደ፤ አባቱም ያመለካቸውን ጣዖታት አመለከ፥ ሰገደላቸውም።'),
  ('99851181-0da5-5aaa-a122-b3b6d815b628', 'a0124273-abbc-5873-a29e-480683469a9f', 'ae0ded7d-30c7-5688-a222-d01865906d9b', 4, 22, 'የአባቶቹንም አምላክ እግዚአብሔርን ተወ፥ በእግዚአብሔርም መንገድ አልሄደም።'),
  ('53eeb9aa-1e4e-5956-a973-5ad7f0b27081', 'a0124273-abbc-5873-a29e-480683469a9f', 'ae0ded7d-30c7-5688-a222-d01865906d9b', 5, 23, 'የአሞጽም ብላቴኖች አሴሩበት፤ ንጉሡንም በቤቱ ውስጥ ገደሉት።'),
  ('90035d51-6e11-5c06-a0fa-7acdd2d4e93c', 'a0124273-abbc-5873-a29e-480683469a9f', 'ae0ded7d-30c7-5688-a222-d01865906d9b', 6, 24, 'የሀገሩ ሕዝብ ግን በንጉሡ በአሞጽ ላይ ያሴሩትን ሁሉ ገደሉ፤ የሀገሩም ሕዝብ ልጁን ኢዮስያስን በእርሱ ፋንታ አነገሡት።'),
  ('fa79a1fa-d4ab-5eb2-a0a0-bf4bc4181d35', 'a0124273-abbc-5873-a29e-480683469a9f', 'ae0ded7d-30c7-5688-a222-d01865906d9b', 7, 25, 'የአሞጽም የቀረው ነገርና የሠራው ሥራ ሁሉ፥ እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('335185e9-ed12-59a4-abdd-b086a285d307', 'a0124273-abbc-5873-a29e-480683469a9f', 'ae0ded7d-30c7-5688-a222-d01865906d9b', 8, 26, 'በዖዛም የአትክልት ቦታ ባለው መቃብሩ ቀበሩት፤ ልጁም ኢዮስያስ በእርሱ ፋንታ ነገሠ።'),
  ('98bac0c7-67a1-5eef-aa7b-6d25f9afc67a', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '270d4373-0ab4-59d5-a8f5-884f46f73c51', 1, 1, 'ኢዮስያስም መንገሥ በጀመረ ጊዜ የስምንት ዓመት ልጅ ነበረ፤ በኢየሩሳሌምም ሠላሳ አንድ ዓመት ነገሠ፤ እናቱም ከባሱሮት የሆነ የአዳያ ልጅ ይዲያ ነበረች።'),
  ('c49ee773-09ce-5d50-a98f-c7665db53682', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '270d4373-0ab4-59d5-a8f5-884f46f73c51', 2, 2, 'በእግዚአብሔርም ፊት ቅን ነገርን አደረገ፤ በአባቱም በዳዊት መንገድ ሁሉ ሄደ፤ ቀኝም ግራም አላለም።'),
  ('b902dd51-ba94-557c-a312-c537f46fae25', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '270d4373-0ab4-59d5-a8f5-884f46f73c51', 3, 3, 'በንጉሡም በኢዮስያስ በዐሥራ ስምንተኛው ዓመተ መንግሥት በስምንተኛው ወር ንጉሡ የእግዚአብሔርን ቤት ጸሓፊ የሜሱላምን ልጅ የኤሴልዩን ልጅ ሳፋንን እንዲህ ሲል ላከው፦'),
  ('306d8ef1-1521-5b17-ab69-c3c37e803564', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '270d4373-0ab4-59d5-a8f5-884f46f73c51', 4, 4, '“ወደ ታላቁ ካህን ወደ ኬልቅዩ ወጥተህ ደጃፉን የሚጠብቁ ከሕዝቡ የሰበሰቡትን ወደ እግዚአብሔር ቤት የገባውን ወርቅ ቍጠር።'),
  ('eb784429-10ee-580d-a9de-9f48484d6a97', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '270d4373-0ab4-59d5-a8f5-884f46f73c51', 5, 5, 'በእግዚአብሔርም ቤት ላሉት ሠራተኞች አለቆች ይስጡት፤ እነርሱም የተናደውን የእግዚአብሔርን ቤት ለሚጠግኑት ሠራተኞች፥'),
  ('10983cb0-cf51-566a-a864-8a0ec5f6ff14', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '270d4373-0ab4-59d5-a8f5-884f46f73c51', 6, 6, 'ለአናጢዎችና ለጠራቢዎች፥ ለድንጋይም ወቃሪዎች፥ መቅደሱንም ለመጠገን እንጨትንና የተወቀረውን ድንጋይ ለሚገዙ ይክፈሉት።”'),
  ('079fece7-4127-51ea-afec-039ec33bcfec', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '270d4373-0ab4-59d5-a8f5-884f46f73c51', 7, 7, 'ነገር ግን እነርሱ በእምነት ይሠሩ ነበርና የሰጡአቸውን ገንዘብ አይቈጣጠሩአቸውም ነበር።'),
  ('134ca5ee-27bc-5280-aafe-1c3a038c8168', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 1, 8, 'ታላቁ ካህንም ኬልቅያስ ጸሓፊውን ሳፋንን፥ “የሕጉን መጽሐፍ በእግዚአብሔር ቤት አግኝቻለሁ” አለው፤ ኬልቅያስም መጽሐፉን ለሳፋን ሰጠው፥ እርሱም አነበበው።'),
  ('e25b7f0a-c30c-52ab-a385-6ca86c079fe3', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 2, 9, 'ጸሓፊውም ሳፋን ወደ ንጉሡ መጣ፤ ለንጉሡም፥ “በመቅደሱ የተገኘውን ገንዘብ አገልጋዮችህ አፈሰሱት፥ የእግዚአብሔርንም ቤት ሥራ ለመሥራት ለተመደቡት ሰዎች ሰጡት” ብሎ ነገረው።'),
  ('a2fde1bd-97bc-5729-a231-fd5865f7a135', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 3, 10, 'ጸሓፊው ሳፋንም ለንጉሡ፥ “ካህኑ ኬልቅያስ የሕግ መጽሐፍ ሰጥቶኛል” ብሎ ነገረው። ሳፋንም በንጉሡ ፊት አነበበው።'),
  ('892fac76-a3e7-5468-a8a0-4423009ce424', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 4, 11, 'ንጉሡም የሕጉን መጽሐፍ ቃል በሰማ ጊዜ ልብሱን ቀደደ።'),
  ('a7d140ff-941f-5bef-af2e-4c23f9182309', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 5, 12, 'ንጉሡም ካህኑን ኬልቅያስን፥ የሳፋንንም ልጅ አኪቃምን፥ የሚክዩንም ልጅ ዓክቦርን፥ ጸሓፊውንም ሳፋንን፥ የንጉሡንም ብላቴና ዓስያን እንዲህ ብሎ አዘዛቸው፦'),
  ('0a3ee6f5-6dc4-549c-a80b-dcdd18b67a3b', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 6, 13, '“አባቶቻችን በእርስዋ የተጻፈውን ሁሉ ይሠሩ ዘንድ የዚህችን መጽሐፍ ቃል ስላልሰሙ በላያችን የነደደ የእግዚአብሔር ቍጣ እጅግ ነውና ሄዳችሁ ስለ እኔና ስለ ሕዝቡ ስለ ይሁዳም ሁሉ ስለዚችም ስለተገኘችው መጽሐፍ ቃል ሁሉ እግዚአብሔርን ጠይቁ።'),
  ('2f1af357-49a2-586a-ade1-086c62cccad0', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 7, 14, 'እንዲሁም ካህኑ ኬልቅያስና አኪቃም ዓክቦርም ሳፋንና ዓሳያም ወደ ልብስ ጠባቂው ወደ ሓስራ ልጅ ወደ ቴቁዋ ልጅ ወደ ሴሌም ሚስት ወደ ነቢዪቱ ወደ ሕልዳና ሄዱ፤ እርስዋም በዚያ በኢየሩሳሌም በሁለተኛው ክፍል ተቀምጣ ነበር፤ ለእርስዋም ነገሩአት።'),
  ('af5d1432-1d91-59f0-ae57-c7e249602bf1', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 8, 15, 'እርስዋም አለቻቸው፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ወደ እኔ ለላካችሁ ሰው እንዲህ ብላችሁ ንገሩት፦'),
  ('08e5bcfd-c05d-581b-ab6f-9ac1fcdc532d', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 9, 16, 'እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ የይሁዳ ንጉሥ እንዳነበበው እንደዚህ መጽሐፍ ቃል ሁሉ በዚህ ስፍራና በሚኖሩበት ላይ ክፉ ነገር አመጣለሁ።'),
  ('00d1c9f5-bf35-55ae-acd3-2cdb78517b97', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 10, 17, 'በእጃችሁ ሥራ ሁሉ ታስቈጡኝ ዘንድ ትታችሁኛልና፥ ለሌሎች አማልክትም ዐጥናችኋልና ቍጣዬ በዚህ ስፍራ ላይ ይነድዳል፥ አይጠፋምም።'),
  ('b2f87c6c-d30d-56b7-aef1-49c6c230c86e', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 11, 18, 'እግዚአብሔርን ለመጠየቅ ለላካችሁ ለይሁዳ ንጉሥ ግን እንዲህ በሉት፦ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ስለ ሰማኸው ቃል፥'),
  ('17d9d1ca-4c1b-5e4b-a3ce-53df5821c9c5', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 12, 19, 'ልብህን አላደነደንህምና፥ እነርሱም ለጥፋትና ለመርገም እንዲሆኑ በዚህ ስፍራና በሚኖሩበት ላይ የተናገርሁትን ሰምተህ በእግዚአብሔር ፊት ተዋርደሃልና፥ ልብስህን ቀድደሃልና፥ በፊቴም አልቅሰሃልና እኔ ደግሞ ሰምቼሃለሁ ይላል እግዚአብሔር።'),
  ('67bf52e6-d426-5958-a532-b06a2a4323d8', '83c3e4dd-f8e8-5b40-ab95-5529c352439a', '96bc3404-c3ff-5fec-a586-f7f67189ea13', 13, 20, 'ነገሩ እንደዚህ አይደለም፤ ወደ አባቶችህ እሰበስብሃለሁ፥ በሰላምም ወደ መቃብርህ ትሰበሰባለህ፤ በዚህም ስፍራና በሚኖሩበት ላይ የማመጣውን ክፉ ነገር ዐይኖችህ አያዩም።” ይህንም ለንጉሡ ነገሩት።'),
  ('c110bae3-bdaa-5d5a-ad7b-8387bed9ad3c', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 1, 1, 'ንጉሡም ላከ፤ የይሁዳንና የኢየሩሳሌምንም ሽማግሌዎች ሁሉ ወደ እርሱ ሰበሰባቸው።'),
  ('3934795f-ec91-55e7-a148-2003ef0eef3a', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 2, 2, 'ንጉሡም ወደ እግዚአብሔር ቤት ወጣ፤ ከእርሱም ጋር የይሁዳ ሰዎች ሁሉ፥ በኢየሩሳሌምም የሚኖሩ ሁሉ፥ ካህናቱና ነቢያቱም፥ ሕዝቡም ሁሉ ከታናሾቹ ጀምሮ እስከ ታላቆቹ ድረስ ወጡ፤ በእግዚአብሔርም ቤት የተገኘውን የቃል ኪዳኑን መጽሐፍ ቃል ሁሉ በጆሮአቸው አነበበ።'),
  ('78486afc-9863-5a90-a8f1-046eaa3871bb', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 3, 3, 'ንጉሡም በዓምደ ወርቁ አጠገብ ቆሞ እግዚአብሔርን ይከተሉ ዘንድ፥ ትእዛዙንና ምስክሩንም ሥርዐቱንም በፍጹም ልባቸውና በፍጹም ነፍሳቸው ይጠብቁ ዘንድ፥ በዚህም መጽሐፍ የተጻፈውን የቃል ኪዳን ቃል ያጸኑ ዘንድ በእግዚአብሔር ፊት ቃል ኪዳን አደረገ፤ ሕዝቡም ሁሉ በቃል ኪዳን ጸኑ።'),
  ('56718184-8d40-5b8a-ac53-70a7429a7be7', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 4, 4, 'ንጉሡም የካህናቱን አለቃ ኬልቅያስን በሁለተኛውም መዓርግ ያሉትን ካህናት በረኞቹንም፥ ለበዓልና ለማምለኪያ ዐፀድ ለሰማይም ሠራዊት ሁሉ የተሠሩትን ዕቃዎች ሁሉ ከእግዚአብሔር መቅደስ ያወጡ ዘንድ አዘዛቸው፤ ከኢየሩሳሌምም ውጭ በቄድሮን ሜዳ አቃጠሉት፤ አመዱንም ወደ ቤቴል ወሰዱት።'),
  ('5a525292-c0a9-5630-a77c-c6bd2c498a1f', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 5, 5, 'የይሁዳ ነገሥታትም በይሁዳ ከተሞች በነበሩት በኮረብታው መስገጃዎች፥ በኢየሩሳሌምም ዙሪያ ባሉ መስገጃዎች ያጥኑ ዘንድ ያኖሩአቸውን የጣዖቱን ካህናት፥ ለበዓልና ለፀሐይ፥ ለጨረቃና ለከዋክብት ለሰማይም ሠራዊት ሁሉ ያጥኑ የነበሩትን አቃጠላቸው።'),
  ('2d7c9bb3-e989-5607-a263-b3f31ddd5628', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 6, 6, 'የማምለኪያ ዐፀድንም ጣዖት ከእግዚአብሔር ቤት ወደ ኢየሩሳሌም ውጭ ወደ ቄድሮን ፈፋ አወጣው፤ በቄድሮንም ፈፋ አጠገብ አቃጠለው፤ አድቅቆም ትቢያ አደረገው፥ ትቢያውንም በሕዝብ መቃብር ላይ ጨመረው።'),
  ('c27cc4d0-a93f-5060-afb4-e087755b52f8', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 7, 7, 'ሴቶቹም ለማምለኪያ ዐፀድ መጋረጃ ይፈትሉባቸው የነበሩትን በእግዚአብሔር ቤት ውስጥ ያሉትን የሰዶማውያንን ቤቶች አፈረሰ።'),
  ('6945c0f0-3c78-5364-a6b5-462102ac7fdd', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 8, 8, 'ካህናቱንም ሁሉ ከይሁዳ ከተሞች አወጣቸው፤ ከጌባልም ጀምሮ እስከ ቤርሳቤህ ድረስ ካህናት ያጥኑበት የነበረውን የኮረብታ መስገጃ ሁሉ ርኩስ አደረገው። በከተማዪቱም በር በግራ በኩል በነበረው በከተማዪቱ ሹም በኢያሱ በር መግቢያ አጠገብ የነበሩትን የበሮቹን መስገጃዎች አፈረሰ።'),
  ('0937b3c3-e600-5a84-a35e-c027f3569360', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 9, 9, 'የኮረብታው መስገጃዎች ካህናት ግን በኢየሩሳሌም ወዳለው ወደ እግዚአብሔር መሠዊያ አይመጡም ነበር፤ ብቻ በወንድሞቻቸው መካከል ቂጣ እንጀራ ይበሉ ነበር።'),
  ('ade876c2-5754-59ee-a03c-21dd7978e740', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 10, 10, 'ሰው ሁሉ ወንድ ልጁን ወይም ሴት ልጁን ለሞሎክ በእሳት እንዲሠዋ በሄኖም ልጅ ሸለቆ ቆሞ የነበረውን ጣፌትን ርኩስ አደረገው።'),
  ('5d84e016-38fd-5f3a-a76e-f9add5f18aeb', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 11, 11, 'የይሁዳም ነገሥታት በእግዚአብሔር ቤት መግቢያ አጠገብ በከተማው አቅራቢያ በነበረው በንጉሡ ጃንደረባ በናታን መኖሪያ አጠገብ ለፀሐይ የሰጡአቸውን ፈረሶች አቃጠለ፤ የፀሐይንም ሰረገሎች በእሳት አቃጠለ።'),
  ('e955f836-43ca-52c4-a35f-c299f1a7a988', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 12, 12, 'የይሁዳም ነገሥታት ያሠሩትን በአካዝ ቤት ሰገነት ላይ የነበሩትን መሠዊያዎች፥ ምናሴም ያሠራውን በእግዚአብሔር ቤት በሁለቱ ወለሎች ላይ የነበሩትን መሠዊያዎች ንጉሡ አስፈረሳቸው፤ ከዚያም አወረዳቸው፤ አደቀቃቸውም፥ ትቢያቸውንም በቄድሮን ፈፋ ጣለ።'),
  ('24a73296-24bb-5045-ac66-f1ab589bad2b', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 13, 13, 'በኢየሩሳሌምም ፊት ለፊት በርኵስት ተራራ ቀኝ የነበሩትን፥ የእስራኤል ንጉሥ ሰሎሞን ለሲዶናውያን ርኵስት ለአስታሮት፥ ለሞዓብም ርኵሰት ለካሞሽ፥ ለአሞንም ልጆች ርኵሰት ለሞሎክ ያሠራቸውን መስገጃዎች ንጉሡ ርኩስ አደረገ።'),
  ('24866103-7890-5b48-a74f-aa1acc995d0b', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 14, 14, 'ሐውልቶቹንም ሁሉ አደቀቀ፥ የማምለኪያ ዐፀዶቹንም ሁሉ ቈረጠ፤ በስፍራቸውም የሙታንን አጥንት ሞላበት።'),
  ('ebfb6f0d-0547-51c5-a4e6-2e696f5a0bc4', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 15, 15, 'ደግሞም በቤቴል ኮረብታ የነበረውን መሠዊያ፥ እስራኤልንም ያሳተ የናባጥ ልጅ ኢዮርብዓም ያሠራውን የኮረብታውን መስገጃ፥ ይህንም መሠዊያና መስገጃ አፈረሰ፤ ድንጋዮቹንም ሰባበረ፤ አድቅቆም ትቢያ አደረገው፤ የማምለኪያ ዐፀዱንም አቃጠለው።'),
  ('7fa48ef3-a47c-5fd7-a71a-c355c7840701', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 16, 16, 'ኢዮስያስም ዘወር ብሎ በከተማው የነበሩትን መቃብሮች አየ፤ ኢዮርብዓምም በበዓል ጊዜ የእግዚአብሔር ሰው እንደ ተናገረው እንደ እግዚአብሔር ቃል፥ ልኮ ከመቃብሮቹ አጥንቶቹን አስወጣ፥ በመሠዊያው ላይም አቃጠላቸው፥ አረከሰውም። ዘወርም ብሎ ይህን ቃል ወደ ተናገረው ወደ እግዚአብሔር ሰው መቃብር ዐይኖቹን አቀና። እንዲህም አለ፦'),
  ('7e86f27d-10df-5ba5-a7ed-5d03bb31896b', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 17, 17, '“ይህ የማየው የተቀበረ ነገር ምንድን ነው?” አለ የዚያችም ከተማ ሰዎች፥ “ከይሁዳ መጥቶ በቤቴል መሠዊያ ላይ ይህን ያደረግኸውን ነገር የተናገረው የእግዚአብሔር ሰው መቃብር ነው” ብለው ነገሩት።'),
  ('fa621939-fe49-5873-a61f-d1ba71311af1', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 18, 18, 'እርሱም፥ “ተዉት፥ ማንም አጥንቱን አያንቀሳቅሰው” አለ፤ አጥንቶቹም ከሰማርያ ከመጣው ከነቢዩ አጥንት ጋር ዳኑ።'),
  ('4d66df90-209d-583e-a163-9b3e24085a59', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 19, 19, 'በሰማርያም ከተሞች የነበሩትን፥ እግዚአብሔርን ያስቈጡት ዘንድ የእስራኤል ነገሥታት የሠሩትን የኮረብታውን መስገጃዎች ኢዮስያስ አስወገዳቸው፤ በቤቴልም እንዳደረገው ነገር ሁሉ እንዲሁ አደረገባቸው።'),
  ('03c3a3f3-f4b4-5a9f-a6f5-a9baf992bbe7', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'f3defead-63c9-5b21-a41b-5a6be1098693', 20, 20, 'በዚያም የነበሩትን የኮረብታውን መስገጃዎች ካህናት ሁሉ በመሠዊያዎቹ ላይ ገደላቸው፥ የሰዎቹንም አጥንት በመሠዊያዎቹ ላይ አቃጠለ። ወደ ኢየሩሳሌምም ተመለሰ።'),
  ('c18b4288-47a2-5a13-a350-648fd09e7585', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 1, 21, 'ንጉሡም ሕዝቡን ሁሉ፥ “በዚህ በቃል ኪዳኑ መጽሐፍ እንደ ተጻፈው ለአምላካችሁ ለእግዚአብሔር ፋሲካን አድርጉ” ብሎ አዘዛቸው።'),
  ('ff4ecdd3-4eb9-5751-a8e5-85a552f2b6b5', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 2, 22, 'እንደዚህም ያለ ፋሲካ በእስራኤል ላይ ይፈርዱ ከነበሩ ከመሳፍንት ዘመን ጀምሮ በእስራኤልና በይሁዳ ነገሥታት ዘመን ሁሉ አልተደረገም።'),
  ('761ad297-2f33-5a0f-abb1-64cf3b8ab598', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 3, 23, 'ነገር ግን በይሁዳ ንጉሥ በኢዮስያስ በዐሥራ ስምንተኛው ዓመት ይህ ፋሲካ በኢየሩሳሌም ለእግዚአብሔር ተደረገ።'),
  ('e7467d26-bfe4-57f0-acf0-626c52cbe5c9', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 4, 24, 'ደግሞም ካህኑ ኬልቅያስ በእግዚአብሔር ቤት ባገኘው መጽሐፍ የተጻፈውን የሕጉን ቃል ያጸና ዘንድ፥ መናፍስት ጠሪዎቹንና ጠንቋዮቹን ተራፊምንና ጣዖታትንም በይሁዳ ሀገርና በኢየሩሳሌም የተገኘውን ርኵሰት ሁሉ ኢዮስያስ አስወገደ።'),
  ('646f90de-1ba5-53f4-a77f-f5f26fd949b7', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 5, 25, 'እንደ ሙሴም ሕግ ሁሉ በፍጹም ልቡ በፍጹምም ነፍሱ በፍጹምም ኀይሉ ወደ እግዚአብሔር የተመለሰ እንደ እርሱ ያለ ንጉሥ ከእርሱ አስቀድሞ አልነበረም፤ እንደ እርሱም ያለ ንጉሥ ከእርሱ በኋላ አልተነሣም።'),
  ('241f2dcb-3d33-5733-a1b9-d510cba17d28', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 6, 26, 'ነገር ግን ምናሴ ስላስቈጣው ነገር ሁሉ እግዚአብሔር በይሁዳ ላይ ከነደደው ከታላቁ ቍጣው ትኵሳት አልተመለሰም።'),
  ('9cc74d84-d162-5d33-a5e8-f37ea31a6077', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 7, 27, 'እግዚአብሔርም፥ “እስራኤልን እንዳራቅሁት ይሁዳን ከፊቴ አርቀዋለሁ፤ ይህችንም የመረጥኋትን ከተማ ኢየሩሳሌምንና፦ ስሜ በዚያ ይሆናል ያልሁትንም ቤት እጥላለሁ” አለ።'),
  ('93863437-cae1-5b1a-a104-bb71c8350569', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 8, 28, 'የቀረውም የኢዮስያስ ነገር፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('0c9468d9-3c40-5c14-a7fa-aebfad44389f', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 9, 29, 'በእርሱም ዘመን የግብፅ ንጉሥ ፈርዖን ኒካዑ ከአሦር ንጉሥ ጋር ሊጋጠም ወደ ኤፍራጥስ ወንዝ ወጣ፤ ንጉሡም ኢዮስያስ ከእርሱ ጋር ሊጋጠም ወጣ፤ ፈርዖንም በተገናኘው ጊዜ በመጊዶ ገደለው።'),
  ('214cc4db-beb5-5ffa-ad54-aa1316811564', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', '85fbc566-bacc-5e79-a835-b14b810e0c0b', 10, 30, 'አገልጋዮቹም በድኑን በሰረገላው አድርገው ከመጊዶ ወደ ኢየሩሳሌም አመጡት፤ በመቃብሩም ቀበሩት። የሀገሩም ሰዎች የኢዮስያስን ልጅ ዮአክስን ወሰዱት። ቀብተውም በአባቱ ፋንታ አነገሡት።'),
  ('64569dcd-0cc3-5524-a38f-b596f69fa8e9', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'e509add8-8c4f-5d6e-ace0-eb57fe438148', 1, 31, 'ዮአክስም በነገሠ ጊዜ ሃያ ሦስት ዓመት ሆኖት ነበረ፤ በኢየሩሳሌምም ሦስት ወር ነገሠ። እናቱም አሚጣል ትባል ነበር፥ እርስዋም የሎብና ሰው የኤርምያስ ልጅ ነበረች።'),
  ('a46f07c6-5378-57c9-a5cd-226f293da293', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'e509add8-8c4f-5d6e-ace0-eb57fe438148', 2, 32, 'እርሱም አባቶቹ እንደ አደረጉ ሁሉ በእግዚአብሔር ፊት ክፉ አደረገ።'),
  ('76012032-d99a-5dff-ae43-9c8d670945d9', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'e509add8-8c4f-5d6e-ace0-eb57fe438148', 3, 33, 'በኢየሩሳሌምም እንዳይነግሥ ፈርዖን ኒካዑ በኤማት ምድር ባለችው በዴብላታ አሰረው፤ በምድሩም ላይ መቶ መክሊት ብርና አንድ መቶ መክሊት ወርቅ ፈሰሴ ጣለበት።'),
  ('858e40d0-682f-5dcb-a4ac-1e2c2e812b3a', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'e509add8-8c4f-5d6e-ace0-eb57fe438148', 4, 34, 'ፈርዖን ኒካዑም የይሁዳ ንጉሥ የኢዮስያስን ልጅ ኤልያቄምን በአባቱ በኢዮስያስ ፋንታ አነገሠ፤ ስሙንም ኢዮአቄም ብሎ ለወጠው። ዮአክስንም ወስዶ ወደ ግብፅ አፈለሰው፤ በዚያም ሞተ።'),
  ('59f9ea83-f6b1-5664-ae3e-8adb59de1806', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'e509add8-8c4f-5d6e-ace0-eb57fe438148', 5, 35, 'ኢዮአቄምም ብሩንና ወርቁን ለፈርዖን ሰጠው፤ እንደ ፈርዖንም ትእዛዝ ገንዘብ ይሰጥ ዘንድ ምድሩን አስገበረ፤ ለፈርዖን ኒካዑም ግብር ይሰጥ ዘንድ ከሀገሩ ሕዝብ ሁሉ እንደ ግምጋሜው ብርና ወርቅ አስከፈለ።'),
  ('4dcfaff8-600e-5a6d-a557-c1f7ba1fa624', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'd44af8ec-f342-5659-a01c-1a1b6e1d15fc', 1, 36, 'ኢዮአቄምም በነገሠ ጊዜ ሃያ አምስት ዓመት ሆኖት ነበረ፤ በኢየሩሳሌምም ዐሥራ አንድ ዓመት ነገሠ፤ እናቱም ሄልድፍ ትባል ነበር፤ እርስዋም የሩማ ሰው የፈዳያ ልጅ ነበረች።'),
  ('5d840eb1-8884-5083-a051-82c63503ea9a', 'b2f72aea-53db-5f6a-a166-a3b310fa911e', 'd44af8ec-f342-5659-a01c-1a1b6e1d15fc', 2, 37, 'አባቶቹም እንዳደረጉ ሁሉ በእግዚአብሔር ፊት ክፉ አደረገ።'),
  ('0e5f0072-f82f-5d0a-aa95-751fc9a28007', 'a836965c-ed80-5787-ad45-84739230b236', '9d586bca-cc5d-514d-ad62-198e1c11a5ba', 1, 1, 'በእርሱም ዘመን የባቢሎን ንጉሥ ናቡከደነፆር ወጣ፤ ኢዮአቄምም ሦስት ዓመት ተገዛለት፤ ከዚያም በኋላ ዘወር አለና ዐመፀበት።'),
  ('4902013f-3cdf-59a9-a604-bfd28c70b1ff', 'a836965c-ed80-5787-ad45-84739230b236', '9d586bca-cc5d-514d-ad62-198e1c11a5ba', 2, 2, 'እግዚአብሔርም የከለዳውያንን አደጋ ጣዮች፥ የሶርያውያንንም አደጋ ጣዮች፥ የሞዓባውያንንም አደጋ ጣዮች፥ የአሞንንም ልጆች አደጋ ጣዮች ሰደደበት፤ በባሪያዎቹ በነቢያት ቃል እንደ ተናገረው እንደ እግዚአብሔር ቃል ያጠፉት ዘንድ በይሁዳ ላይ ሰደዳቸው።'),
  ('f7c84625-b62e-5459-a394-5cdb6b66d9a4', 'a836965c-ed80-5787-ad45-84739230b236', '9d586bca-cc5d-514d-ad62-198e1c11a5ba', 3, 3, 'ምናሴም ስላደረገው ኀጢአት ሁሉ ከፊቱ ያርቀው ዘንድ የእግዚአብሔር ቍጣ በይሁዳ ላይ ሆነ፤'),
  ('8b576691-a694-5707-a7d6-9838af859b3c', 'a836965c-ed80-5787-ad45-84739230b236', '9d586bca-cc5d-514d-ad62-198e1c11a5ba', 4, 4, 'ጻድቁንም ስለ ገደለ ኢየሩሳሌምንም በንጹሕ ደም ስለ ሞላ እግዚአብሔር ይራራ ዘንድ አልወደደም።'),
  ('ea81f7e0-1af2-51d8-a826-213cd91f6e64', 'a836965c-ed80-5787-ad45-84739230b236', '9d586bca-cc5d-514d-ad62-198e1c11a5ba', 5, 5, 'የቀረውም የኢዮአቄም ነገር፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('12dc37fa-3107-5c44-ae20-a9981551b195', 'a836965c-ed80-5787-ad45-84739230b236', '9d586bca-cc5d-514d-ad62-198e1c11a5ba', 6, 6, 'ኢዮአቄምም ከአባቶቹ ጋር አንቀላፋ፤ በኦዛም የአትክልት ቦታ ተቀበረ ልጁም ዮአኪን በእርሱ ፋንታ ነገሠ።'),
  ('c26255f9-8556-5884-a771-bfed2fc5dc4b', 'a836965c-ed80-5787-ad45-84739230b236', '9d586bca-cc5d-514d-ad62-198e1c11a5ba', 7, 7, 'የባቢሎንም ንጉሥ ለግብፅ ንጉሥ የነበረውን ሁሉ ከግብፅ ወንዝ ጀምሮ እስከ ኤፍራጥስ ወንዝ ድረስ ወስዶ ነበርና የግብፅ ንጉሥ ከዚያ ወዲህ ከሀገሩ አልወጣም።'),
  ('629bd403-9f60-529b-ad54-60b153d4786b', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 1, 8, 'ዮአኪንም በነገሠ ጊዜ ዐሥራ ስምንት ዓመት ሆኖት ነበረ፤ በኢየሩሳሌምም ሦስት ወር ነገሠ፤ እናቱም ኒስታ ትባል ነበር፤ እርስዋም የኢየሩሳሌም ሰው የኤልናታን ልጅ ነበረች።'),
  ('2c4ab4a9-7a15-5ade-aa0b-babc4a9047ce', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 2, 9, 'አባቶቹም እንዳደረጉ ሁሉ በእግዚአብሔር ፊት ክፉ አደረገ።'),
  ('58d1bc3b-1459-5bf3-aa0c-1b1b1f40ac9d', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 3, 10, 'በዚያም ወራት የባቢሎን ንጉሥ የናቡከደነፆር ሠራዊት ወደ ኢየሩሳሌም ወጡ፤ ከተማዪቱም ተከበበች።'),
  ('1d83eb5b-966c-59e1-ace4-89d9147a79eb', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 4, 11, 'የባቢሎን ንጉሥ ናቡከደነፆርም ወደ ከተማዪቱ መጣ። ሠራዊቱም ከበቡአት።'),
  ('21aa8198-3f4f-5373-a31a-8f8ffedf01e3', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 5, 12, 'የይሁዳም ንጉሥ ዮአኪን ከእናቱ፥ ከብላቴኖቹም፥ ከአለቆቹም፥ ከጃንደረቦቹም ጋር ወደ ባቢሎን ንጉሥ ወጣ፤ የባቢሎንም ንጉሥ በነገሠ በስምንተኛው ዓመት ያዘው።'),
  ('89fea3eb-b4f6-5f10-af91-d62690c99d18', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 6, 13, 'የእግዚአብሔርን ቤተ መዛግብት ሁሉ የንጉሡንም ቤተ መዛግብት ከዚያ አወጣ፤ እግዚአብሔርም እንደ ተናገረው የእስራኤል ንጉሥ ሰሎሞን ለእግዚአብሔር መቅደስ የሠራውን የወርቁን ዕቃ ሁሉ ሰባበረ።'),
  ('caf15305-388f-5a43-add4-e52d7847e096', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 7, 14, 'ኢየሩሳሌምንም አጠፋት፥ አለቆቹንም ሁሉ፥ ጽኑዓኑንና ኀያላኑን ሁሉ፥ ጠራቢዎቹንም ሁሉ፥ ብረት ሠራተኞቹንም ሁሉ ዐሥር ሺህ ምርኮኞችን ሁሉ አፈለሰ፤ ከሀገሩ ድሆች በቀር ማንም አልቀረም።'),
  ('a7693134-2b31-5ac3-af49-007d04e0e7bf', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 8, 15, 'ዮአኪንንም ወደ ባቢሎን አፈለሰ፤ የንጉሡንም እናት፥ የንጉሡንም ሚስቶች፥ ጃንደረቦቹንም፥ የሀገሩንም ታላላቆች ከኢየሩሳሌም ወደ ባቢሎን ማረከ።'),
  ('c439003b-72de-54b4-a34e-b698a80d7a2a', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 9, 16, 'የባቢሎንም ንጉሥ ሰባት ሺህ ያህል፥ ብርቱዎችንና ሰልፍ የሚችሉትን ሁሉ፥ ኀያላኑን ሁሉ አንድ ሺህ የሚሆኑ ጠራቢዎችንና ብረት ሠራተኞችንም ወደ ባቢሎን ማረከ።'),
  ('6908821a-2737-5b0e-a373-66c1e857c43f', 'a836965c-ed80-5787-ad45-84739230b236', '02a42070-cb73-5a32-a3d0-d126b00f68c6', 10, 17, 'የባቢሎንም ንጉሥ የዮአኪንን አጎት ማታንያን በእርሱ ፋንታ አነገሠ፤ ስሙንም ሴዴቅያስ ብሎ ለወጠው።'),
  ('230695b8-fbef-5f21-a6ff-25abf2526296', 'a836965c-ed80-5787-ad45-84739230b236', 'a51fb598-bba8-5354-a737-f7e1a1515415', 1, 18, 'ሴዴቅያስም በነገሠ ጊዜ ሃያ አንድ ዓመት ሆኖት ነበረ፤ በኢየሩሳሌምም ዐሥራ አንድ ዓመት ነገሠ፤ እናቱም አሚጣል የተባለች የሎብና ሰው የኤርምያስ ልጅ ነበረች።'),
  ('0f641d0f-77dd-5e4c-acc0-96c06f428de1', 'a836965c-ed80-5787-ad45-84739230b236', 'a51fb598-bba8-5354-a737-f7e1a1515415', 2, 19, 'ኢዮአቄምም እንዳደረገው ሁሉ በእግዚአብሔር ፊት ክፉ አደረገ።'),
  ('d962ed55-89db-5c1b-a091-5dd0014fcef6', 'a836965c-ed80-5787-ad45-84739230b236', 'a51fb598-bba8-5354-a737-f7e1a1515415', 3, 20, 'ከፊቱ አውጥቶ እስኪጥላቸው ድረስ ይህ ነገር በእግዚአብሔር ቍጣ በኢየሩሳሌምና በይሁዳ ላይ ሆኖአልና፤ ሴዴቅያስም በባቢሎን ንጉሥ ላይ ዐመፀ።'),
  ('853bc263-79a8-5933-abea-6c9f5189538b', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 1, 1, 'ሴዴቅያስም በነገሠ በዘጠነኛው ዓመት በዐሥረኛው ወር ከወሩም በዐሥረኛው ቀን የባቢሎን ንጉሥ ናቡከደነፆር ከሠራዊቱ ሁሉ ጋር ወደ ኢየሩሳሌም መጥቶ ሰፈረባት፤ በዙሪያዋም ዕርድ ሠራባት።'),
  ('4374514c-0ff8-55ea-a3ee-5f649f2739e4', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 2, 2, 'ከተማዪቱም እስከ ንጉሡ እስከ ሴዴቅያስ ዐሥራ አንደኛው ዓመተ መንግሥት እስከ አራተኛው ወር እስከ ዘጠነኛው ቀን ድረስ ተከብባ ነበር።'),
  ('7d3e3345-17b4-56a4-abe7-c8fc83801b78', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 3, 3, 'በከተማዪቱም ራብ ጸንቶ ነበርና ለሀገሩ ሰዎች እህል ታጣ።'),
  ('acd331c9-7aaa-50ca-a466-0623ed8ecaf0', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 4, 4, 'ከተማዪቱም ተሰበረች፤ ሰልፈኞችም ሁሉ በሁለት ቅጥር መካከል ባለው በር ወደ ንጉሡ አትክልት በሚወስደው መንገድ በሌሊት ሸሹ፤ ከለዳውያንም በከተማዪቱ ዙሪያ ነበሩ፤ ወደ ምድረ በዳ በሚወስደውም መንገድ ሄዱ።'),
  ('2c05b2ed-1fd3-53d5-ab1a-ddcd14304fb8', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 5, 5, 'የከለዳውያንም ሠራዊት ንጉሡን ተከተሉ፤ በኢያሪኮም በኩል ባለው ሜዳ ያዙት፤ ሠራዊቱም ሁሉ ከእርሱ ተለይተው ተበትነው ነበር።'),
  ('90679f1f-841b-5083-ab3e-574cc8536bcd', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 6, 6, 'ንጉሡንም ይዘው የባቢሎን ንጉሥ ወዳለበት የኢየሩሳሌም ክፍል ወደምትሆን ወደ ዴብላታ ወሰዱት፤ ፍርድም ፈረዱበት።'),
  ('bacabddd-8cdd-5d5f-a20c-36c112e44224', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 7, 7, 'የሴዴቅያስንም ልጆች በፊቱ ገደሉአቸው፤ የሴዴቅያስንም ዐይኖች አወጡ፤ በሰንሰለትም አሰሩት፤ ወደ ባቢሎንም ወሰዱት።'),
  ('04a56d39-7742-5ba7-af9e-cb3f32ec318e', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 8, 8, 'በባቢሎንም ንጉሥ በናቡከደነፆር በዐሥራ ዘጠነኛው ዓመት በአምስተኛው ወር ከወሩም በሰባተኛው ቀን በባቢሎን ንጉሥ ፊት የሚቆመው የአበዛዎች አለቃ ናቡዛርዳን ወደ ኢየሩሳሌም ወጣ።'),
  ('43da383f-0af8-5bd2-ad57-8233f735d7ae', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 9, 9, 'የንጉሡም የአበዛዎች አለቃ የእግዚአብሔርን ቤትና የንጉሡን ቤት አቃጠለ። የኢየሩሳሌምንም ቤቶች ሁሉ በእሳት አቃጠለ።'),
  ('58270ae9-d562-5f9e-ac7e-9a69229908ca', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 10, 10, 'የከለዳውያን ሠራዊት ሁሉ የኢየሩሳሌምን የአንባዋን ቅጥር ዙሪያዋን አፈረሱ።'),
  ('ab0649a1-dffc-5e56-a58c-3a629ef1fa6c', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 11, 11, 'የአበዛዎች አለቃ ናቡዛርዳንም በከተማዪቱ ውስጥ የቀረውን ሕዝብ፥ ሸሽተውም ወደ ባቢሎን ንጉሥ የተጠጉትን፥ የቀሩትንም ሕዝብ ሁሉ ማርኮ ወሰደ።'),
  ('3d7c6334-f12c-57e7-ad39-52356ac10ad5', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 12, 12, 'የአበዛዎችም አለቃ ከሀገሩ ድሆች ወይን ተካዮችና አራሾች እንዲሆኑ አስቀረ።'),
  ('7aa0aaf2-0744-5049-ab5f-d02a37616de6', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 13, 13, 'ከለዳውያንም በእግዚአብሔር ቤት ውስጥ የነበሩትን የናስ ዓምዶች፥ በእግዚአብሔርም ቤት የነበሩትን መቀመጫዎችና የናስ ኵሬዎች ሰባበሩ፤ ናሱንም ወደ ባቢሎን ወሰዱ።'),
  ('6b0717a5-af99-59ce-a6c8-898689764169', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 14, 14, 'ምንቸቶቹንና ማንካዎቹንም፥ መኰስተሪያዎቹንና ጭልፋዎቹንም የሚያገለግሉበትንም የናስ ዕቃ ሁሉ ወሰዱ።'),
  ('3b9c90d7-ca33-557c-a19e-c5ef3e25feed', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 15, 15, 'የአበዛዎች አለቃም ጥናዎቹን ከወርቅና ከብር የተሠሩ መኰስተሪያዎችንም ወሰደ።'),
  ('3336af0f-5287-531f-a328-da6f2c3890c9', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 16, 16, 'ሰሎሞንም ለእግዚአብሔር ቤት የሠራቸውን ሁለቱን ዓምዶች፥ አንዱንም ኵሬ መቀመጫዎቹንም ወሰደ፤ ለእነዚህም ዕቃዎች ሁሉ ናስ ሚዛን አልነበረውም።'),
  ('7aefe547-49e1-5f79-a9c1-c154e4a3c329', '19cf3dd4-afb3-5262-a229-353c8b928653', 'e86dd032-0c0c-5a29-a261-bd3a64f2934c', 17, 17, 'የአንዱም ዓምድ ቁመት ዐሥራ ስምንት ክንድ ነበረ፥ የናስም ጕልላት ነበረበት፤ የጕልላቱም ርዝመት ሦስት ክንድ ነበረ፥ በጕልላቱም ላይ በዙሪያው የናስ መርበብና ሮማኖች ነበሩ፤ እንዲሁም ደግሞ በሁለተኛው ዓምድ ላይ መርበብ ነበረበት።'),
  ('42fe314c-257c-56ca-a58d-2996f933092d', '19cf3dd4-afb3-5262-a229-353c8b928653', 'c37c91be-b914-550e-a710-2da7cecfaed2', 1, 18, 'የአበዛዎችም አለቃ ታላቁን ካህን ሠራያን ሁለተኛውንም ካህን ሶፎንያስን ሦስቱንም በረኞች ማርኮ ወሰደ።'),
  ('47517366-526c-5353-a024-c900d95d0935', '19cf3dd4-afb3-5262-a229-353c8b928653', 'c37c91be-b914-550e-a710-2da7cecfaed2', 2, 19, 'ከከተማዪቱም በሰልፈኞች ላይ ተሾመው ከነበሩት አንዱን ጃንደረባ፥ በከተማዪቱም የተገኙትን በንጉሡ ፊት የሚቆሙትን አምስቱን ሰዎች፥ የሀገሩንም ሕዝብ የሚያሰልፍ የሠራዊቱን አለቃ ጸሓፊ፥ በከተማዪቱም ከተገኙት ከሀገሩ ሕዝብ ስድሳ ሰዎችን ወሰደ።'),
  ('08c487e7-a02e-5d7b-aa6b-23636fdd7db8', '19cf3dd4-afb3-5262-a229-353c8b928653', 'c37c91be-b914-550e-a710-2da7cecfaed2', 3, 20, 'የአበዛዎቹም አለቃ ናቡዛርዳን ማርኮ የባቢሎን ንጉሥ ወዳለበት ወደ ዴብላታ አመጣቸው።'),
  ('4c100893-932f-5c38-a837-0af38f1860e5', '19cf3dd4-afb3-5262-a229-353c8b928653', 'c37c91be-b914-550e-a710-2da7cecfaed2', 4, 21, 'የባቢሎንም ንጉሥ መታቸው፥ በኤማትም ምድር ባለችው በዴብላታ ገደላቸው። እንዲሁም ይሁዳ ከሀገሩ ተማረከ።'),
  ('e25f4234-0941-5e7d-ac0a-44f61e8dff6f', '19cf3dd4-afb3-5262-a229-353c8b928653', 'a0b99bd3-2832-5dd6-a766-81dc64426d89', 1, 22, 'የባቢሎንም ንጉሥ ናቡከደነፆር በይሁዳ ምድር በቀረው ሕዝብ ላይ የሳፋንን ልጅ የአኪቃምን ልጅ ጎዶልያን ሾመው።'),
  ('ef7b4dd4-f0ee-52af-afb7-ce22cacb5bc3', '19cf3dd4-afb3-5262-a229-353c8b928653', 'a0b99bd3-2832-5dd6-a766-81dc64426d89', 2, 23, 'የሠራዊቱም አለቆች ሁሉ ሰዎቻቸውም፥ የናታንዩ ልጅ እስማኤል፥ የቃሬያን ልጅ ዮሐናን፥ የነጦፋዊውም የተንሑሜት ልጅ ሴሪያ፥ የማዕካታዊው ልጅ አዛንያ፥ ሰዎቻቸውም የባቢሎን ንጉሥ ጎዶልያን እንደ ሾመው በሰሙ ጊዜ ወደ ጎዶልያ ወደ መሴፋ መጡ።'),
  ('0b62306f-bf62-5c76-abe7-a69f029eb16a', '19cf3dd4-afb3-5262-a229-353c8b928653', 'a0b99bd3-2832-5dd6-a766-81dc64426d89', 3, 24, 'ጎዶልያም፥ “ከከለዳውያን ሎሌዎች የተነሣ አትፍሩ፤ በሀገሩ ተቀመጡ፤ ለባቢሎንም ንጉሥ ተገዙ፤ መልካምም ይሆንላችኋል” ብሎ ለእነርሱና ለሰዎቻቸው ማለላቸው።'),
  ('64f07faa-ea21-54a5-ac93-8359b5e39ffa', '19cf3dd4-afb3-5262-a229-353c8b928653', 'a0b99bd3-2832-5dd6-a766-81dc64426d89', 4, 25, 'በሰባተኛው ወር ግን የመንግሥት ዘር የነበረ የኤልሴማ ልጅ የናታንዩ ልጅ እስማኤል መጣ፤ ከእርሱም ጋር ዐሥር ሰዎች ነበሩ፤ ጎዶልያንም መታው፤ ሞተም፤ ከእርሱም ጋር በመሴፋ የነበሩትን አይሁድንና ከለዳውያንንም ገደላቸው።'),
  ('909e47ff-7be4-5738-ad8e-d25f629f7672', '19cf3dd4-afb3-5262-a229-353c8b928653', 'a0b99bd3-2832-5dd6-a766-81dc64426d89', 5, 26, 'ከለዳውያንንም ፈርተው ነበርና ከታናሹ ጀምሮ እስከ ታላቁ ድረስ ሕዝቡ ሁሉ፥ የሠራዊቱም አለቆች ተነሥተው ወደ ግብፅ ገቡ።'),
  ('bcf6a68c-4630-56b8-afa2-c7cffb2c283d', '19cf3dd4-afb3-5262-a229-353c8b928653', 'ee613227-7f39-57f6-a2bc-a99dd45067a5', 1, 27, 'እንዲህም ሆነ፤ የይሁዳ ንጉሥ ዮአኪን በተማረከ በሠላሳ ሰባተኛው ዓመት በዐሥራ ሁለተኛው ወር ከወሩም በሃያ ሰባተኛው ቀን የባቢሎን ንጉሥ ዮርማሮዴቅ በነገሠ በአንደኛው ዓመት የይሁዳን ንጉሥ ዮአኪንን ከፍ አደረገው፤ ከወህኒ ቤትም አወጣው፤'),
  ('3fd35d33-b9dd-5daf-a1fe-1bb52df6e3a7', '19cf3dd4-afb3-5262-a229-353c8b928653', 'ee613227-7f39-57f6-a2bc-a99dd45067a5', 2, 28, 'መልካም ነገርንም ተናገረው፥ ዙፋኑንም ከእርሱ ጋር በባቢሎን ከነበሩት ነገሥታት ዙፋን በላይ አደረገለት።'),
  ('070694cb-f11a-5b01-aae4-cb26d7f3c2c1', '19cf3dd4-afb3-5262-a229-353c8b928653', 'ee613227-7f39-57f6-a2bc-a99dd45067a5', 3, 29, 'በወህኒም ውስጥ ለብሶት የነበረውን ልብስ ለወጠለት፤ ዮአኪንም በሕይወቱ ዘመን ሁሉ በፊቱ ሁልጊዜ እንጀራ ይበላ ነበር።'),
  ('958f3f31-c5d5-5405-a898-798b25626eca', '19cf3dd4-afb3-5262-a229-353c8b928653', 'ee613227-7f39-57f6-a2bc-a99dd45067a5', 4, 30, 'ቀለቡንም ሁልጊዜ ከንጉሡ ቤት ይቀበል ነበር፤ በሕይወቱም ዘመን ሁሉ የዘወትር ቀለቡን ዕለት ዕለት ይሰጡት ነበር።'),
  ('7ea80fb4-04f5-59d9-ab2d-511b3b634724', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 1, 1, 'አዳም፥ ሴት፥ ሄኖስ፥'),
  ('ac928303-d06a-5607-a2ea-89b7e6f04e20', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 2, 2, 'ቃይናን፥ መላልኤል፥ ያሬድ፥'),
  ('908bce9a-3553-593d-a7be-1fb3886be27b', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 3, 3, 'ሄኖክ፥ ማቱሳላ፥ ላሜሕ፥'),
  ('ea24ab60-3d72-58cd-aa09-71bec2062c52', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 4, 4, 'ኖኅ፥ ልጆቹም ሴም፥ ካም፥ ያፌት።'),
  ('fe83dd89-2b4e-53ec-a132-d648abd67e70', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 5, 5, 'የያፌት ልጆች ጋሜር፥ ማጎግ፥ ማዳይ፥ ይሕያን፥ ኤልሳ፥ ቶቤል፥ ሞሳሕና ቲራም።'),
  ('367f97af-426c-5994-a408-78b05d24164f', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 6, 6, 'የጋሜርም ልጆች አስካናስ፥ ሪፋት፥ ቶርጋማ።'),
  ('cce0b86d-aece-5aad-a5bc-f6460016e45d', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 7, 7, 'የይሕያ ልጆች ኤልሳ፥ ተርሴስ፥ ኬቲም፥ ሮድኢ።'),
  ('3953cba6-b1e3-5cb5-a787-4467d96156ce', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 8, 8, 'የካምም ልጆች፤ ኩሽ፥ ምስራይም፥ ፉጥ፥ ከነዓን።'),
  ('d0eda070-7aed-53df-ade3-4ec65540e0a2', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 9, 9, 'የኩሽም ልጆች፤ ሳባ፥ ኤውላጥ፥ ሳበታ፥ ሬግማን፥ ሱቦን። የሬግማንም ልጆች፤ ሴባ፥ ዳዳን።'),
  ('aff710cc-06bb-5f0b-af6f-629b87fcc1a2', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 10, 10, 'ኩሽም ናምሩድን ወለደ፤ እርሱም በምድር ላይ አዳኝና ኀያል መሆንን ጀመረ።'),
  ('7f9d126e-9a0b-5a6c-a734-514c17e4e3dc', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 11, 11, 'ምሥራይም ሎዲአምን፥ ዐናኒምን፥ ሎቢንን፥ ንፍታሌምን፥'),
  ('48de3b85-cb87-538f-a789-e1bc768b0d58', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 12, 12, 'ጴጥሮሳኒኤምን፥ ፍልስጥኤማውያን የወጡበትን ከሰሎንኤምን፥ ከፋቱሪምን ወለደ።'),
  ('7f2d2b22-66be-57c7-a3a5-9393064cf737', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 13, 13, 'ከነዓን የበኵር ልጁን ሲዶንን፥ ኬጤዎንን፥'),
  ('27932334-0a51-5099-a3c0-d7ee08d05202', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 14, 14, 'ኤያቡሴዎንን፥ አሞሬዎንን፥ ጌርጌሴዎንን፥'),
  ('067ffd77-6a02-5094-a156-ae7380563edb', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 15, 15, 'አዌዎንን፥ አረቄዎንን፥ ኤሴነዎንን፥'),
  ('d7b9f920-01b9-5e30-a9a6-ff9215372960', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 16, 16, 'አራዴዎንን፥ ሰማሬዎንን፥ አማቲን ወለደ።'),
  ('02549978-efad-5bc8-a758-1dac490ba467', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 17, 17, 'የሴምም ልጆች፤ አይላም፥ አሡር፥ አርፋክስድ፥ ሉድ፥ አራም፥ የአራምም ልጆች፤ ኡስ፥ ዑል፥ ጋቴር፥ ሞሳክ።'),
  ('997de331-e1bd-5cfb-a3e7-790e8c6dd95f', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 18, 18, 'አርፋክስድም ቃይናንን ወለደ፤ ቃይናንም ሳላን ወለደ፤ ሳላም ኤቦርን ወለደ።'),
  ('2098855f-a0fa-5cbc-a38d-b451fa10ac3a', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 19, 19, 'ለኤቦርም ሁለት ልጆች ተወለዱለት፤ በዘመኑ ምድር ተከፋፍላለችና የአንደኛው ስም ፋሌቅ ተባለ፤ የወንድሙም ስም ዮቅጣን ነበረ፤'),
  ('2054259e-1585-5883-a945-afee66e8a0aa', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 20, 20, 'ዮቅጣንም ኤልሞዳድን፥ ሣሌፍን፥ ኤራሞትን፥ ያራሕን፥'),
  ('b6f6f366-5328-5204-af71-e701921736a1', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 21, 21, 'ቄዱራምን፥ ኤዜልን፥ ዲቅላምን፥'),
  ('947e3c07-b55b-57a8-ab7b-d84ce60bcb39', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 22, 22, 'ጌማሄልን፥ ኤልሜሄልን፥ ሳባን፥'),
  ('39643cf1-3c81-56a6-a5a6-cee312f22265', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 23, 23, 'ኦፌርን፥ ሄውላን፥ ኦራምን፥ ዑካብን ወለደ፤ እነዚህ ሁሉ የዮቅጣን ልጆች ነበሩ።'),
  ('62d91a1e-150a-5c1c-a6f4-005c0706ba16', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 24, 24, 'የሴምም ልጆች፤ አይላም፥ አሡር፥ አርፋክስድ፥ ሳላን፥ ቃይናን፥'),
  ('2db204b3-d0d2-5417-af75-69891877662b', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 25, 25, 'ዔቦር፥ ፋሌቅ፥ ራግው፥'),
  ('b14fe856-158c-5b8f-aba8-25153ce423ea', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 26, 26, 'ሴሮሕ፥ ናኮር፥ ታራ፥'),
  ('2ab2f117-028a-51ef-a98f-e079bcd5a324', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '3ab964dd-af2d-5b2a-ad11-2ee6adaf6a30', 27, 27, 'አብርሃም የተባለው አብራም።'),
  ('236a6c7a-be83-5e97-afda-8c6bd7778edb', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '5a8dd016-3386-5231-a93b-9d1085b6a31e', 1, 28, 'የአብርሃምም ልጆች፤ ይስሐቅ፥ ይስማኤል።'),
  ('2ca717bd-49b4-50f5-a3d8-18d6c7f9e6fa', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '5a8dd016-3386-5231-a93b-9d1085b6a31e', 2, 29, 'ትውልዳቸውም እንደዚህ ነው። የይስማኤል በኵር ልጅ ናቢዎት፤ ቄዳር፥ ቢዲሄል፥ ሙባሳን፥'),
  ('37cdca6c-b859-594f-ae17-cc6c136bb9d7', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '5a8dd016-3386-5231-a93b-9d1085b6a31e', 3, 30, 'ሚስማዕ፥ ይዱማ፥ ማሴ፥ ኬዲድ፥ ቴማን፤'),
  ('b6f97723-5ac2-5a2d-af9c-94519f8951e6', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '5a8dd016-3386-5231-a93b-9d1085b6a31e', 4, 31, 'የጡር፥ ናፌስ፥ ቂዳማ፤ እነዚህ የይስማኤል ልጆች ናቸው።'),
  ('9a6c5aaa-8e41-5664-a021-438a94468380', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '5a8dd016-3386-5231-a93b-9d1085b6a31e', 5, 32, 'የአብርሃም ዕቅብት ኬጡራ የወለደችለት ልጆች፤ ዘምራን፥ ዮቅሳን፥ ሜዳም፥ ምድያን፥ ዮሳብቅ፥ ስዌሕ፥ የዮቅሳንም ልጆች፤ ሳባ፥ ዳዳን።'),
  ('53d45312-da92-5730-a9ea-31684c5e5209', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '5a8dd016-3386-5231-a93b-9d1085b6a31e', 6, 33, 'የምድያምም ልጆች፤ ጌፌር፥ ዔፌር፥ ሄኖሕ፥ አቢዳን፥ ኤልዳን። እነዚህ ሁሉ የኬጡራ ልጆች ነበሩ።'),
  ('1a3b7579-4b30-5097-adda-14d27386b7d4', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 1, 34, 'አብርሃምም ይስሐቅን ወለደ። የይስሐቅም ልጆች ዔሳውና ያዕቆብ ነበሩ።'),
  ('7f847a1c-b331-5d34-aa18-b7219a1c0a8e', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 2, 35, 'የዔሳው ልጆች፤ ዔልፋዝ፥ ራጉኤል፥ ይዑል፥ ይጉሎም፥ ቆሬ።'),
  ('99ee3372-948a-5f22-ac89-0d313432131f', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 3, 36, 'የኤልፋዝ ልጆች፤ ቴማን፥ ኦማር፥ ሳፍር፥ ጎታም፥ ቄኔዝ፥ ቴምናስ፥ አማሌቅ።'),
  ('8dd3f1f8-a54a-593e-a81a-99528f16c5ef', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 4, 37, 'የራጉኤል ልጆች፤ ናቦት፥ ዛራ፥ ሴዴት፥ ሞዛ።'),
  ('5f1a7e36-a3bc-501d-abdd-396c68b7ad13', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 5, 38, 'የሴይርም ልጆች፤ ሎጣን፥ ሳባን፥ ሴቤጎን፥ ዓናን፥ ዴሶን፥ አሦር፥ ዴሳን።'),
  ('58582383-4fde-5d82-a14b-d33d1fbc2826', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 6, 39, 'የሎጣንም ልጆች፤ ሖሪ፥ ኤማን፤ ታምናን የሎጣን እኅት ነበረች።'),
  ('9f48484c-1366-5b65-a450-5c6c03a90329', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 7, 40, 'የሦባል ልጆች፤ ጎለም፥ ማኔሐት፥ ኔባል፥ ሳፍር፥ አናን፤ የሴቤጎን ልጆች፤ ሐያን፥ አናም፤'),
  ('0dd0a5ef-c1a5-552b-aef8-c051bafd2164', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 8, 41, 'የአናም ልጆች፤ ዴሶን፥ የአናም ሴት ልጅ ኤሌማ፥ የዴሶንም ልጆች፤ አምዳን፥ ኤስቦን፥ ኢይትራን፥ ካራን፥ እሊህ ናቸው።'),
  ('c3730094-f2cb-5444-a3dd-c0fee2d29468', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '4711588b-611a-583e-a753-c26d52efcb5e', 9, 42, 'የአሦር ልጆች፤ በለዓን፥ ዛዕዋን፥ ኢይዓቃን። የዴሶን ልጆች፤ ዖስ፥ አራን።'),
  ('9c70c60d-5de1-5c39-a84c-be74c600ebd8', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 1, 43, 'በእስራኤልም ልጆች ላይ ገና ንጉሥ ሳይነግሥ በኤዶምያስ ምድር የነገሡ ነገሥታት እነዚህ ናቸው። የቢዖር ልጅ ባላቅ፤ የከተማውም ስም ዲናባ ነበረ።'),
  ('51472bba-5c11-576c-a4cd-287fe00c4b8c', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 2, 44, 'ባላቅም ሞተ፤ በእርሱም ፋንታ የባሶራ ሰው የዛራ ልጅ ኢዮባብ ነገሠ።'),
  ('d08987b2-327a-565c-a343-82ad2de59176', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 3, 45, 'ኢዮባብም ሞተ፤ በእርሱም ፋንታ የቴማን ሀገር ሰው አሶም ነገሠ፤'),
  ('b7083aef-8117-5163-a2c4-5bbb61e181ce', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 4, 46, 'አሶምም ሞተ፤ በእርሱም ፋንታ በሞዓብ ሜዳ ምድያምን የመታው የባራድ ልጅ አዳድ ነገሠ፤ የከተማውም ስም ጌቴም ነበረ።'),
  ('027952fe-d8b7-5e4e-a9b6-48e61dc9da74', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 5, 47, 'አዳድም ሞተ፤ በእርሱም ፋንታ የማስቃ ሰው ስማዓ ነገሠ።'),
  ('8428aa1d-9890-5628-addf-72c7546cce0e', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 6, 48, 'ስማዓም ሞተ፤ በእርሱም ፋንታ በወንዙ አጠገብ ያለችው የረኆቦት ሰው ሳኦል ነገሠ።'),
  ('db97537b-b0c1-53c8-af90-9278457ba5c9', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 7, 49, 'ሳኦልም ሞተ፤ በእርሱም ፋንታ የአክቦር ልጅ በኣልሐናን ነገሠ።'),
  ('cb8dc791-53b9-5627-a9f3-36bbcb8707d6', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 8, 50, 'የአክቦር ልጅ በኣልሐናንም ሞተ፤ በእርሱም ፋንታ የባራድ ልጅ አዳድ ነገሠ፤ የከተማውም ስም ፌጎር ነበረ፤ ሚስቱም የሚዛሃብ ልጅ የመጥሬድ ልጅ መሄጣብኤል ነበረች።'),
  ('f51e4b64-60a7-5135-a752-73ad5e66aef0', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 9, 51, 'አዳድም ሞተ፤ የኤዶምያስም አለቆች እነዚህ ነበሩ፤ ቴምናዕ አለቃ፥ ጎለም አለቃ፥ የቴት አለቃ፥'),
  ('18896edb-0633-5f04-a58f-7b02b930952e', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 10, 52, 'አህሊባማ አለቃ፥ ኤላ አለቃ፥ ፌኖን አለቃ፥'),
  ('02fb14a6-229c-5a9b-ae28-25494ae8152b', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 11, 53, 'ቄኔዝ አለቃ፥ ቴማን አለቃ፥ መብሳር አለቃ፥')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8ae16c32-f5f8-5495-aee6-8e03d043aa6f', '938a3c6d-1b48-5d9e-aaf0-6f5141ffa37a', '68ba25a1-4999-53ec-a121-84d2109547cb', 12, 54, 'መግዴኤል አለቃ፥ ዛፎአል አለቃ፤ እነዚህ የኤዶምያስ አለቆች ነበሩ።'),
  ('fa9d1563-b20b-58b4-ae29-496636030530', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 1, 1, 'የእስራኤልም ልጆች ስሞች እነዚህ ናቸው፤ ሮቤል፥ ስምዖን፥ ሌዊ፥ ይሁዳ፥ ይሳኮር፥ ዛብሎን፤'),
  ('50007c13-0194-5217-acf3-cb6c23a4473b', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 2, 2, 'ዳን፥ ዮሴፍ፥ ብንያም፥ ንፍታሌም፥ ጋድ፥ አሴር።'),
  ('a9e0908e-8740-5fdd-a9f7-2c1e9a148286', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 3, 3, 'የይሁዳ ልጆች፤ ዔር፥ አውናን፥ ሴሎም፤ እነዚህ ሦስቱ ከከነዓናዊቱ ሴት ከሴዋ ልጅ ተወለዱለት። የይሁዳም የበኵር ልጅ ዔር በእግዚአብሔር ፊት ክፉ ነበረ፤ ገደለውም።'),
  ('dd2cbdd5-b627-5628-a56c-9426aaa2dfd1', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 4, 4, 'ምራቱም ትዕማር ፋሬስንና ዛራን ወለደችለት፤ የይሁዳም ልጆች ሁሉ አምስት ነበሩ።'),
  ('10569a0b-04f5-5236-ae9b-f0ba28e960aa', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 5, 5, 'የፋሬስ ልጆች፤ ኤስሮም፥ ያሙሔል።'),
  ('ee1d2636-32a1-5a86-a3fc-bd4748dac450', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 6, 6, 'የዛራም ልጆች፤ ዘምሪ፥ ኤታን፥ ኤማን፥ ካልኮል፥ ዳራ፤ ሁሉም አምስት ነበሩ።'),
  ('58fc7db7-3e10-5b08-a63d-a92da21cc34c', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 7, 7, 'የዘምሪም ልጅ ከርሚ ነው፤ የከርሚም ልጅ እስራኤልን ያስጨነቀ፥ እርሙን ሰርቆ የበደለ አካን ነበረ።'),
  ('e81d2feb-5122-5ad8-a9b8-259b19b7fc08', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 8, 8, 'የኤታንም ልጅ አዛርያ ነበረ።'),
  ('892cb116-0c33-5252-a875-2f399e678e3e', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 9, 9, 'ለኤስሮም የተወለዱለት ልጆች፤ ኢያሬሄም፥ አራም፥ ካሌብ ነበሩ።'),
  ('9a90d975-f0bb-5342-a752-09e9f111df81', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 10, 10, 'አራምም አሚናዳብን ወለደ፤ አሚናዳብም የይሁዳን ልጆች አለቃ ነአሶንን ወለደ፤'),
  ('67c74f1c-34d5-515a-ad54-bc9edbb7a935', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 11, 11, 'ነአሶንም ሰልሞንን ወለደ፤ ሰልሞን ቦዔዝን ወለደ፤'),
  ('07f6fa9a-dfbd-567c-a873-46c81d7d9bf5', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 12, 12, 'ቦዔዝም ኢዮቤድን ወለደ፤ ኢዮቤድም እሴይን ወለደ፤'),
  ('3b3f11ab-2b4c-5e67-a1e3-677a633000cb', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 13, 13, 'እሴይም የበኵር ልጁን ኤልያብን፥ ሁለተኛውንም አሚናዳብን፥ ሦስተኛውንም ሣማን፥'),
  ('d4c6da31-82f8-595b-af75-d9ac899b6dc0', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 14, 14, 'አራተኛውንም ናትናኤልን፥ አምስተኛውንም ራዳይን፥'),
  ('04ca44ed-32b0-507f-aa0b-81227be17f9d', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 15, 15, 'ስድስተኛውንም አሶንን፥ ሰባተኛውንም ዳዊትን ወለደ፤'),
  ('42260b31-2543-5f80-ad6a-5118e6db2b42', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 16, 16, 'እኅቶቻቸውም ሶርህያና አቢግያ ነበሩ። የሶርህያም ልጆች አቢሳ፥ ኢዮአብ፥ አሣሄል እኒህ ሦስቱ ነበሩ።'),
  ('6bdad437-a82d-5e53-a276-974415babe65', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 17, 17, 'አቢግያም አሜሳይን ወለደች፤ የአሜሳይም አባት እስማኤላዊው ይትኤር ነበረ።'),
  ('0e6ddb4a-0a8b-5047-a80d-0eab91f5757c', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 18, 18, 'የኤስሮምም ልጅ ካሌብ ዐዙባ የምትባል ሚስት አገባ፥ ይሪዖትንም አገባ፤ ልጆችዋም ያሳር፥ ሶባብ፥ ኤርኖን ነበሩ።'),
  ('312cb12e-0839-503f-a932-9574bcdb747d', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 19, 19, 'ዐዙባም ሞተች፥ ካሌብም ኤፍራታን አገባ፤ እርስዋም ኦርን ወለደችለት።'),
  ('17c1f84a-8d41-54eb-a1c5-4685d22d9838', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 20, 20, 'ኦርም ኡሪን ወለደ፥ ኡሪም ባስልኤልን ወለደ።'),
  ('adec400d-9171-55c2-a318-d0ef64e850d5', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 21, 21, 'ከዚያም በኋላ ኤስሮም ስድሳ ዓመት በሆነው ጊዜ ወደ አገባት ወደ ገለዓድ አባት ወደ ማኬር ልጅ ገባ፤ ሴጉብንም ወለደችለት።'),
  ('ef6f329e-f7ae-5d1e-aa56-a26d72f88958', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 22, 22, 'ሴጉብም ኢያኤርን ወለደ፤ ለእርሱም በገለዓድ ምድር ሃያ ሦስት ከተሞች ነበሩት።'),
  ('8c859cf1-ce1c-5e09-a1f9-b659d05847e6', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 23, 23, 'ኤስሮምም ጌሱርንና አራምን የኢያዔርን ከተሞች ከቄናትና ከመንደሮችዋ ጋር ስድሳውን ከተሞች ወሰደ። እነዚህ ሁሉ የገለዓድ አባት የማኪር ልጆች ከተሞች ነበሩ።'),
  ('5909962d-4670-5680-a4d4-40af02369450', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 24, 24, 'ኤስሮምም ከሞተ በኋላ ካሌብ ወደ ኤፍራታ መጣ። የኤስሮምም ሚስት አብያ የቴቁሔን አባት አስሖርን ወለደችለት።'),
  ('81dd3a3a-dd29-5fff-af83-68813d35781f', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 25, 25, 'የኤስሮምም የበኵር ልጁ የኢያሬምሄል ልጆች በኵሩ ራም፥ በአናን፥ አራን፥ አሶም፥ አኪያ ነበሩ።'),
  ('9ed43001-701b-5604-a18a-fb8291be026c', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 26, 26, 'ለኢያሬምሄልም አጥራ የተባለች ሌላ ሚስት ነበረችው፤ እርስዋም የአናም እናት ነበረች።'),
  ('8eba14a1-6188-5aea-afce-cb68004fe282', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 27, 27, 'የኢያሬምሄል የበኵሩ የራም ልጆች ማኦስ፥ ኢያቢን ዔቄር ነበሩ።'),
  ('7112ccb9-1cfd-5b77-ae80-4a7ad4432174', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 28, 28, 'የአናምም ልጆች ሸማይና ያዳይ ነበሩ። የሸማይም ልጆች ናዳብና አቢሱር ነበሩ።'),
  ('4bb15e5b-95b4-5c21-a81f-e89320c099db', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 29, 29, 'የአቢሱርም ሚስት ስም አቢካኤል ነበረ፤ እርስዋም፥ አዛቡርንና ሞሊድን ወለደችለት።'),
  ('de1014dd-6731-58aa-a3ab-4fee61b908b0', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 30, 30, 'የናዳብም ልጆች ሴሌድና አፋይም ነበሩ፤ ሴሌድም ልጆችን ሳይወልድ ሞተ።'),
  ('455296e9-442f-53ae-a662-f68a18500173', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 31, 31, 'የአፋይምም ልጅ ይሲ፥ የይሲም ልጅ ሶሳን፥ የሶሳንም ልጅ አሕላይ ነበረ። የአሕላይም ልጅ ይዳይ ነበረ።'),
  ('e6ff4d5f-e61e-5273-a9ee-adac2faec7a7', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 32, 32, 'የይዳይ ልጆች አክሲም፥ ዮቴርና ዮናታን ነበሩ፤ ዮቴርም ልጆችን ሳይወልድ ሞተ።'),
  ('e0009b8d-b77d-5ec9-aecc-6365690ba6a1', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 33, 33, 'የዮናታንም ልጆች ፋሌትና አዛዝ ነበሩ፤ እነዚህም የኢያሬምሔል ልጆች ነበሩ።'),
  ('9b657101-83f3-5a0e-adce-9a16f69600a0', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 34, 34, 'ለሶሳንም ሴቶች ልጆች እንጂ ወንዶች ልጆች አልነበሩትም፤ ለሶሳንም ኢዮሄል የተባለ ግብፃዊ አገልጋይ ነበረው።'),
  ('81c5d0d7-bab3-5914-a6bd-eaa2a7fe573b', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 35, 35, 'ሶሳንም ለአገልጋዩ ለኢዮሄል ልጁን አጋባት፥ እርስዋም ያቲን ወለደችለት።'),
  ('121e3524-e57b-5edc-a086-77ec7bd531aa', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 36, 36, 'ያቲም ናታንን ወለደ፤ ናታንም ዛቤትን ወለደ፤'),
  ('42996dcb-5db2-5564-a546-6bb7175acc1d', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 37, 37, 'ዛቤትም አውፋልን ወለደ፤ አውፋልም ዖቤድን ወለደ፤'),
  ('d8ab4980-d594-5172-aa63-c0dabff2fafa', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 38, 38, 'ዖቤድም ኢያሁን ወለደ፤ ኢያሁም አዛርያስን ወለደ፤'),
  ('a0259133-678c-51ce-ab99-d646626a3f80', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 39, 39, 'አዛርያስም ኬሌስን ወለደ፤ ኬሌስም ኤልዓሳን ወለደ፤'),
  ('20bbc1c6-a124-585d-a8a9-0b3a3a781fa0', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 40, 40, 'ኤልዓሳም ሲስማኤልን ወለደ፤ ሲስማኤልም ሱላምን ወለደ፤'),
  ('534d8906-03ea-572e-afe1-3a366f55fec7', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 41, 41, 'ሱላምም ኢዮቆምን ወለደ፤ ኢዮቆምም ኤልሳማን ወለደ።'),
  ('331d3647-3759-5d34-ab94-cfd5b03a37a5', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 42, 42, 'የኢያሬምሄል ወንድም የካሌብ ልጆች በኵር የዚፍ አባት ማሪስ ነው፤ የኬብሮንም አባት የማሪስ ልጆች ነበሩ።'),
  ('d7e93bf4-2a59-59cd-a760-0ef91e790e49', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 43, 43, 'የኬብሮንም ልጆች፤ ቆሬ፥ ተፋ፥ ሬቆምና፥ ሴማዓ ነበሩ።'),
  ('27ce93be-d1f1-5b61-a415-e9520fac57a0', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 44, 44, 'ሴማዓም የኤርቃምን አባት ራኤምን ወለደ፤ ኤርቃምም ሰማኤምን ወለደ።'),
  ('37dd65bd-68c6-54d1-ae43-7e6c78ac80a1', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 45, 45, 'የሰማኤምም ልጅ ማዖን ነበረ፤ ማዖንም የቤት ሱር አባት ነበረ።'),
  ('4c6c3edb-a3ab-5a6c-ae0e-cde23f4ade51', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 46, 46, 'የካሌብም ዕቅብት ጌፋ አራንን፥ ሞሳን፥ ጋዜዝን ወለደች። አራንም ጊዚኢን ወለደ።'),
  ('5c3bc31a-1440-5546-ab47-8e6cea8d4d85', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 47, 47, 'የያዳይም ልጆች፤ ሬጌም፥ ዮታም፥ ጌርሶም፥ ፋሌጥ፥ ጌፋና፥ ሰጋፍ ነበሩ።'),
  ('0de2c63e-d108-53b6-ab7f-0290a35cd094', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 48, 48, 'የካሌብም ዕቅብት ማዕካ ሴብርንና ቲርሐናን ወለደች።'),
  ('817c8586-7056-5db9-a0b0-b3e546487b5b', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 49, 49, 'ደግሞም የምድሜናን አባት ስጋብን የመክቢናንና የጌባልን አባት ሳዑልን ወለደች፤ የካሌብም ሴት ልጅ አስካ ነበረች።'),
  ('fa058b04-51f7-5ded-a429-f97c435c4e44', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 50, 50, 'የካሌብም ልጆች እነዚህ ነበሩ፤ የኤፍራታ የበኵሩ የኦር ልጅ የቀርያታርም አባት ሶባል ነበር፥'),
  ('09f1db47-4542-59c4-a46c-ee71651b7b3a', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 51, 51, 'የቤተ ልሔም አባት ሰልሞን፥ የቤት ጋዲር አባት ኦሪ።'),
  ('ce4af938-a16c-59fd-a802-ca4d645612b4', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 52, 52, 'የቀርያታርምም አባት የሶባል ልጆች አረኤ፥ ሃጼ፥ አማኒት ነበሩ።'),
  ('70aeaaf9-ec0f-5b79-a55d-c5eaf81a2a43', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 53, 53, 'የቀርያታርም ወገኖች፤ ይትራውያን፥ ፋታውያን፥ ሹማታውያን፥ ሚሸራውያን፤ ከእነዚህም ሶራሐውያንና ኤሽታአላውያን ወጡ።'),
  ('b26625e7-5e23-5fe6-ae73-fd0ff5e4f268', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 54, 54, 'የሰልሞንም ልጆች ቤተ ልሔም፥ ነጦፋውያን፥ አጦሮት ቤትዮአብ፥ የመናሕታውያን እኩሌታ፥ ሰራዓውያንም ነበሩ።'),
  ('493ca001-4937-536e-a0dd-5e96defcbd33', '28c20504-e62c-5bf0-a3b7-708451998f65', '5a8f53f3-9d70-5321-a9b6-24279f6bd4b4', 55, 55, 'በያቤጽም የተቀመጡ የጸሓፊዎች ወገኖች፤ ቴርዓውያን፥ ሹማታውያን፥ ሡካታውያን ነበሩ፤ እነዚህ ከሬካብ ቤት አባት ከሐማት የወጡ ቄናውያን ናቸው።'),
  ('fa65cdeb-5bba-543c-ac36-5b398295482a', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 1, 1, 'በኬብሮን ለዳዊት የተወለዱለት ልጆች እነዚህ ናቸው። በኵሩ አምኖን ከኢይዝራኤላዊቱ ከአኪናሆም፥ ሁለተኛውም ዶለህያ ከቀርሜሎሳዊቱ ከአቢግያ፥'),
  ('852081ec-0221-520c-a867-da4f099d1cde', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 2, 2, 'ሦስተኛው አቤሴሎም ከጌድሶር ንጉሥ ከተልማይ ልጅ ከመዓካ፥ አራተኛው አዶንያስ ከአጊት፥'),
  ('e31e8654-0ebf-566d-a864-89a7ddeaaaa8', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 3, 3, 'አምስተኛው ሰፋጥያስ ከአቢጣል፥ ስድስተኛው ይትርኃም ከሚስቱ ከዔግላ።'),
  ('6941595a-0e5e-5c65-a861-f24a9c66f64f', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 4, 4, 'እነዚህ ስድስቱ በኬብሮን ተወለዱለት፤ በዚያም ሰባት ዓመት ከስድስት ወር ነገሠ፤ በኢየሩሳሌምም ሠላሳ ሦስት ዓመት ነገሠ።'),
  ('78b72f0e-6eb3-54d2-acc7-cd91dfac0f9d', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 5, 5, 'እነዚህ ደግሞ በኢየሩሳሌም ተወለዱለት፤ ከዓሚል ልጅ ከቤርሳቤህ ስማዕ፥ ሶባብ፥ ናታን፥ ሰሎሞን፥ አራት፤'),
  ('27ea5179-b231-57b1-a75a-3831ea3c1e32', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 6, 6, 'ኢያቤሔር፥ ኤልሳማ፥ ኤሊፋላት፥'),
  ('177a6fc5-6add-5668-aca1-3f75c385f18e', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 7, 7, 'ናጌል፥ ናፌቅ፥ ያፍያ፥'),
  ('941ee076-1183-5dbb-a160-eeb15d1eaaad', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 8, 8, 'ኤልሳማ፥ ኤሊዳ፥ ኤልፋሌጥ፥ ዘጠኝ።'),
  ('eaf17083-225a-5640-aadf-27ed14b09339', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 9, 9, 'እነዚህ ሁሉ ከቁባቶቹ ልጆች በቀር የዳዊት ልጆች ነበሩ፤ ትዕማርም እኅታቸው ነበረች።'),
  ('d08a686d-179b-566e-aeed-7bd7b12bd7af', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 10, 10, 'የሰሎሞንም ልጅ ሮብዓም ነበረ፤ ልጁ አቢያ፥ ልጁ አሳ፥ ልጁ ኢዮሣፍጥ፥'),
  ('f7da7719-2d5f-54a5-a901-146a4b5fea27', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 11, 11, 'ልጁ ኢዮራም፥ ልጁ አካዝያስ፥ ልጁ ኢዮአስ፥'),
  ('31f1e4ed-1703-5520-a528-34a38e948ca8', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 12, 12, 'ልጁ አሜስያስ፥ ልጁ ዓዛርያስ፥ ልጁ ኢዮአታም፥'),
  ('886335c4-8dc5-5e66-a89d-3670148a432c', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 13, 13, 'ልጁ አካዝ፥ ልጁ ሕዝቅያስ፥ ልጁ ምናሴ፥'),
  ('99ceac44-d3ec-5624-a003-75a1063cfcd0', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 14, 14, 'ልጁ አሞጽ፥ ልጁ ኢዮስያስ።'),
  ('c54f16a2-74b3-5896-a9b9-02dc1aafda18', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 15, 15, 'የኢዮስያስም ልጆች፤ በኵሩ ዮሐናን፥ ሁለተኛውም ኢዮአቄም፥ ሦስተኛውም ሴዴቅያስ፥ አራተኛውም ሰሎም።'),
  ('e8976dd5-c7b0-5680-ab7a-0b5f0f5a97d9', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 16, 16, 'የኢዮአቄምም ልጆች፤ ልጁ ኢኮንያን፥ ልጁ ሴዴቅያስ።'),
  ('eeb8f473-a032-583a-a357-4702db81d7c4', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 17, 17, 'የኢኮንያንም ልጆች አሤር፥ ሰላትያል፥'),
  ('7937a034-7e20-5214-adb7-cb3efa87fe15', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 18, 18, 'መልኪራም፥ ፈዳያ፥ ሳንሳሮ፥ ይቃምያ፥ ሆሻማ፥ ነዳብያ ነበሩ።'),
  ('9d27fb09-22ed-5def-af20-6fee7d624d35', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 19, 19, 'የፈዳያም ልጆች ዘሩባቤልና ሰሜኤ ነበሩ፤ የዘሩባቤልም ልጆች፤ ሜሱላም፥ ሐናንያ፥ እኅታቸውም ሰሎሚት።'),
  ('8496964d-a04a-5fb6-ad8d-31837a75fcd3', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 20, 20, 'አሱባ፥ አሄል፥ በራክያ፥ ሐሳድያ፥ አስቦሴድ አምስት ናቸው።'),
  ('45b891ee-dea2-5d45-ad7a-e4638410441c', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 21, 21, 'የሐናንያም ልጆች ፈላጥያና ልጁ ኢያሴያ ነበሩ። ረፋያ ልጁ፥ አርና ልጁ፥ አብድዩ ልጁ፥ ሴኬንያ ልጁ።'),
  ('605ff585-3133-5971-a9e1-b9fd326dea4d', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 22, 22, 'የሴኬንያም ልጅ ሰማዕያ ነበረ። የሰማዕያም ልጆች ሐጡስ፥ ኢዮሔል፥ ቤርያሕ፥ ነዋድያ፥ ሳፌጥ ስድስት ነበሩ።'),
  ('a7f0a24a-f49a-515b-ad28-54288bd6b087', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 23, 23, 'የነዋድያ ልጆች ኤልዮዔንኢ፥ ሕዝቅያስ፥ ዓዝሪቃም ሦስት ነበሩ።'),
  ('1c4139bd-fe31-5682-ae75-d071bda0d2ca', 'dc768dc9-3cc7-5843-a7f9-7bfb194cca48', '11d9003f-f2fb-54f8-a8f8-fce61d8b74db', 24, 24, 'የኤልዮዔናኢም ልጆች አዳይያ፥ ኤልያሴብ፥ ፈላያ፥ ዓቁብ፥ ዮሐናን፥ ዶላያ፥ ዓናኒ ሰባት ነበሩ።'),
  ('2da4235b-cbbe-5cf4-af8a-82819da9b20a', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 1, 1, 'የይሁዳ ልጆች ፋሬስ፥ ኤስሮም ከርሚ፥ ሆርና ሱባል ናቸው።'),
  ('3b4f128a-725a-5d31-aca2-85e1d677dacc', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 2, 2, 'የሱባልም ልጅ ራያ ኢኤትን ወለደ፤ ኢኤትም አሑማይንና ላሃድን ወለደ። እነዚህ የሰራአውያን ትውልዶች ናቸው።'),
  ('032aa31e-a34f-5881-a6b9-e65b4f552b07', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 3, 3, 'እነዚህም የኤጣም ልጆች ናቸው፤ ኢይዝራኤል፥ ይሰማ፥ ኤጋቢስ፥ እኅታቸውም ኤሴልፎን።'),
  ('ca987a99-727b-5497-a180-e8c2bfd361b6', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 4, 4, 'የጌዶርም አባት ፋኑኤል፥ የአሶን አባት አዜር፤ እነዚህ የቤተ ልሔም አባት የኤፍራታ የበኵሩ የሆር ልጆች ናቸው።'),
  ('bd421da4-ee88-5ce5-accb-252250b27e32', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 5, 5, 'ለቴቁሄም አባት ለአስሑር ሔላና ነዓራ የተባሉ ሁለት ሚስቶች ነበሩት።'),
  ('d5600a57-b241-55cb-a464-b17090c7af85', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 6, 6, 'ነዓራም አሑዛምን፥ ኦፌርን፥ ቴማንንና አስትራን ወለደችለት። እነዚህ የነዓራ ልጆች ናቸው።'),
  ('5dd1964a-5633-51ba-a620-1feaacb95f55', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 7, 7, 'የሔላም ልጆች ሴሬት፥ ይጽሐርና ኢትናን ናቸው።'),
  ('860e2b20-5399-5ffc-a037-1253892f822d', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 8, 8, 'ቆስ፥ ኢኖብን፥ ሲባባን፥ የሃሩምንም ልጅ የሬካብን ወንድም ወገኖች ወለደ።'),
  ('df492d56-e646-5192-add5-6d7dc44f7ef6', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 9, 9, 'ያግቤጽም ከወንድሞቹ ይልቅ የተከበረ ነበረ፤ እናቱም፦ በጣር ወልጄዋለሁና ብላ ስሙን፦ ያግቤጽ ብላ ጠራችው።'),
  ('52e512f1-5b92-56fa-ae20-8357947ac732', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 10, 10, 'ያግቤጽም፥ “እባክህ፥ መባረክን ባርከኝ፥ ሀገሬንም አስፋው፤ እጅህም ከእኔ ጋር ትሁን፤ እንዳያሳዝነኝም ምልክት አድርግልኝ” ብሎ የእስራኤልን አምላክ ጠራ፤ እግዚአብሔርም የለመነውን ሰጠው።'),
  ('5e84b5fc-b1b6-52e2-a84a-28c22f024274', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 11, 11, 'የሱሃም ወንድም ካሌብ የኤስቶንን አባት ማኪርን ወለደ።'),
  ('1636f1f8-e865-5320-a695-7f28ff06436c', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 12, 12, 'ኤስቶንም ቤቶራፋንና ፋሲሓን፥ የቄኔዛዊው የኤሴሎምን ወንድም የነዓስ ከተማ አባት ታሒናን ወለደ፤ እነዚህ የራፋ ሰዎች ናቸው።'),
  ('4cf9f815-270b-5b90-ac9b-4a23e9e6ebf1', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 13, 13, 'የቄኔዝም ልጆች ጎቶንያልና ሠራኢያ ነበሩ። የጎቶንያልም ልጅ አታት ነበረ።'),
  ('01834257-9ba1-5f53-a521-228577b67cb4', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 14, 14, 'መናቲም ጎፍራን ወለደ። ሠራኢያም የጌራሲምን አባት ኢዮአብን ወለደ፤ እነርሱም ጠራቢዎች ነበሩ።'),
  ('2947eb3f-9f36-52a7-ac77-ccde5f135035', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 15, 15, 'የዮፎኒም ልጅ የካሌብ ልጆች ዔሩ፥ ኤላ፥ ነዓም ነበሩ። የኤላም ልጅ ቄኔዝ ነበረ።'),
  ('80ebfc00-e9ab-501c-ab25-e242c54dba5d', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 16, 16, 'የኢያልኤል ልጆች ዜፍ፥ ዚፋ፥ ቲርያ፥ አሣርኤል ነበሩ።'),
  ('1b8351b7-66d3-5756-a8db-5bc08eb2aec2', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 17, 17, 'የኤዜራስም ልጆች፤ ኢያቴር፥ ሞራድ፥ ጋፌር፥ ኢያሎን ነበሩ፤ ኢያቴርም ማሮንን፥ ሰማዒን፥ የኢስቲሞንን አባት ይስባኤልን ወለደ።'),
  ('dd63c330-b1fc-5ba2-affc-e117ea295c3f', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 18, 18, 'ሚስቱ አይሂዳም የጌዶርን አባት ያሬድን፥ የሦኮንም አባት ሔቤርን፥ የዛኖዋንም አባት ይቁቲኤልን ወለደች። እነዚህ ሞሬድ ያገባት የፈርዖን ልጅ የቢትያ ልጆች ናቸው።'),
  ('f8f61fc3-de71-5800-a039-13ba65da1b3d', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 19, 19, 'የሆድያ ሚስት የነሐም እኅት ልጆች የገርሜው የቅዔላ አባትና ማዕካታዊው ኤሲትሞዓ ነበሩ።'),
  ('7eee86b3-783a-56bb-a16f-2acefa72476e', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 20, 20, 'የሴሞንም ልጆች አምኖን፥ የአናን ልጆች ሬኖንና ቲሎን ነበሩ፤ የይስቴም ልጆች ዘካትና የዘካት ልጆች ነበሩ።'),
  ('0b15f4ca-1644-5d05-aa29-f5929ed76e89', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 21, 21, 'የይሁዳም ልጅ የሴሎም ልጆች የሌካ አባት ዔር፥ የመሪሳ አባት ለዓዳ፥ ከአስቤዓ ቤት የሚሆኑ ጥሩ በፍታ የሚሠሩ ወገኖች፥'),
  ('18fd9fc3-c473-52d0-af0d-c49691671b44', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 22, 22, 'ኢዮአቄም፥ የካዚባ ሰዎች፥ ኢዮአስ፥ በሞዓብ አድሮ ስማቸውን፥ አብዶራንና ተቂኤም ብሎ የመለሰ ሣራፍ ነበሩ።'),
  ('4d06d516-d00a-5ad3-a7cc-03f5fe30d2af', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 23, 23, 'እነዚህ በነጣዔምና በጋዲራ ከንጉሡ ጋር የሚቀመጡ ሸክላ ሠራተኞች ነበሩ። እነርሱም በመንግሥቱ ጸንተው በዚያ ይኖሩ ነበር።'),
  ('483ca151-9bca-5680-a91e-68e1bc3fb896', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 24, 24, 'የስምዖንም ልጆች፤ ነሙኤል፥ ያሚን፥ ያሪብ፥ ዛራ፥ ሳኡል፤'),
  ('0e7b5007-fa75-5246-af14-22c1550549fe', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 25, 25, 'ልጁ ሳሌም፥ ልጁ መብሳም፥ ልጁ ማስማዕ።'),
  ('ca20d640-a9bc-5dfa-aa2f-02e2d217f67a', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 26, 26, 'የማስማዕም ልጆች፤ ልጁ ሃሙኤል፥ ልጁ ሳባድ፥ ልጁ ዝኩር፥ ልጁ ሰሜኢ።'),
  ('fbb31818-b023-5d36-ad88-f27618f74b05', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 27, 27, 'ለሰሜኢም ዐሥራ ስድስት ወንዶችና ስድስት ሴቶች ልጆች ነበሩት፤ ለወንድሞቹ ግን ብዙ ልጆች አልነበሩአቸውም፥ ወገናቸውም ሁሉ እንደ ይሁዳ ልጆች አልተባዙም።'),
  ('b3d3688b-f919-53f4-ad58-ac3abf718da6', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 28, 28, 'በቤርሳቤህም፥ በሰምዓም፥ በሞላዳ፥ በሐጸርሱዓል፥'),
  ('06290335-259b-5113-a82a-46e92b064ef2', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 29, 29, 'በቤልሃ፥ በዔጼም፥ በቶላድ፤'),
  ('fcd7d92b-dd03-5100-a14a-fb810bfc56fe', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 30, 30, 'በቤቱኤል፥ በሔርማ፥ በሤቄላቅ፤'),
  ('c435da1a-9dd0-584b-ae90-8372107b15d4', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 31, 31, 'በቤትማርካቦት፥ በሐጸርሱሲም፥ በቤትቢሪ፥ በሰዓራይም ይቀመጡ ነበር። እስከ ዳዊትም መንግሥት ድረስ ከተሞቻቸው እነዚህ ነበሩ።'),
  ('bbd2f2e6-2ee0-5747-abe6-44739618fa12', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 32, 32, 'መንደሮቻቸውም ኤጣም፥ ዓይን፥ ሬሞን፥ ቶኪን፥ ዓሻን፥ አምስቱ ከተሞች፤'),
  ('04cf893e-f3ce-585f-a994-96cc761301c6', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 33, 33, 'መንደሮቻቸውም ሁሉ እስከ በኣል ድረስ በእነዚህ ከተሞች ዙሪያ ነበሩ። መቀመጫቸውና ድርሻቸውም ይህ ነበረ።'),
  ('45051375-08de-5d39-a958-b6c5db7d406c', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 34, 34, 'መሶባብ፥ የምሌክ፥ የአሚስያስ ልጅ ኢዮስያ፤'),
  ('1e3cebea-c462-52be-a5c6-d302bccfbc68', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 35, 35, 'ኢዮኤል፥ የዮስብያ ልጅ፥ የሠራያ ልጅ የአሣኤል ልጅ ኢዩ፤'),
  ('8fbb3cb8-a7f4-5d74-af4b-cff02ae9f1ac', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 36, 36, 'ኤልዮዔናይ፥ ያዕቀባ፥ የሰሐያ፥ ዓሣያ፥ ዓዲዔል፥ ይስማኤል፥ በናያስ፤'),
  ('c006849b-e390-5018-a783-9cc17d232f2d', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 37, 37, 'የሳፋኤ ልጅ ዙዛ፥ የአሎን ልጅ የይዳያ ልጅ የሰማሪ ልጅ የሰማያ ልጅ፤'),
  ('aa1d8851-2100-5aa9-aace-99be2d95bd51', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 38, 38, 'እነዚህ በስማቸው የተጠሩ በወገኖቻቸው ላይ አለቆች ነበሩ፤ የአባቶቻቸውም ቤቶች በዝተው ነበር።'),
  ('fb087f81-2016-547d-a11c-9365345f96ab', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 39, 39, 'ለመንጎቻቸው መሰማርያ ይሹ ዘንድ ወደ ጌራራ እስኪደርሱ ድረስ ወደ ጋይ ምሥራቅ ሄዱ።'),
  ('ba38577f-b95c-5e08-ad67-eb8c1be12aee', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 40, 40, 'ብዙና እጅግ ያማረ መሰማርያም አገኙ፤ ምድሪቱም በፊታቸው ሰፊና ጸጥተኛ ሰላም ያላትም ነበረች፤ በቀድሞም ጊዜ በዚያ ተቀምጠው የነበሩ ከካም ወገን ነበሩ።'),
  ('e7b7b297-5cc1-59a6-a241-63c74797e658', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 41, 41, 'በስማቸው የተጻፉ እነዚህም በይሁዳ ንጉሥ በሕዝቅያስ ዘመን መጥተው ድንኳኖቻቸውንና በዚያ የተገኙትን ምዑናውያንን መቱ፥ እስከ ዛሬም ድረስ ፈጽመው አጠፉአቸው፤ በዚያም ለመንጎቻቸው መሰማሪያ ነበርና በስፍራቸው ተቀመጡ።'),
  ('ab7b57b8-aee1-5b07-af8d-0547b0e52f0c', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 42, 42, 'ከስምዖንም ልጆች አምስት መቶ ሰዎች ወደ ሴይር ተራራ ሄዱ፤ አለቆቻቸውም የይሰዔ ልጆች ፥ ፈላጥያ፥ ነዓርያ፥ ረፋያ፥ ዑዝኤል ነበሩ።'),
  ('1e60ad21-0f43-5c99-ae40-4d47920f18d9', 'ede8cea3-7f8f-5091-ad4a-73c7b71e032a', 'acceff63-09d7-52df-adbd-ec75c43d4ffb', 43, 43, 'ያመለጡትንም የአማሌቃውያንን ቅሬታ መቱ፥ በዚያም እስከ ዛሬ ድረስ ተቀምጠዋል።'),
  ('081e34bc-6e0f-5bf1-aa2d-ede231768cdd', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 1, 1, 'የእስራኤልም በኵር የሮቤል ልጆች እነዚህ ናቸው። እርሱ የበኵር ልጅ ነበረ፤ ነገር ግን ወደ አባቱ ምንጣፍ ስለ ወጣ አባቱ እስራኤል በረከቱን ለልጁ ለዮሴፍ ሰጠ፤ ብኵርናም አልተቈጠረለትም።'),
  ('d75bae48-711c-58f0-a07e-005371760be8', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 2, 2, 'ይሁዳም በወንድሞቹ መካከል በረታ፥ አለቃም ከእርሱ ሆነ፤ በረከት ግን ለዮሴፍ ነበረ።'),
  ('d09a5d0e-216b-5d61-acba-b0abd03ba44e', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 3, 3, 'የእስራኤል በኵር የሮቤል ልጆች፤ ሄኖኅ፥ ፍሎስ፥ አስሮን፥ ከርሚ ነበሩ።'),
  ('d0722b61-ab33-5b4d-abeb-da829baada69', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 4, 4, 'የኢዩኤል ልጆች፤ ልጁ ሰማያ፥ ልጁ ጎግ፥ ልጁ ሰሜኢ፤'),
  ('f8a0fcd8-b9c1-543d-ac7b-9655a4210733', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 5, 5, 'ልጁ ሚካ፥ ልጁ ሬካ፥ ልጁ ቤኤል፥'),
  ('fdac0f77-f96f-5744-a624-45d22939fb57', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 6, 6, 'የአሦር ንጉሥ ቴልጌልቴልፌልሶር የማረከው ልጁ ብኤራ፤ እርሱ የሮቤል ነገድ አለቃ ነበረ።'),
  ('23670458-27eb-5161-a478-0bf42141a1c1', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 7, 7, 'ወንድሞቹ በየወገናቸው የትውልዶቻቸው መዝገብ በተቈጠረ ጊዜ፥ አለቆቻቸው ኢዩኤልና ዘካርያስ ነበሩ።'),
  ('ffaf54c7-8752-5417-a1e0-7ef255a8e4f8', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 8, 8, 'እስከ ናባውና እስከ በኣልሜዎን ድረስ በአሮዔር የተቀመጠው የኢዩኤል ልጅ የሰማዕ ልጅ የዖዛዝ ልጅ ቤላ፤'),
  ('29fabffa-6004-5af0-a165-282303ec2c3a', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 9, 9, 'በገለዓድ ምድር እንስሶቻቸው በዝተው ነበርና በምሥራቅ በኩል ከኤፍራጥስ ወንዝ ጀምሮ እስከ ምድረ በዳው መግቢያ ድረስ ተቀመጠ።'),
  ('5417d41c-7d61-54eb-a0d5-d5e2fb3b86dc', '33252d01-5770-50a0-ae17-b83c55c60780', 'c4796fd2-691f-5d6a-a387-41cdcf50cdb7', 10, 10, 'በሳኦልም ዘመን ከስደተኞች ጋር ተዋጉ፥ እነርሱም በእጃቸው ተመትተው ወደቁ፤ በገለዓድ ምሥራቅ በኩል ባለው ሀገር ሁሉ በድንኳኖቻቸው ተቀመጡ።'),
  ('eb1384e3-a88c-5e47-ab93-c19fb24d534d', '33252d01-5770-50a0-ae17-b83c55c60780', '0be3c1d2-cd90-5055-af93-bb92c9ffdaf4', 1, 11, 'የጋድም ልጆች በባሳን ምድር እስከ ሰልካ ድረስ በአፋዛዣቸው ተቀመጡ።'),
  ('6b2550d6-e68d-5f7e-a901-87cf1490844c', '33252d01-5770-50a0-ae17-b83c55c60780', '0be3c1d2-cd90-5055-af93-bb92c9ffdaf4', 2, 12, 'በኵሩ ኢዩኤል፥ ሁለተኛው ሳፋም፥ ጸሓፊው ያናይን፥ ሳፋጥም በባሳን ተቀመጡ።'),
  ('32c517a7-e707-5c6b-ae7e-c0c125867e9a', '33252d01-5770-50a0-ae17-b83c55c60780', '0be3c1d2-cd90-5055-af93-bb92c9ffdaf4', 3, 13, 'የአባቶቻቸው ቤቶች ወንድሞች ሚካኤል፥ ሜሱላም፥ ሳባ፥ ዮራይ፥ ያካን፥ ዙኢ፥ ኦቤድ እነዚህ ሰባት ነበሩ።'),
  ('9b3bf897-298a-5e6d-a06a-d34b169dff7a', '33252d01-5770-50a0-ae17-b83c55c60780', '0be3c1d2-cd90-5055-af93-bb92c9ffdaf4', 4, 14, 'እነዚህም የቡዝ ልጅ የዮዳይ ልጅ የኢዮሳይ ልጅ የሚካኤል ልጅ የገለዓድ ልጅ የኤዳይ ልጅ የዑሪ ልጅ የአቢካኤል ልጆች ነበሩ።'),
  ('ae2e3142-0ca4-5ff7-ac78-0f296014a1e6', '33252d01-5770-50a0-ae17-b83c55c60780', '0be3c1d2-cd90-5055-af93-bb92c9ffdaf4', 5, 15, 'የአባቶቻቸውም ቤቶች አለቃ የጎኔ ልጅ የአብዲኤል ልጅ ወንድም ነበር።'),
  ('701b17f5-dbbd-52dc-aee9-7e120bf80a7a', '33252d01-5770-50a0-ae17-b83c55c60780', '0be3c1d2-cd90-5055-af93-bb92c9ffdaf4', 6, 16, 'በገለዓድም ምድር በባሳን በመንደሮቹም በሳሮንም መሰማርያዎች ሁሉ እስከ ዳርቻቸው ድረስ ተቀምጠው ነበር።'),
  ('3224c934-8ff9-5798-a8a2-3a2a18d4440e', '33252d01-5770-50a0-ae17-b83c55c60780', '0be3c1d2-cd90-5055-af93-bb92c9ffdaf4', 7, 17, 'እነዚህ ሁሉ በትውልዶቻቸው በይሁዳ ንጉሥ በኢዮአታም ዘመንና በእስራኤል ንጉሥ በኢዮርብዓም ዘመን ተቈጠሩ።'),
  ('9e829352-cc33-51b9-ac1f-4895f9c63711', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 1, 18, 'የሮቤልና የጋድ ልጆች የምናሴም ነገድ እኩሌታ፥ ጽኑዓን ጋሻና ሰይፍ የሚይዙ፥ ቀስተኞችም፥ ሰልፍ የሚያውቁ ሰልፈኞችም፥ አርባ አራት ሺህ ሰባት መቶ ስድሳ ነበሩ።'),
  ('70e1aaad-cdb9-52ea-a1c6-98786f93179d', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 2, 19, 'ከአጋራውያንና ከኢጣርዮን ከናፋስዮንና ከናዳብዮን ጋር ተዋጉ።'),
  ('3ea6f8d6-9b62-5a17-addb-55bc0d7d381d', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 3, 20, 'በሚዋጉበትም ጊዜ ወደ እግዚአብሔር ጮኸዋልና በእርሱም ታምነዋልና አዳናቸው፤ በላያቸውም በረቱባቸው፥ አጋራውያንና ከእነርሱ ጋር የነበሩትም ሁሉ በእጃቸው ተሰጡ።'),
  ('048b5649-6a4e-5012-ab38-deea3cb91269', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 4, 21, 'ከከብቶቻቸውም አምሳ ሺህ ግመሎች፥ ሁለት መቶ አምሳ ሺህም በጎች፥ ሁለት ሺህም አህዮች፥ ከሰዎችም መቶ ሺህ ማረኩ።'),
  ('99e4c9ce-1236-5dc2-a01f-7543f6ec8f2b', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 5, 22, 'ሰልፉ ከእግዚአብሔር ዘንድ ነበረና ብዙ ሰዎች ተገድለው ወደቁ፤ እስከ ምርኮም ዘመን ድረስ በስፍራቸው ተቀመጡ።'),
  ('22c5198b-980f-5415-ab23-da7477781217', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 6, 23, 'የምናሴም የነገድ እኩሌታ ልጆች፤ ከባሳን ጀምሮ እስከ በኣልአርሞንና እስከ ሳኔር እስከ አርሞንኤም ተራራ እስከ ሊባኖስ ድረስ ተቀመጡ፤ እነርሱም በዙ።'),
  ('09da41e2-c54d-570e-a504-7e33c5eccf60', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 7, 24, 'የአባቶቻቸውም ቤቶች አለቆች እነዚህ ነበሩ፤ ዔፌር፥ ይስዔ፥ ኤሊኤል፥ ዓዝርኤል፥ ኢይርምያ፥ ሆዳይዋ፥ ኢየድኤል፤ እነርሱ ጽኑዓን ኀያላን የታወቁ ሰዎች የአባቶቻቸውም ቤቶች አለቆች ነበሩ።'),
  ('4e2691c1-1119-5742-ac0f-720c95a998d4', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 8, 25, 'የአባቶቻቸውንም አምላክ በደሉ፤ እግዚአብሔርም ከፊታቸው ባጠፋቸው በምድሩ አሕዛብ አማልክት አመነዘሩ።'),
  ('3a513599-5fbb-548b-a4a7-0772c3197c09', '33252d01-5770-50a0-ae17-b83c55c60780', '8abcb210-0244-5049-ad37-d0e60943d174', 9, 26, 'የእስራኤልም አምላክ የአሦርን ንጉሥ የፋሎክን መንፈስ፥ የአሦርንም ንጉሥ የቴልጌልቴልፌልሶርን መንፈስ አስነሣ፤ የሮቤልንና የጋድን ልጆች የምናሴንም ነገድ እኩሌታ አፈለሰ፥ እስከ ዛሬም ወዳሉበት ወደ አላሔና ወደ ኦቦር፥ ወደ ሃራንና ወደ ጎዛን ወንዝ አመጣቸው።'),
  ('1dee977a-1f78-563d-af5e-12bb94ce6692', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 1, 1, 'የሌዊ ልጆች፤ ጌድሶን፥ ቀዓት ሜራሪ።'),
  ('dc730ce8-8057-58e8-a1f9-ab1e8104239d', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 2, 2, 'የቀዓትም ልጆች፤ እንበረም፥ ይስዓር፥ ኬብሮን፥ ዑዝኤል።'),
