  ('61aa3158-8aa2-5fdc-ac1c-8d49bfb92630', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 4, 4, 'አልዓዛር ፊንሐስን ወለደ፤ ፊንሐስም አቢሱን ወለደ፤'),
  ('903e0e05-3dcc-5ce0-a9bc-bf5de07335bd', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 5, 5, 'አቢሱም ቡቂን ወለደ፤ ቡቂም ኦዚን ወለደ፤'),
  ('c91045fd-e2cd-55f9-a017-a209b2cb6a66', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 6, 6, 'ኦዚም ዘራእያን ወለደ፤ ዘራእያም መራዮትን ወለደ፤'),
  ('855288f7-8dbe-5eb4-aec9-6b1d048a619d', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 7, 7, 'መራዮትም አማርያን ወለደ፤ አማርያም አኪጦብን ወለደ፤'),
