  ('0b79a67d-1429-5e6e-aaec-6f6fbc6e5c0b', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 11, 11, 'ዓዛርያስም አማርያን ወለደ፤ አማርያም አኪጦብን ወለደ፤'),
  ('94b439a5-b264-534d-a8a2-db8cd734eff4', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 12, 12, 'አኪጦብም ሳዶቅን ወለደ፤ ሳዶቅም ሳሎምን ወለደ፤'),
  ('1d07c599-d695-5dd2-a8c7-8247ddbee002', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 13, 13, 'ሳሎምም ኬልቅያስን ወለደ፤ ኬልቅያስም ዓዛርያስን ወለደ፤'),
  ('a4b899cc-744f-5360-aba1-57a9c2018c5d', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 14, 14, 'ዓዛርያስም ሠራያን ወለደ፤ ሠራያም ኢዮሴዴቅን ወለደ፤'),
  ('1b5a923c-ecc7-58e2-ac1b-e92ad03cfaec', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 15, 15, 'ኢዮሴዴቅም፥ ይሁዳና ኢየሩሳሌም በናቡከደነፆር እጅ በተማረኩ ጊዜ ተማርኮ ሄደ።'),
  ('1b80b37a-bec7-5420-a5a1-d6dde29fa159', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 16, 16, 'የሌዊ ልጆች፤ ጌድሶን፥ ቀዓት፥ ሜራሪ።'),
  ('f5717c3d-3c5d-59c0-a336-7f7ec4e9160c', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 17, 17, 'የጌድሶንም ልጆች ስም ይህ ነው፤ ሎቤኒ፥ ሰሜኢ።'),
  ('f196b5a4-639b-5203-a684-5741de625920', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 18, 18, 'የቀዓትም ልጆች፤ እንበረም፥ ይስዓር፥ ኬብሮን፥ ዑዝኤል ነበሩ።'),
  ('728ea1ed-cf68-534f-aa59-efb587469c6a', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 19, 19, 'የሜራሪም ልጆች፤ ሞሐሊ፥ ሙሲ፥ የሌዋውያን ወገኖች በየአባቶቻቸው ቤቶች እነዚህ ናቸው።'),
  ('d703cbe7-9412-5ede-a480-8bf53413211e', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 20, 20, 'ከጌድሶን፤ ልጁ ሎቤኒ፥ ልጁ ኢኤት፥ ልጁ ዛማት፤'),
  ('d86b2002-27b4-5f07-a056-588dd7ff575f', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 21, 21, 'ልጁ ዮአክ፥ ልጁ አዶ፥ ልጁ ዛራ፥ ልጁ ያትራይ።'),
  ('111c4835-4d3a-5558-ac5b-6b6272adb93f', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 22, 22, 'የቀዓት ልጆች፤ ልጁ አሚናዳብ፥ ልጁ ቆሬ፥ ልጁ አሴር፤'),
