  ('b3bf8aa3-f19e-57cd-a9c0-a00a1d7f45d2', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 44, 44, 'በግራቸውም በኩል የሚቆሙ ወንድሞቻቸው የሜራሪ ልጆች ነበሩ፤ ኤታን የቄሳ ልጅ፥ የአብዲ ልጅ፥ የማሎክ ልጅ፤'),
  ('d9d02906-8baf-5230-a07a-fa00b43a52ef', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 45, 45, 'የአሳቢ ልጅ፥ የአሜስያስ ልጅ፥ የኬልቅያስ ልጅ፤'),
  ('79ab213e-8110-54c6-a25a-a7474276ca3f', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 46, 46, 'የአማሴ ልጅ፥ የባኒ ልጅ፥ የሴሜር ልጅ፤'),
  ('3176042f-bd05-5de9-ac5a-319b2a03e1d8', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 47, 47, 'የሞአሊ ልጅ፥ የሙሲ ልጅ፥ የሜራሪ ልጅ፥ የሌዊ ልጅ።'),
  ('2b0e40a1-2d93-5583-a11f-0a15e6a84581', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 48, 48, 'ወንድሞቻቸውም ሌዋውያን እንደ እየባቶቻቸው ቤቶች ለእግዚአብሔር ቤት ሥራ አገልግሎት ሁሉ ተሰጡ።'),
  ('dfa4a9e6-44c4-5f3b-a266-0346b55d0310', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 49, 49, 'አሮንና ልጆቹ ግን የእግዚአብሔር አገልጋይ ሙሴ እንዳዘዘው ሁሉ ለቅድስተ ቅዱሳን ሥራ ሁሉ ስለ እስራኤልም ያስተሰርይ ዘንድ ለሚቃጠለው መሥዋዕት በሚሆነው መሠዊያ ላይ ይሠዉ ነበር፥ በዕጣኑም መሠዊያ ላይ ያጥኑ ነበር።'),
  ('e429bc32-5f5a-5705-af73-8b09f44155b6', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 50, 50, 'የአሮንም ልጆች ስሞች እነዚህ ናቸው፤ ልጁ አልዓዛር፥ ልጁ ፊንሐስ፥ ልጁ አቢሱ፤'),
  ('b779e588-8f70-577c-a0b9-0dac9a30cd02', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 51, 51, 'ልጁ ቡቂ፥ ልጁ ኦዚ፥ ልጁ ዘራእያ፤'),
