  ('964d14ed-712c-5a3b-a30e-5385c705562f', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 53, 53, 'ልጁ ሳዶቅ፥ ልጁ አኪማኦስ።'),
  ('f0ee1cf4-51a2-5c7d-a2c8-824d01bb5cca', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 54, 54, 'ማደሪያዎቻቸውም በየሰፈራቸው በየዳርቻቸው እነዚህ ናቸው፤ ለአሮን ልጆች ለቀዓት ወገኖች አንደኛው ዕጣ ነበረ።'),
  ('7a77b310-b7f9-568d-a036-9301fce93bb8', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 55, 55, 'ለእነርሱ በይሁዳ ሀገር ያለችውን ኬብሮንን፥ በእርስዋም ዙሪያ የነበረውን መሰማሪያ ሰጡ፤'),
  ('d80f7c62-e318-57e0-a249-17c4e41cebd1', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 56, 56, 'የከተማዪቱን እርሻ ግን መንደሮችዋንም ለዮፎኒ ልጅ ለካሌብ ሰጡ።'),
  ('be404571-e0ab-53d9-af24-c5ed0434885f', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 57, 57, 'ለአሮንም ልጆች የመማፀኛውን ከተሞች፥ ኬብሮንን፥ ልብናንና መሰማርያዋን፥ ሴልናንና መሰማሪያዋን፤ ኤስትሞዓንና መሰማሪያዋን ሰጡ።'),
  ('acef34f4-b4b5-50cc-a79d-7f87bb9835d4', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 58, 58, 'የኢያቴርን ከተማና መሰማሪያዋን፥ ዳቤርንና መሰማሪያዋን፤'),
  ('5c1015ca-9c79-5030-a762-d30dee15da10', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 59, 59, 'ዓሳንንና መሰማሪያዋን፥ ቤትሳሚስንና መሰማሪያዋን፤'),
  ('13412099-95ed-541f-ac2b-45a79394305c', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 60, 60, 'ከብንያምም ነገድ ጌባንና መሰማርያዋን፥ ጋሌማትንና መሰማሪያዋን፥ ዓናቶትንና መሰማሪያዋን ሰጡ። ከተሞቻቸው ሁሉ በየወገናቸው ዐሥራ ሦስት ነበሩ።'),
  ('22d6bc8b-979d-547c-a704-3e249a10b5d3', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 61, 61, 'ለቀሩትም ለቀዓት ልጆች ከምናሴ ነገድ እኩሌታ ዐሥር ከተሞች በዕጣ ተሰጡ።'),
  ('65907b3e-49fa-5a39-a185-a9501a3e3794', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 62, 62, 'ለጌድሶንም ልጆች በየወገናቸው ከይሳኮር ነገድ፥ ከአሴርም ነገድ፥ ከንፍታሌምም ነገድ፥ በባሳንም ካለው ከምናሴ ነገድ፥ ዐሥራ ሦስት ከተሞች ተሰጡ።'),
  ('500387ab-692b-52cb-a25f-5e3f85a9eb05', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 63, 63, 'ለሜራሪም ልጆች በየወገናቸው ከሮቤል ነገድ፥ ከጋድም ነገድ፥ ከዛብሎንም ነገድ፥ ዐሥራ ሁለት ከተሞች በዕጣ ተሰጡ።'),
  ('3a91144f-795c-5442-a575-db5a020b6279', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 64, 64, 'የእስራኤልም ልጆች ለሌዋውያን ከተሞችን ከመሰማሪያዎቻቸው ጋር ሰጡ።'),
  ('8030ce76-e669-5625-aef9-bebf50e1af8f', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 65, 65, 'ከይሁዳም ልጆች ነገድ፥ ከስምዖንም ልጆች ነገድ፥ ከብንያምም ልጆች ነገድ፥ እነዚህን በስማቸው የተጠሩትን ከተሞች በዕጣ ሰጡ።'),
  ('5511dfcc-a362-5dff-a6a4-39e7420b141a', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 66, 66, 'ከቀዓትም ልጆች ወገኖች ለአንዳንዶቹ ከኤፍሬም ነገድ ከተሞች ድርሻ ነበራቸው።'),
  ('300efd18-9c5b-5337-ae94-725d78a7f54e', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 67, 67, 'በተራራማው በኤፍሬም ሀገር ያሉትን የመማፀኛውን ከተሞች ሴኬምንና መሰማሪያዋን፥ ደግሞም ጋዜርንና መሰማሪያዋን፤'),
  ('0967d42c-4f4d-58c1-a5c5-06df438d5c61', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 68, 68, 'ዮቅምዓምንና መሰማሪያዋን፥ ቤትሖሮንንና መሰማሪያዋን፤'),
  ('36d26dbe-c39d-5915-a3b4-ec9f076c7ba0', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 69, 69, 'ኤሎንንና መሰማሪያዋን፥ ጋትሪሞንንና መሰማሪያዋን ሰጡአቸው።'),
  ('b249035b-9c7c-5f6a-ada6-38da5a3f772f', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 70, 70, 'ከምናሴም ነገድ እኩሌታ ዓኔርንና መሰማሪያዋን፥ ቤልዓምንና መሰማሪያዋን፥ ከቀዓት ልጆች ወገን ለቀሩት ሰጡ።'),
  ('4e1168c0-e031-5957-a689-02657c37f08a', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 71, 71, 'ለጌድሶን ልጆች ከምናሴ ነገድ እኩሌታ ወገን በባሳን ያለችው ጋውሎንና መሰማሪያዋ፥ አስታሮትና መሰማሪያዋ፤'),
  ('a7acdb5f-55bb-530c-a61d-3991e6908302', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 72, 72, 'ከይሳኮርም ነገድ ቃዴስና መሰማሪያዋ፥ ዳብራትና መሰማሪያዋ፤'),
  ('971bfce8-6a8b-5091-aef3-0e721682e49c', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 73, 73, 'ራሞትና መሰማሪያዋ፥ ዓኔምና መሰማሪያዋ፤'),
  ('4f754644-3f15-57c7-a2d5-3930b691ec49', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 74, 74, 'ከአሴርም ነገድ መዓሳልና መሰማሪያዋ፥ ዓብዶንና መሰማሪያዋ፤'),
  ('16221e2a-dfe3-5ec5-a610-f171f5fc9716', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 75, 75, 'ሐቆቅና መሰማሪያዋ፥ ረዓብና መሰማሪያዋ፤'),
  ('34b24c92-a908-59d5-aec6-b5b9d7a0090b', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 76, 76, 'ከንፍታሌምም ነገድ በገሊላ ያለችው ቃዴስና መሰማሪያዋ፥ ሐሞንና መሰማሪያዋ፥ ቄርያታይምና መሰማሪያዋ ተሰጡ።'),
  ('9e004015-b56c-55b6-a6d2-d532dcab6208', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 77, 77, 'ለቀሩትም ለሜራሪ ልጆች ከዛብሎን ነገድ ሬሞንና መሰማሪያዋ፥ ታቦርና መሰማሪያዋ፤'),
  ('334838be-3cce-53f8-a5d0-74b747c0481d', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 78, 78, 'ከሮቤልም ነገድ በኢያሪኮ አንጻር በዮርዳኖስ ማዶ በምሥራቅ በኩል በምድረ በዳ ያለችው ቦሶርና መሰማሪያዋ፥ ያሶንና መሰማሪያዋ፤'),
  ('666a92af-ba2a-5398-a030-d4477c15189c', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 79, 79, 'ቅዴሞትና መሰማሪያዋ፥ ሜፍዓትና መሰማሪያዋ፤'),
  ('a07599e6-923d-5fbe-abd6-afc171857822', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 80, 80, 'ከጋድም ነገድ በገለዓድ ያለችው ሬማትና መሰማሪያዋ፥ መሃናይምና መሰማሪያዋ፤'),
  ('2ecbe616-0da4-5a4e-a207-033c5fce4766', '24d660c1-ff25-57ab-a661-c23b03b507fe', 'cbfba7aa-c9ee-5601-a271-b9655210a0cc', 81, 81, 'ሐሴቦንና መሰማሪያዋ፥ ኢያዜርና መሰማሪያዋ ተሰጡ።'),
  ('dc8238a8-b45c-50fb-ab89-5b008cc6e665', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 1, 1, 'የይሳኮርም ልጆች፤ ቶላ፥ ፋዋ፥ ያሱብ፥ ሰምሮን፥ አራት ናቸው።'),
  ('c7c8e15d-3f3a-5a33-ada4-241c43249039', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 2, 2, 'የቶላም ልጆች፤ ኦዚ፥ ረፋያ፥ ይሪኤል፥ የሕማይ፥ ይብሣም፥ ሰሙኤል፥ የአባታቸው የቶላ ቤት አለቆች፥ በትውልዳቸው ጽኑዓን ኀያላን ሰዎች ነበሩ፤ በዳዊት ዘመን ቍጥራቸው ሃያ ሁለት ሺህ ስድስት መቶ ነበረ።'),
  ('31c17ff9-0516-5586-a372-75e0654de033', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 3, 3, 'የኦዚም ልጆች ይዝረሕያ፤ የይዝረሕያም ልጆች ሚካኤል፥ አብድዩ፥ ኢዩኤል፥ ይሴያ አምስት ናቸው፤ ሁሉም አለቆች ነበሩ።'),
  ('4f22470f-e4c9-5dd4-a628-b1a4b4191e41', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 4, 4, 'ከእነርሱም ጋር በየትውልዳቸው በየአባቶቻቸው ቤት ለሰልፍ የተዘጋጁ የሠራዊት ጭፍሮች ነበሩ፤ ብዙም ሴቶችና ልጆች ነበሩአቸውና ሠላሳ ስድስት ሺህ ነበሩ።'),
  ('d307f921-bd15-5426-ab59-9f327700bd34', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 5, 5, 'ወንድሞቻቸውም በይሳኮር ወገኖች ሁሉ ጽኑዓን ኀያላን ሰዎች በትውልዳቸው ሁሉ የተቈጠሩ ሰማንያ ሰባት ሺህ ነበሩ።'),
  ('439d5231-a287-58b4-ab59-df3a7f21d66e', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 6, 6, 'የብንያም ልጆች ቤላ፥ ቤኬር፥ ይድኤል ሦስት ነበሩ።'),
  ('a6a91421-bca2-52a6-a8d2-bab49fcb9566', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 7, 7, 'የቤላም ልጆች፥ ኤሲቦን፥ ኦዚ፥ ዑዝኤል፥ ኢያሬሙት፥ ዔሪ አምስት ነበሩ፤ የአባቶቻቸው ቤቶች አለቆች፥ ጽኑዓን ኀያላን ሰዎች ነበሩ፤ ቍጥራቸውም ሃያ ሁለት ሺህ ሠላሳ አራት ነበሩ።'),
  ('316ac8d2-885f-54dc-a704-59274a39193f', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 8, 8, 'የቤኬርም ልጆች ዝሜራ፥ ኢዮአስ፥ አልዓዛር፥ ኤልዮኤናይ፥ ዖምሪ፥ ኢያሪሙት፥ ዓብያ፥ ዓናቶት፤ ዓሌሜት፤ እነዚህ ሁሉ የቤኬር ልጆች ነበሩ።'),
  ('f2440a67-8eeb-5d59-a19a-124fca1fb082', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 9, 9, 'በየትውልዳቸውም መዝገብ የተቈጠሩ፥ የአባቶቻቸው ቤቶች አለቆች፥ ጽኑዓን ኀያላን ሰዎች ሃያ ሺህ ሁለት መቶ ነበሩ።'),
  ('29c2ca6d-71de-5697-a262-7ba4b829a7db', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 10, 10, 'የይዴኤልም ልጅ ቢልሐን ነበረ፤ የቢልሐንም ልጆች የዑስ፥ ብንያም፥ ኤሁድ፥ ክንዓና፥ ዜታን፥ ተርሴስ፥ አኬሳአር ነበሩ።'),
  ('888d051d-e1d8-5bd4-aa88-686568f72d1b', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 11, 11, 'እነዚህ ሁሉ የይዴኤል ልጆች ነበሩ፤ በየአባቶቻቸው ቤቶች አለቆች፥ ጭፍራ እየሆኑ ወደ ሰልፍ የሚወጡ ጽኑዓን ኀያላን ሰዎች ዐሥራ ሰባት ሺህ ሁለት መቶ ነበሩ።'),
  ('71113b4e-fb0b-5959-ae12-21cdaaf5e1fa', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 12, 12, 'ደግሞም ሳፊን፥ ሑፊም የዔር ልጆች፥ ሑሲም የአሔር ልጅ ነበረ።'),
  ('4caa20ef-19dc-5670-a34c-00820a809c42', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 13, 13, 'የንፍታሌምም ልጆች፥ ያሕጽኤል፥ ጎኒ፥ ዬጽር፥ ሼሌም፥ እነዚህ አራቱ የባላ ልጆች ነበሩ።'),
  ('19d91d56-be34-5d92-a6f3-145ab8712df9', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 14, 14, 'የምናሴ ልጆች ሶሪያዪቱ ቁባቱ የወለደችለት አስርኤልና የገለዓድ አባት ማኪር ናቸው።'),
  ('030440c1-5a8c-53d5-a3b1-fb54adcc6a74', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 15, 15, 'ማኪርም ከሑፊምና ከሳፊን ወገን ሚስት አገባ፤ የእኅትየዋም ስም መዓካ ነበረ፤ የሁለተኛውም ስም ሰለጰዓድ ነበረ፤ ለሰለጰዓድም ሴቶች ልጆች ነበሩት።'),
  ('9ea31584-4bf9-5678-a416-78c0c190d430', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 16, 16, 'የማኪርም ሚስት መዓካ ልጅ ወለደች፥ ስሙንም ፋሬስ ብላ ጠራችው፤ የወንድሙም ስም ሱሮስ ነበረ፤ ልጆቹም ኡላምና ራቄም ነበሩ።'),
  ('37f6b038-594d-5570-a9e1-8fd46ee582db', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 17, 17, 'የኡላምም ልጅ ባዳን ነበረ፤ እነዚህ የምናሴ ልጅ የማኪር ልጅ የገለዓድ ልጆች ነበሩ።'),
  ('7b580549-d878-5d97-a106-dd727c482d0f', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 18, 18, 'እኅቱ መለኪት ኢሱድን፥ አቢዔዜርን፥ መሕላን ወለደች።'),
  ('b12cb8c7-7e9b-53ff-abd4-ca381e34814a', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 19, 19, 'የሰሜራም ልጆች አሒያን፥ ሴኬም፥ ሌቅሔ፥ አኔዓም ነበሩ።'),
  ('c8f493bb-ac7e-58f4-ae03-e168fa3fb991', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 20, 20, 'የኤፍሬም ልጆች፤ ሱቱላ፥ ልጁ ባሬድ፥ ልጁ ታሐት፥ ልጁ ኤልዓዳ፥ ልጁ ታክት፤')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('47cf18ce-5b8f-5155-a6c0-a03b5444c797', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 21, 21, 'ልጁ ዛባድ፥ ልጁ ሹቱላ፥ ልጁ ኤድር፥ ልጁ ኤልዓድ ነበሩ፤ የሀገሩም ተወላጆች የጌት ሰዎች ከብቶቻቸውን ሊወስዱ ወርደው ነበርና ገደሉአቸው።'),
  ('0db478a9-cfbe-5b71-ace2-014f5e22239a', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 22, 22, 'አባታቸው ኤፍሬምም ብዙ ቀን አለቀሰ፤ ወንድሞቹም ሊያጽናኑት መጡ።'),
  ('44010d8a-dcc2-50d9-a866-e078405c1cdf', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 23, 23, 'ወደ ሚስቱም ገባ፥ አረገዘችም፤ ወንድ ልጅም ወለደች፤ በቤቴም መከራ ሆኖአልና ሲል ስሙን በሪዓ ብሎ ጠራው።'),
  ('416fd3d4-7ed7-5043-a4f5-ea3c2f0730e1', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 24, 24, 'የሴት ልጁም ስም ሲአራ ነበረ፤ በዚያም በቀሩት ታችኛውንና ላይኛውን ቤትሖሮንን ሠራ የኡዛንም ልጁ ሠይራ ነበረ፤'),
  ('ecfcd715-a06b-5a06-a1cb-59bb827c1033', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 25, 25, 'ወንዶች ልጆቹም ራፋኢ፥ ሳራፍ፥ ልጁ ቴላ፥ ልጁ ታሐን፤'),
  ('62f3ce69-c3fe-5f6a-ae48-b55291aa135a', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 26, 26, 'ልጁ ለአዳን፥ ልጁ ዓሜሁድ፥ ልጁ ኤሌሳማ፤'),
  ('25401b1d-ea2d-5ccb-aa70-5b6bbe13fdc3', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 27, 27, 'ልጁ ነዌ፥ ልጁ ኢያሱ።'),
  ('52681afa-1113-5e9a-a2e8-d9d82fa6fba9', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 28, 28, 'ግዛታቸውና ማደሪያቸው ቤቴልና መንደሮችዋ፥ በምሥራቅም በኩል ነዓራን፥ በምዕራብም በኩል ጌዝርና መንደሮችዋ፥ ደግሞም ሴኬምና መንደሮችዋ፥ እስከ ጋዛና እስከ መንደሮችዋ ድረስ፤'),
  ('4e4622ee-edab-5c51-a3c3-f13d493bd8c5', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 29, 29, 'በምናሴም ልጆች ዳርቻ ቤትሳንና መንደሮችዋ፥ ታዕናክና መንደሮችዋ፥ መጊዶና መንደሮችዋ፥ ዶርና መንደሮችዋ፥ በላድና መንደሮችዋ ነበሩ፤ በእነዚህ ያዕቆብ የተባለ የእስራኤል ልጅ የዮሴፍ ልጆች ተቀመጡ።'),
  ('0b32a640-c3e8-5e80-a29a-b5e32a8f851b', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 30, 30, 'የአሴር ልጆች፤ ኢያምና፥ የሱዋ፥ የሱዊ፥ በሬዓ፥ እኅታቸውም ሤራሕ ነበሩ።'),
  ('09a115f3-55e8-56fe-a851-807a97b1912e', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 31, 31, 'የበሪዓም ልጆች፤ ሔቤርና፥ የቤርዛዊት አባት የነበረው መልኪኤል ናቸው።'),
  ('f2013bdb-1efc-50f5-a1e1-de188a7722c6', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 32, 32, 'ሔቤርም ያፍሌጥን፥ ሳሜርን፥ ኮታምን፥ እኅታቸውንም ሶላን ወለደ።'),
  ('a24e5256-1ab2-5748-a8d9-67416ae0e5dc', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 33, 33, 'የያፍሌጥም ልጆች፤ ፋሴክ፥ ቢምሃል፥ ዓሴት ነበሩ፤ እነዚህ የያፍሌጥ ልጆች ነበሩ።'),
  ('ef8c83e3-2a85-56ff-aa6e-6586c50d3b7a', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 34, 34, 'የሳሜርም ልጆች፤ አኪ፥ ሮኦጋ፥ ይሁባ፥ አራም ነበሩ።'),
  ('50621522-4dd2-5520-ad2f-3dcdcb38f701', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 35, 35, 'የወንድሙም የኡላም ልጆች ጾፋ፥ ይምና፥ ሰሌስ፥ ዓማል ነበሩ።'),
  ('6d3f4a0e-8673-529e-a4de-6c3c233c5b72', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 36, 36, 'የጾፋም ልጆች፤ ሴዋ፥ ሐርኔፍር፥ ሦአል፥ ቤሪ፥ ይምራ፥'),
  ('b230f864-4a9d-5c08-a692-e8d0af159d58', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 37, 37, 'ቤጼር፥ ሆድ፦ ሳማ፦ ሰሌሳ፥ ይትራን፦ ብኤራ ነበሩ።'),
  ('4fe7bae1-31ce-5811-a995-398db4ed3f03', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 38, 38, 'የዬቴርም ልጆች፤ ያፊና፥ ፊስጳ፥ አራ ነበሩ።'),
  ('e117aaf3-8feb-57fc-a1c1-05a7860d9bb5', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 39, 39, 'የዑላ ልጆች፤ ኤራ፥ ሐኔኤል፥ ሪጽያ ነበሩ።'),
  ('5a771185-7d3c-5410-af53-3a0e6595d10e', '4ded709c-7745-5800-a430-b727c5bc0d60', '062b22db-ebab-51d3-a78c-69303ae643b4', 40, 40, 'እነዚህ ሁሉ የአሴር ልጆች፥ የአባቶቻቸው ቤቶች አለቆች፥ የተመረጡ ጽኑዓን ኀያላን ሰዎች፥ የመኳንንቱ አለቆች ነበሩ። በትውልዳቸውም በሰልፍ ለመዋጋት የተቈጠሩ ሃያ ስድስት ሺህ ሰዎች ነበሩ።'),
  ('f70e43a5-fb48-5f04-a9cc-5dd44d790c7b', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '0e5cb07a-27b2-5656-a212-698ae2ce20f8', 1, 1, 'ብንያምም በኵሩን ቤላን፥ ሁለተኛውንም አስቤልን፥ ሦስተኛውንም አሐራን፤'),
  ('288a9a97-131c-59cc-ac7d-7d59683574eb', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '0e5cb07a-27b2-5656-a212-698ae2ce20f8', 2, 2, 'አራተኛውንም ኖሐን፥ አምስተኛውንም ራፋን ወለደ።'),
  ('d9534fba-2c41-5f52-a312-3c765c3ba827', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '0e5cb07a-27b2-5656-a212-698ae2ce20f8', 3, 3, 'ለቤላም ልጆች ነበሩት፤ አዳር፥ ጌራ፥ አቤሁድ፤'),
  ('1545844e-ea5d-56fd-aff9-33fc92d8748a', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '0e5cb07a-27b2-5656-a212-698ae2ce20f8', 4, 4, 'አቤሱ፥ ናዕማን፥ አሖዋ፤'),
  ('17dc3e1e-076c-5fd5-a9bc-5a1723251b20', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '0e5cb07a-27b2-5656-a212-698ae2ce20f8', 5, 5, 'ጌራ፥ ሰፉፋም፥ ሑራም።'),
  ('86aa60e3-7aba-5dfe-a1a0-4088d2ca9a32', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '0e5cb07a-27b2-5656-a212-698ae2ce20f8', 6, 6, 'እነዚህ የኤሁድ ልጆች ናቸው፤ እነዚህ በጌባ የሚቀመጡ የአባቶቻቸው ቤቶች አለቆች ናቸው፤ ወደ መነሐትም ተማረኩ፤'),
  ('0739c395-43bf-515b-a2a2-b989e3c4c731', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '0e5cb07a-27b2-5656-a212-698ae2ce20f8', 7, 7, 'ናዕማን፥ አኪያ፥ ጌራ፥ እነርሱም ተማረኩ። ዖዛንና አሂሑድን ወለደ።'),
