  ('9c1596d4-d45b-5932-aad0-59179771f0bd', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '1accb06b-2279-51ad-a029-98aec84a62e9', 1, 33, 'ኔር ቂስን ወለደ፤ ቂስም ሳኦልን ወለደ፤ ሳኦልም ዮናታንን፥ ሜልኪሳን፥ አሚናዳብን፥ አስበኣልን ወለደ።'),
