  ('b245ab65-628c-585c-a578-587e3238a6f1', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '1accb06b-2279-51ad-a029-98aec84a62e9', 3, 35, 'የሚካም ልጆች ፒቶን፥ ሜሌክ፥ ታሬዓ፥ አካዝ ነበሩ።'),
