  ('780b4755-aa7a-51ae-adce-00729f9284ca', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '1accb06b-2279-51ad-a029-98aec84a62e9', 5, 37, 'ማሴዕም በዓናን ወለደ፤ ልጁም ራፋያ ነበረ፤ ልጁ ኤልዓሣ፥ ልጁ ኤሴል፤'),
