  ('8bf0adbb-b0b0-5e39-a7a9-985b121ee4b8', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '1accb06b-2279-51ad-a029-98aec84a62e9', 7, 39, 'የወንድሙም የአሴል ልጆች፤ በኵሩ ኡላም፥ ሁለተኛውም ኤያስ፥ ሦስተኛውም ኤሊፋላት።'),
  ('4b22a76c-a65e-5339-a11a-b659469bd40f', '24bc71b9-5e34-5ed1-a36d-2b83258194fc', '1accb06b-2279-51ad-a029-98aec84a62e9', 8, 40, 'የኡላም ልጆች ጽኑዓን ኀያላንና ቀስተኞች ነበሩ፤ ለእነርሱም መቶ አምሳ የሚያህሉ ብዙ ልጆችና የልጅ ልጆች ነበሩአቸው፤ እነዚህ ሁሉ የብንያም ልጆች ነበሩ።'),
  ('b86aab1b-3c52-509a-a1d7-2736e7f4c889', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 1, 1, 'እስራኤልም ሁሉ ስለ ኀጢአታቸው ወደ ባቢሎን ከተማረኩ በኋላ፥ በየትውልዳቸው ተቈጠሩ፤ እነሆም በእስራኤልና በይሁዳ ነገሥታት መጽሐፍ ተጽፈዋል።'),
  ('c3cf39f1-270c-5724-addc-6e9c956d46b2', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 2, 2, 'በእስራኤል ከተሞችና በአውራጃዎቻቸው መጀመሪያ የተቀመጡ ካህናት፥ ሌዋውያንም፥ አገልጋዮችም ነበሩ።'),
  ('25c5ecb9-b818-594b-a4da-8a20f58a50b2', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 3, 3, 'ከይሁዳ ልጆችና ከብንያም ልጆች፥ ከኤፍሬምና ከምናሴ ልጆች በኢየሩሳሌም ተቀመጡ።'),
