  ('fbde19ea-d2e6-5585-afbf-fa3e538ffada', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 5, 5, 'ከሴሎናውያንም በኵሩ ዓሣያና ልጆቹ።'),
  ('a6ed624b-a9a3-5520-a524-fe04a2f716d2', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 6, 6, 'ከዛራም ልጆች ኢያሄልና ወንድሞቻቸው፥ ስድስት መቶ ዘጠና።'),
  ('e85f593c-e3b3-53d8-a48e-04a272b6853a', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 7, 7, 'ከብንያምም ልጆች የሐስኑአ ልጅ የሆዳይዋ ልጅ የሜሱላም ልጅ ሰሎ፤'),
  ('2692a459-fb2a-5878-a0f0-8ef1fe555f55', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 8, 8, 'የይሮሐም ልጅ ኢያብናአ፤ የሚክሪ ልጅ የኦዚ ልጅ ኤላ፤ የበንያስ ልጅ የራጉኤል ልጅ የሰፋጥያስ ልጅ ሜሱላም፤'),
  ('028a0067-d693-5836-a6c1-cf12ea349a89', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 9, 9, 'በየትውልዳቸውም ወንድሞቻቸው ዘጠኝ መቶ አምሳ ስድስት ነበሩ፤ እነዚህ ሰዎች ሁሉ የአባቶቻቸው ቤቶች አለቆች ነበሩ።'),
  ('eb94462c-f239-5b0e-aec9-13913f0aad94', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 10, 10, 'ከካህናቱም ዮዳኤ፥ ዮአሪብ፥ ያኪን፤'),
  ('183e58b1-3e84-5936-a54d-d96da6da5d22', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 11, 11, 'የእግዚአብሔርም ቤት አለቃ የአኪጦብ ልጅ፥ የመራዩት ልጅ፥ የሳዶቅ ልጅ፥ የሜሱላም ልጅ የኬልቅያስ ልጅ ዓዛርያስ፤'),
  ('1424de06-db22-58b3-a649-454152fcb7b6', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 12, 12, 'የመልክያ ልጅ፥ የጳስኮር ልጅ፥ የይሮሐም ልጅ፥ አዳያ፤ የኤሜር ልጅ የምስልሞት ልጅ፥ የሜሱላም ልጅ፥ የኤሕዜራ ልጅ፥ የዓዴኤል ልጅ መዕሣይ፤'),
  ('64fdecba-8a5f-566c-a326-609ae5f2fd27', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 13, 13, 'የአባቶቻቸውም ቤቶች አለቆች ወንድሞቻቸው ሺህ ሰባት መቶ ስድሳ ነበሩ፤ ለእግዚአብሔር ቤትም ማገልገል ሥራ እጅግ ብቁዎች ሰዎች ነበሩ።'),
  ('d6c200eb-f990-5749-ad08-a857f589cb8f', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 14, 14, 'ከሌዋውያንም ልጆች ከሜራሪ ልጆች የአሳብያ ልጅ፥ የዓዝሪቃም ልጅ፥ የአሱብ ልጅ ሸማያ፤'),
  ('7d88a668-bbc3-5381-a204-f0d4baa3823f', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 15, 15, 'በቀባቃር፥ ኤሬስ፥ ጋላል፥ የአሳፍ ልጅ የዝክሪ ልጅ የሜካ ልጅ ማታንያስ፤ የኤዶታም ልጅ የጋላል ልጅ የሰማያ ልጅ አብድያ፤'),
  ('745fb093-bc1a-53e9-a0a9-4eb42abb4ee0', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 16, 16, 'በነጦፋውያንም መንደሮች የተቀመጠው የሕልቃና ልጅ የአሳ ልጅ በራክያ።'),
  ('48a6ac3e-bab8-54fd-ae3e-24113ea6afe7', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 17, 17, 'በረኞችም ሰሎም፥ ዓቁብ፥ ጤልሞን፥ አሒማን፥ ወንድሞቻቸውም ነበሩ፤ ሰሎምም አለቃ ነበረ።'),
  ('b56fd65e-e551-5348-a6d1-361b24c7ceb5', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 18, 18, 'እስከዛሬም ድረስ በንጉሥ በር በምሥራቅ በኩል ነበሩ፤ ለሌዊ ልጆች ሰፈር በረኞች ነበሩ።'),
  ('6e70aec4-19ab-5a3a-a731-7c846f81165c', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 19, 19, 'የቆሬም ልጅ የአብያሳፍ ልጅ የቆሬ ልጅ ሰሎም ከአባቱ ቤት የነበሩ ወንድሞቹ ቆሬያውያን በማገልገል ሥራ ላይ ነበሩ፤ የድንኳኑንም መድረክ ይጠብቁ ነበር። አባቶቻቸውም የእግዚአብሔርን ሰፈር መግቢያ ይጠብቁ ነበር።'),
  ('b6f031bf-fd8b-5482-a56a-152979d4dc6a', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 20, 20, 'አስቀድሞም የአልዓዛር ልጅ ፊንሐስ አለቃቸው ነበረ። እግዚአብሔርም ከእርሱ ጋር ነበረ።'),
  ('a64076f6-da03-5c5b-a660-99a603e82873', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 21, 21, 'የሜሱላም ልጅ ዘካርያስ የምስክሩ ድንኳን ደጅ በረኛ ነበረ።'),
  ('9de6c93b-d2bd-589b-ab76-f023b1fab520', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 22, 22, 'የመድረኩ በረኞች ይሆኑ ዘንድ የተመረጡ እነዚህ ሁሉ ሁለት መቶ ዐሥራ ሁለት ነበሩ። እነዚህ በመንደሮቻቸው በየትውልዳቸው ተቈጠሩ። ዳዊትና ነቢዩ ሳሙኤል ታማኝነታቸውን አይተው በሥራቸው አቆሙአቸው።'),
  ('9b3cb39f-30c1-5eac-a6d6-747f2d4f6a88', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 23, 23, 'እነርሱና ልጆቻቸውም በእግዚአብሔር ቤት በድንኳኑ ደጆች ላይ በረኞች ነበሩ።'),
  ('0be8d33d-8620-561f-ab82-68557e2542ae', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 24, 24, 'በአራቱ ማዕዘኖች፥ በምሥራቅ፥ በምዕራብ፥ በሰሜን፥ በደቡብ በሮች ነበሩ።'),
  ('7a3ba894-0090-5277-a5d9-edcc1c3a5b89', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 25, 25, 'ወንድሞቻቸውም በመንደሮቻቸው ሆነው፥ በየሰባቱ ቀን ከእነርሱ ጋር ሊሆኑ ከጊዜ ወደ ጊዜ ይገቡ ነበር።'),
  ('35cd6ab1-fea6-56ca-a10e-4f48b89497d0', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 26, 26, 'እነዚህ አራቱ ኀያላን ሰዎች ለአራቱ በሮች ኀላፊዎች ነበሩ። ሌዋውያንም በእግዚአብሔር ቤት ባሉ ጓዳዎችና ቤተ መዛግብት ላይ የተሾሙ ነበሩ።'),
  ('13470608-dbe9-536d-a91a-c485ced26814', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 27, 27, 'የእግዚአብሔርንም ቤት መክፈቻ የሚይዙ፥ ጥዋት ጥዋትም ደጆቹን የሚከፍቱ እነርሱ ነበሩና።'),
  ('fa00e003-93ee-5f51-a9f6-846784d39d56', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 28, 28, 'ዕቃውንም በቍጥር ያገቡና ያወጡ ነበርና ከእነዚህ አንዳንዶቹ በማገልገያው ዕቃ ላይ ሹሞች ነበሩ።'),
  ('f94618f7-7986-5eaa-a227-68112baf5514', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 29, 29, 'ከእነርሱ አንዳንዶቹ በአገልግሎቱ ዕቃዎች በመቅደሱ ዕቃ ሁሉ፥ በመልካሙም ዱቄት፥ በወይን ጠጁም፥ በዘይቱም፥ በዕጣኑም፥ በሽቱውም ላይ ሹሞች ነበሩ።'),
  ('c983007c-0043-542d-a85f-5fe8c072fb11', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 30, 30, 'ከካህናቱም ልጆች አንዳንዶቹ ዕጣኑንና የሽቱውን ቅባት ያዘጋጁ ነበር።'),
  ('c8b487ec-2f8f-5922-a1b4-9079dc6c9253', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 31, 31, 'የቆሬያዊውም የሰሎም በኵር ሌዋዊው ማቲትያ ለታላቁ ሊቀ ካህናት በምጣድ በሚጋገረው ነገር ላይ ሹም ነበረ።'),
  ('7c072b21-4451-575d-a767-9c273dcba29a', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 32, 32, 'በየሰንበቱም ያዘጋጁ ዘንድ ቀዓታዊው በንያስና ወንድሞቻቸው በገጹ ኅብስት ላይ ሹሞች ነበሩ።'),
  ('60897723-216f-50b8-a72a-b8228eeb195e', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 33, 33, 'ከሌዋውያንም ወገን የአባቶቻቸው ቤቶች አለቆች የነበሩ መዘምራን በየሰሞናቸው አገልጋዮችና ሹሞች ነበሩ፤ ሥራቸውም ሌሊትና ቀን ነበረ።'),
  ('a1f0dfe4-a7b4-54f6-ab70-0010fa3c50a9', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 34, 34, 'እነዚህ ከሌዋውያን የአባቶቻቸው ቤቶች አለቆች በየትውልዳቸው አለቆች ነበሩ። እነዚህም በኢየሩሳሌም ይቀመጡ ነበር።'),
  ('40e85325-4958-59cd-aaa1-3c95a617c353', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 35, 35, 'የሚስቱ ስም መዓካ የነበረው የገባዖን አባት ይዒኤል በገባዖን ይቀመጥ ነበረ።'),
  ('200a6aac-21dd-57ac-a6e9-43326c3bac99', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 36, 36, 'የበኵር ልጁም ስም ዓብዶን፥ሁለተኛው ሲር፥ ሦስተኛው ቂስ፥ አራተኛው በኣል፥ አምስተኛው ኔር፥ ስድስተኛውም ናዳብ፤'),
  ('1d431e16-cc25-59c4-a3d2-7997c6e70e91', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 37, 37, 'ሰባተኛው ግዱር፥ ወንድሙ ዘካርያስም፥ ሜቅሎትም።'),
  ('a3e58c83-2c1d-5de8-af3b-93a75c313d61', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 38, 38, 'ሜቅሎትም ሳምአን ወለደ፤ እነርሱም ደግሞ ከወንድሞቻቸው ጋር በኢየሩሳሌም በወንድሞቻቸው መካከል ይቀመጡ ነበር።'),
  ('be476e11-20db-54cd-a133-b04a19cc6a39', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 39, 39, 'ኔርም ቂስን ወለደ፤ ቂስም ሳኦልን ወለደ፤ ሳኦልም ዮናታንን፥ ሜልኪሳን፥ አሚናዳብን፥ አስበኣልን ወለደ።'),
  ('b47d6a09-177d-52af-aa4a-619a7c062b4a', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 40, 40, 'የዮናታንም ልጅ መሪበኣል ነበረ፤ መሪበኣልም ሚካን ወለደ።'),
  ('9afb215a-c6f8-5cf8-a960-6af4d70355a0', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 41, 41, 'የሚካም ልጆች ፒቶን፥ ሜሌክ፥ ታራ፥ አካዝ ነበሩ፤'),
  ('7e2bc386-eaa2-5789-a75d-f9759f714714', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 42, 42, 'አካዝም ኢያዳዕን ወለደ፤ ኢያዳዕም ጋሌሜትን፥ ጋዝሞትን፥ ዘምሪን ወለደ፤ ዘምሪም ማሳዕን ወለደ።'),
  ('833cde69-54e2-5ad3-a132-5a609100210d', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 43, 43, 'ማሳዕም በዓናን ወለደ፥ ልጁ ረፋያ ነበረ፥ ልጁ ኤልዓሣ፥ ልጁ ኤሴል፤'),
  ('80fdc929-28d0-51eb-ab3b-46d46fcb5248', 'f35aa104-7e26-590f-a3e2-909685305c21', 'c5d93aa6-0792-5ac3-acbe-6975042df0a4', 44, 44, 'ለኤሴልም ስድስት ልጆች ነበሩት፤ ስማቸውም ይህ ነበረ፤ ዓዝሪቃም፥ ቦኬርዩ፥ እስማኤል፥ ሰዓርያ፥ አብድዩ፥ ሐናን፤ እነዚህ የኤሴል ልጆች ነበሩ።'),
  ('0bbc2f75-50b1-5265-a8be-8736975e951f', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 1, 1, 'በዚያም ወራት ፍልስጥኤማውያን ከእስራኤል ጋር ተዋጉ፤ የእስራኤልም ሰዎች ከፍልስጥኤማውያን ፊት ሸሹ፥ ተወግተውም በጌላቡሄ ተራራ ላይ ወደቁ።'),
  ('d38eb7fb-e06e-5164-a8bd-345f34076550', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 2, 2, 'ፍልስጥኤማውያንም ሳኦልንና ልጆቹን በእግር በእግራቸው ተከትለው አባረሩአቸው፤ ፍልስጥኤማውያንም የሳኦልን ልጆች ዮናታንንና አሚናዳብን ሜልኪሳንም ገደሉ።'),
  ('f550a155-096f-578a-a070-3687a679b783', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 3, 3, 'ሰልፍም በሳኦል ላይ ጠነከረ። ቀስተኞችም አግኝተው ወጉት፤ ከቀስቶችም ኀይል የተነሣ ተጨነቀ።'),
  ('ae238d96-a441-5ec4-aa98-6fecb54bdc8d', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 4, 4, 'ሳኦልም ጋሻ ጃግሬውን፥ “እነዚህ ቈላፋን መጥተው እንዳይዘብቱብኝ ሰይፍህን መዝዘህ ውጋኝ” አለው። ጋሻ ጃግሬው ግን እጅግ ፈርቶ ነበርና እንቢ አለ። ሳኦልም ሰይፉን ወስዶ በላዩ ወደቀ።'),
  ('f0a0d523-5a48-5733-aaf6-70bcfad1dfdc', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 5, 5, 'ጋሻ ጃግሬውም ሳኦል እንደ ሞተ ባየ ጊዜ እርሱ ደግሞ በሰይፉ ላይ ወድቆ ሞተ።'),
  ('16d69c5a-27bf-5d99-a04b-39ca602a3bf6', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 6, 6, 'ሳኦልና ሦስቱም ልጆቹ የቤቱም ሰዎች ሁሉ በዚያች ቀን በአንድ ላይ ሞቱ።'),
  ('c54db716-86df-5413-a4d1-40691ce7515a', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 7, 7, 'በሸለቆውም የነበሩት የእስራኤል ሰዎች ሁሉ እስራኤል እንደ ሸሹ፥ ሳኦልና ልጆቹም እንደ ሞቱ ባዩ ጊዜ ከተሞቻቸውን ለቅቀው ሸሹ፤ ፍልስጥኤማውያንም መጥተው ተቀመጡባቸው።'),
  ('6ec92bde-6ec4-5384-afd6-60fd8b3eb4f4', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 8, 8, 'በነጋውም ፍልስጥኤማውያን የሞቱትን ለመግፈፍ በመጡ ጊዜ ሳኦልንና ልጆቹን በጌላቡሄ ተራራ ላይ ወድቀው አገኙአቸው።'),
  ('d1ec6ddc-1397-5696-a88b-27940a1c12b8', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 9, 9, 'ሳኦልንም ገፈፉት፥ ራሱንም ቈርጠው መሣሪያውንም አንሥተው ለጣዖቶቻቸውና ለሕዝቡ የምሥራች ይወስዱ ዘንድ ወደ ፍልስጥኤማውያን ሀገር ዙሪያ ሰደዱ።'),
  ('f6035a34-80a8-5f07-ae15-ab62735c9d30', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 10, 10, 'መሣሪያውንም በአምላኮቻቸው ቤት ውስጥ አኖሩ፤ ራሱንም በዳጎን ቤት ውስጥ አኖሩት፤'),
  ('a77992ba-2ef2-5e27-ace7-0fa2969b54b9', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 11, 11, 'የገለዓድም ሰዎች ሁሉ ፍልስጥኤማውያን በሳኦልና በእስራኤል ላይ ያደረጉትን ሁሉ ሰሙ።'),
  ('ebf84782-ae30-59c4-a0f8-a58b09cc63aa', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 12, 12, 'ጽኑዓን ሰዎች ሁሉ ከገለዐድ ተነሥተው የሳኦልን ሬሳ የልጆቹንም ሬሳዎች ወሰዱ፥ ወደ ኢያቢስም አመጡአቸው፤ በኢያቢስም ካለው ከትልቁ ዛፍ በታች አጥንቶቻቸውን ቀበሩ፥ ሰባት ቀንም ጾሙ።'),
  ('d017604c-7ef8-5fdb-a37f-a0717998cb32', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 13, 13, 'እንዲሁ ሳኦል በእግዚአብሔር ላይ ስላደረገው ኀጢአት፥ እግዚአብሔርም እንዳዘዘው የእግዚአብሔርን ቃል ስላልጠበቀ ሞተ። ደግሞም መናፍስት ጠሪን ጠየቀ።'),
  ('e3e0c0e7-5594-5321-a582-18ec339053e2', '2df4b7c6-bc5f-56e0-ac83-54ae0ce2b70c', '313f7441-cd82-556a-aca4-73f42fad0ae0', 14, 14, 'ነቢዩ ሳሙኤልም መለሰለት፤ ወደ እግዚአብሔርም ይመለስ ዘንድ አልሰማውም፥ ስለዚህ ገደለው፤ መንግሥቱንም ወደ እሴይ ልጅ ወደ ዳዊት አሳለፈው።'),
  ('7cef20f6-873b-5f26-a440-64f1ac10dc49', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 1, 1, 'እስራኤልም ሁሉ በኬብሮን ወደ ዳዊት ተሰብስበው እንዲህ አሉት፥ “እነሆ፥ እኛ የአጥንትህ ፍላጭ የሥጋህ ቍራጭ ነን፤'),
  ('bd2d69de-f7de-5ee7-ac83-8469f3509261', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 2, 2, 'አስቀድሞ ሳኦል ንጉሥ ሆኖ ሳለ እስራኤልን የምታወጣና የምታገባ አንተ ነበርህ፤ አምላክህ እግዚአብሔርም፦ ሕዝቤን እስራኤልን አንተ ትጠብቃለህ፤ በሕዝቤም በእስራኤል ላይ አለቃ ትሆናለህ” አለህ።'),
  ('b0ff305e-3f0d-551f-a691-318855fe89d6', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 3, 3, 'የእስራኤልም ሽማግሌዎች ሁሉ ወደ ንጉሡ ወደ ኬብሮን መጡ፤ ንጉሥ ዳዊትም በኬብሮን በእግዚአብሔር ፊት ቃል ኪዳን ከእነርሱ ጋር አደረገ፤ በሳሙኤልም እጅ እንደ ተናገረው እንደ እግዚአብሔር ቃል በእስራኤል ላይ ንጉሥ ይሆን ዘንድ ዳዊትን ቀቡት።'),
  ('daa54b2a-7bcf-5a35-adfa-32c88c7e3ad8', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 4, 4, 'ዳዊትና የእስራኤልም ሰዎች ሁሉ ኢያቡስ ወደምትባል ወደ ኢየሩሳሌም ሄዱ፤ በሀገሩም የተቀመጡ ኢያቡሳውያን በዚያ ነበሩ።'),
  ('62f4d057-43c5-5958-ab7b-236ad7437b56', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 5, 5, 'በኢያቡስም የተቀመጡ ዳዊትን፥ “ወደዚህ አትገባም” አሉት፤ ዳዊት ግን አንባዪቱን ጽዮንን ያዘ፤ እርስዋም የዳዊት ከተማ ናት።'),
  ('2f34f2c8-a9a7-569a-ad13-fe898b758e1a', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 6, 6, 'ዳዊትም ኢያቡሳውያንን አስቀድሞ የሚመታ ሰው አለቃና መኰንን ይሆናል አለ። የሶርህያም ልጅ ኢዮአብ አስቀድሞ ወጣና ወጋቸው፥ አለቃም ሆነ።'),
  ('54a43e33-21bc-53a0-aa5d-17c922d415e8', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 7, 7, 'ዳዊትም በአንባዪቱ ውስጥ ተቀመጠ፤ ስለዚህም “የዳዊት ከተማ” ብለው ጠሩአት።'),
  ('a0a159d0-08b6-5843-ad35-ddd3d4c73614', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 8, 8, 'ዳዊትም የከተማዋን ዙሪያ ቀጸረ፤ ተዋግቶም እጅ አደረጋት።'),
  ('82ac1665-5d47-59ee-ac67-dc9fdcf7d26f', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cc175738-8682-5479-a40b-f6c2d604af62', 9, 9, 'ዳዊትም ሁሉን ቻይ እግዚአብሔር ከእርሱ ጋር ነበረና እየበረታ ሄደ።'),
  ('22c29bc6-6239-521e-a9af-0f44450892e7', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 1, 10, 'ለዳዊትም የነበሩት ኀያላን አለቆች እነዚህ ናቸው፤ ስለ እስራኤል እንደ ተናገረው እንደ እግዚአብሔር ቃል ያነግሡት ዘንድ ከእስራኤል ሁሉ ጋር በመንግሥቱ አጸኑት።'),
  ('a9c3e16b-1284-5842-a061-0863c3a3e5c3', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 2, 11, 'የዳዊትም ኀያላን ቍጥር ይህ ነበረ፤ የሠላሳው አለቃ የአኪማን ልጅ ኢያቡስቴ ነበረ፤ እርሱ ጦሩን አንሥቶ ሦስት መቶ ሰው በአንድ ጊዜ ገደለ።'),
  ('5eac7ebf-dcca-5fdf-a554-77a09825214c', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 3, 12, 'ከእርሱም በኋላ በሦስቱ ኀያላን መካከል የነበረ የአሆሃዊው የዱዲ ልጅ አልዓዛር ነበረ።'),
  ('b2cef3af-1cca-5fa3-a658-853f7a7faf34', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 4, 13, 'እርሱ ከዳዊት ጋር በፋሶደሚን ነበረ፥ በዚያም ገብስ በሞላበት እርሻ ውስጥ ፍልስጥኤማውያን ለሰልፍ ተሰብስበው ነበር፤ ሕዝቡም ከፍልስጥኤማውያን ፊት ሸሹ።'),
  ('2b4401c8-2e8e-52fc-aded-5a4a20ee7e0a', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 5, 14, 'በእርሻውም መካከል ቆመው ጠበቁት፥ ያችንም ቦታ አዳናት፤ ፍልስጥኤማውያንንም ገደላቸው፤ እግዚአብሔርም በታላቅ ማዳን አዳናቸው።'),
  ('c2ebed92-8100-5ea9-a530-333198f901e5', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 6, 15, 'ከሠላሳውም አለቆች ሦስቱ ወርደው ዳዊት ወዳለበት ወደ ዓለቱ ወደ ዓዶላም ዋሻ መጡ፤ የፍልስጥኤማውያንም ጭፍራ በኀያላን ሸለቆ ሰፍሮ ነበር።'),
  ('8bb77510-e851-5838-a65a-68747aa114a2', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 7, 16, 'በዚያም ጊዜ ዳዊት በምሽጉ ውስጥ ነበረ፤ የፍልስጥኤማውያንም ጭፍራ በቤተ ልሔም ነበረ።'),
  ('1d2429e7-37de-5fb0-ad0f-62645b7213e4', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 8, 17, 'ዳዊትም፥ “በበሩ አጠገብ ካለችው ከቤተ ልሔም ምንጭ ውኃ ማን ይሰጠኛል?” ብሎ ተመኘ።'),
  ('a5598f4b-ea85-5e5f-a6bb-e42a165ceb20', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 9, 18, 'እነዚህ ሦስቱ ኀያላን የፍልስጥኤማውያንን ሰፈር ሰንጥቀው ሄዱ፥ በበሩም አጠገብ ካለችው ከቤተ ልሔም ምንጭ ውኃ ቀዱ፤ ይዘውም ለዳዊት አመጡለት። እርሱ ግን ሊጠጣ አልወደደም፥ ነገር ግን ለእግዚአብሔር አፍስሶ፦'),
  ('186b8bfb-5073-5bb5-ab2d-5c18578e110a', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 10, 19, '“ይህን አደርግ ዘንድ አምላኬ ሆይ፥ ለእኔ አይገባኝም፤ ሰውነታቸውንም ለሞት አሳልፈው አምጥተውታልና የእነዚህን ሰዎች ደም እጠጣለሁን?” አለ። ስለዚህም ዳዊት ይጠጣው ዘንድ አልወደደም። ሦስቱም ኀያላን ያደረጉት ይህ ነው።'),
  ('f3d62d5c-27c3-5c20-a8e8-27426004531f', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 11, 20, 'የኢዮአብም ወንድም አቢሳ የሦስቱ አለቃ ነበረ፤ ሰይፉንም በሦስት መቶ ላይ አንሥቶ በአንድ ጊዜ ገደላቸው፤ በሦስቱም መካከል ስሙ የተጠራ ነበረ።'),
  ('2004ad4c-4ed3-53f2-adb1-10e49c56bc8e', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 12, 21, 'በሁለተኛውም ተራ በሆኑት በሦስቱ መካከል የከበረ ነበረ፥ አለቃቸውም ሆነ፤ ነገር ግን ወደ ፊተኞቹ ወደ ሦስቱ አልደረሰም።'),
  ('235d5b1e-5225-5fc2-aecf-89cf235b15a7', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 13, 22, 'በቀበሳኤል የነበረው፥ ታላቅ ሥራ ያደረገው የጽኑዕ ሰው የዮዳሄ ልጅ በናያስ እንደ አንበሳ ኀያላን የነበሩትን ሁለት የሞዓብ ሰዎች ገደለ፤ በአመዳይም ወራት ወርዶ በጕድጓድ ውስጥ አንበሳ ገደለ።'),
  ('e3779a45-84aa-581e-a7db-220a881c6bd3', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 14, 23, 'ቁመቱም አምስት ክንድ የነበረውን ረጅሙን ግብፃዊውን ሰው ገደለ፤ በግብፃዊውም እጅ የሸማኔ መጠቅለያ የመሰለ ጦር ነበረ፤ እርሱ ግን በትር ይዞ ወደ እርሱ ወረደ፥ ከግብፃዊውም እጅ ጦሩን ቀምቶ በገዛ ጦሩ ገደለው።'),
  ('918e2693-33d5-5bed-a97c-31163be787ff', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 15, 24, 'የዮዳሄ ልጅ በናያስ ያደረገው ይህ ነው፤ ስሙም በሦስቱ ኀያላን መካከል የተጠራ ነበረ።'),
  ('d867d8ff-bacb-5248-a5df-dadb20b0fd77', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 16, 25, 'እነሆ፥ ከሠላሳው ይልቅ የከበረ ነበረ፤ ነገር ግን ወደ ፊተኞቹ ወደ ሦስቱ አልደረሰም። ዳዊትም በናያስን በሀገሩ ላይ ሾመው።'),
  ('eb479c75-95a3-5cd2-ad83-8deac3c13b3a', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 17, 26, 'ደግሞም በጭፍሮቹ ዘንድ የነበሩት ኀያላን እነዚህ ናቸው፤ የኢዮአብ ወንድም አሣሄል፥ የቤተ ልሔሙ ሰው የዱዲ ልጅ ኤልያናን፤'),
  ('520a22cf-6686-5ba4-a590-dde43e1467f6', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 18, 27, 'ሃሮራዊው ሳሞት፥ ፈሎናዊው ኬሌስ፤'),
  ('94cda743-5e59-58fc-aa32-42319da9a280', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 19, 28, 'የቴቁሔ ሰው የአቂስ ልጅ ኦራ፥ ዓናቶታዊው አቤዔዜር፤'),
  ('3ba4848b-b2e0-5427-a37a-91b61dc7e1b4', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 20, 29, 'ኩሳታዊው ሰቦካይ፥ የአሆሂው ዔላይ፤'),
  ('fbba68df-ec4a-507c-ab29-8b216669c16b', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 21, 30, 'ነጦፋዊው ሜሐሪ፥ የነጦፋዊው የበዓና ልጅ ሔሌድ፤'),
  ('38db98b1-2251-511d-af19-ec25625b7447', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 22, 31, 'ከብንያም ወገን ከጊብዓ የሪባይ ልጅ ኢታይ፥ ፈርኖታዊው ባንያስ፤'),
  ('f48e70ce-6f2f-5998-a21a-d3d47f98b230', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 23, 32, 'የገዓዝ ወንዝ ሰው ኡሪ፥ ገራባታዊው አብኤል፥'),
  ('f17df29d-1cc0-5fe1-ae39-237d58cb6ae1', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 24, 33, 'ባሮማዊው ዓዝሞት፥ ሰዓልቦናዊው ኤሊያሕባ፤'),
  ('982bab6d-9f26-5352-a789-e3d5fb0d4a7d', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 25, 34, 'የጊዞንያዊው የኤሳም ልጅ፥ የአሩራዊው የሶላ ልጅ ዮናታን፤'),
  ('48f0c241-5d19-5e18-aac3-20781d88ee4b', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 26, 35, 'የአሮራዊው የሳኮር ልጅ አህያም፥ የኤር ልጅ ኤሊፋል፤'),
  ('93a498f4-176c-512f-ad0b-098e5f6b389e', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 27, 36, 'መከራታዊው ኦፌር፥ ፍሎናዊው አኪያ፤'),
  ('ea4e2344-03ce-5989-a5d2-03b333abd1d4', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 28, 37, 'ቀርሜሎሳዊው ሴራይ፥ የኤዝባይ ልጅ ናራይ፤'),
  ('977c84b3-6089-5433-a487-5bada6d44e10', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 29, 38, 'የናታንም ወንድም ኢዩኤል፥ የሐገሪ ልጅ ሚብሐር፤'),
  ('4ec4937d-5576-5c97-a080-9dd76a420330', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 30, 39, 'አሞናዊው ሴሌቅ፥ የሦርህያ ልጅ የኢዮአብ ጋሻ ጃግሬ ቤሮታዊው ናኮር፤'),
  ('99314314-4da6-5a76-aed0-cf2b67657cbe', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 31, 40, 'ይትራዊው ዔራ፥ ይትራዊው ጋሬብ፤'),
  ('ef25e486-98eb-5b58-af8c-2d9f9ea84f7a', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 32, 41, 'ኬጢያዊው ዑርያስ፥ የአሕላይ ልጅ ዘባት፤'),
  ('c1b00eb5-c14f-585d-a236-0a339eb772ea', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 33, 42, 'የሮቤላዊው የሲዛ ልጅ ዓዲና፥ እርሱ የሮቤላውያን አለቃ ነበረ ከእርሱም ጋር ሠላሳ ሰዎች ነበሩ፤'),
  ('89829e29-4f7a-56f0-a283-0fa9e7c48bc6', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 34, 43, 'የሞካ ልጅ ሐናን፥ ሚትናዊው ኢዮሣፍጥ፤'),
  ('d177ec63-f1a5-5b9b-a70e-11f8195a47fd', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 35, 44, 'አስታሮታዊው ዖዝያ፥ የአሮዔራዊው የኮታም ልጆች ሳማና ይዒኤል፤'),
  ('57f1d30f-3759-5b95-a70f-99731d2bef68', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 36, 45, 'የሳምሪ ልጅ ይዳኤል፥ ወንድሙም ቲዳዊው ዮዛሔ፥'),
  ('2dce0370-16f8-590c-a8f6-f57e42954378', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 37, 46, 'መዓዊው ኤሊኤል፤ ኢያርባኢ፥ ልጁ ዮሳኢ፥ ኤልነዓምና ሞዓባዊው ይትማ፤'),
  ('96979538-cd49-5328-a9b5-fa612b4ccc54', 'ef220dcf-78c3-5cb2-a1f5-780eb1400dd3', 'cb5e3d05-aefc-5faf-a355-06ca60568022', 38, 47, 'ኤሊኤል፥ ዖቤድ፥ ምሶባዊው ኢያስኤል።'),
  ('e2e85a40-0616-568a-a191-20928925fe6f', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '15c2298f-17ad-5d72-a0a1-6fe047f0bf90', 1, 1, 'በሴቅላቅም ከቂስ ልጅ ከሳኦል በተሸሸገ ጊዜ ወደ ዳዊት የመጡ እነዚህ ናቸው፤ በጦርነትም ባገዙት ኀያላን መካከል ነበሩ።'),
  ('5d7d186e-7eb0-53c0-a826-0c72ae36dbca', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '15c2298f-17ad-5d72-a0a1-6fe047f0bf90', 2, 2, 'ቀስተኞችም ነበሩ፤ በቀኝና በግራም እጃቸው ድንጋይ ሊወነጭፉ፥ ፍላጻም ሊወረውሩ ይችሉ ነበር፤ ከብንያም ወገን የሳኦል ወንድሞች ነበሩ።'),
  ('62004a39-5a2b-5531-a99f-303d74b91080', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '15c2298f-17ad-5d72-a0a1-6fe047f0bf90', 3, 3, 'አለቃቸውም አኬዘር ነበረ፤ የጊብዓዊው የሰማዓ ልጅ ኢዮአስ፥ የዓዝሞት ልጆች ኢዮኤልና ፋሌጥ፥ በራኪያና ዓናቶታዊው ኢዩ፤'),
  ('77c2f2e6-a5a1-56ca-a728-e4dcaf85c7a5', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '15c2298f-17ad-5d72-a0a1-6fe047f0bf90', 4, 4, 'ገባዖናዊው ሰማያስ፥ እርሱ በሠላሳው መካከልና በሠላሳው ላይ ኀያል ሰው ነበረ፤ ኤርምያስ፥ ሕዝኤል፥ ዮሐናን፥ ገድሮታዊ ዮዛባት፤'),
  ('afebdde1-29ce-5c38-a5b6-6711f8918104', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '15c2298f-17ad-5d72-a0a1-6fe047f0bf90', 5, 5, 'ኤልዮዝ፥ ኢያሪሙት፥ በዓልያ፥ ሰማራያ፥ ሐሩፋዊው ሰፋጥያስ፤'),
  ('4fb3f8d1-c867-5a1b-a413-3e01daa33df7', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '15c2298f-17ad-5d72-a0a1-6fe047f0bf90', 6, 6, 'ቆሬያውያን ሕልቃና፥ ኢሰያ፥ ዓዘርኤል፥ ዮዛር፥ ይሰከአም።'),
  ('125485c1-e142-5ff2-a2e9-75f08515f3a4', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '15c2298f-17ad-5d72-a0a1-6fe047f0bf90', 7, 7, 'የግዶር ሰው የይሮሐም ልጆች ዮዔላ፥ ዝባድያ።'),
  ('7ec206fe-bd48-5336-ab9e-08e816bdc167', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'c37add7e-d55e-5b5e-a4d4-33d721a1808c', 1, 8, 'ዳዊትም በምድረ በዳ ውስጥ ባለችው በአንባዪቱ ሳለ ከጋድ ወገን የሆኑ እነዚህ ጋሻና ጦር የሚይዙ፥ ጽኑዓን፥ ኀያላን ሰልፈኞች፥ ወደ እርሱ ተጠጉ፤ ፊታቸውም እንደ አንበሳ ፊት ነበረ፤ በተራራም ላይ እንደሚዘልል ሚዳቋ ፈጣኖች ነበሩ።'),
  ('db56eb02-9bf7-5b30-a72d-9cdabd171c31', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'c37add7e-d55e-5b5e-a4d4-33d721a1808c', 2, 9, 'አለቃው አዝር፥ ሁለተኛው አብድያ፥ ሦስተኛው ኤልያብ፤'),
  ('c5913464-d714-5dc2-a86e-cb717ccfca24', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'c37add7e-d55e-5b5e-a4d4-33d721a1808c', 3, 10, 'አራተኛው መስመና፥ አምስተኛው ኤርምያስ፥'),
  ('38fff371-25a3-51aa-a202-3097336a2e09', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'c37add7e-d55e-5b5e-a4d4-33d721a1808c', 4, 11, 'ስድስተኛው ኤቲ፥ ሰባተኛው ኤሊኤል፥'),
  ('c331944a-7005-55b9-a931-46acae90517a', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'c37add7e-d55e-5b5e-a4d4-33d721a1808c', 5, 12, 'ስምንተኛው ዮሐናን፥ ዘጠነኛው ኤልዛባድ፥'),
  ('596cbb65-3410-558a-a5a1-e8a36571217e', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'c37add7e-d55e-5b5e-a4d4-33d721a1808c', 6, 13, 'ዐሥረኛው ኤርምያስ፥ ዐሥራ አንደኛው መክበናይ።'),
  ('5ed3ef5c-1dd5-527d-afe1-b62d0903f7be', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'c37add7e-d55e-5b5e-a4d4-33d721a1808c', 7, 14, 'እነዚህ የጋድ ልጆች የጭፍራ አለቆች ነበሩ፤ ከእነርሱም ታናሹ የመቶ አለቃ ታላቁ የሺህ አለቃ ነበር።'),
  ('19972f11-ae21-5d98-add9-b453fd689374', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'c37add7e-d55e-5b5e-a4d4-33d721a1808c', 8, 15, 'በመጀመሪያው ወር ዮርዳኖስ ከዳር እስከ ዳር ሞልቶ በነበረ ጊዜ የተሻገሩት እነዚህ ናቸው፤ በሸለቆውም ውስጥ በምሥራቅና በምዕራብ በኩል የተቀመጡትን ሁሉ አባረሩ።'),
  ('72384e00-6b26-5e75-af19-963a645181f9', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '3aea4d91-31df-5f88-ae41-0829dd412d1b', 1, 16, 'ዳዊትም ወደ ነበረባት ወደ አንባዪቱ ከብንያምና ከይሁዳ ወገን ሰዎች ዳዊትን ለመርዳት መጡ።'),
  ('fa6a3927-92d5-5857-a7fd-20ec64aaca5a', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '3aea4d91-31df-5f88-ae41-0829dd412d1b', 2, 17, 'ዳዊትም ሊገናኛቸው ወጥቶ፥ “በሰላም ወደ እኔ መጥታችሁ እንደ ሆነ ልቤ ከእናንተ ጋር አንድ ይሆናል፤ ለጠላቶቼ አሳልፋችሁ ልትሰጡኝ መጥታችሁ እንደ ሆነ ግን፥ በእጄ ዓመፅ የለብኝምና የአባቶቻችን አምላክ ይመልከተው፥ ይፍረደውም፤” አላቸው።'),
  ('dcb89e63-c424-58a0-a6a9-825387d32745', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', '3aea4d91-31df-5f88-ae41-0829dd412d1b', 3, 18, 'መንፈስም በሠላሳው አለቃ በዓማሣይ ላይ መጣ፤ እርሱም፥ “ዳዊት ሆይ፥ እኛ ያንተ ነን፤ የእሴይ ልጅ ሆይ፥ እኛ ከአንተ ጋር ነን፤ ውጣ አምላክህ ይረዳሃልና ሰላም ሰላም ለአንተ ይሁን፤ ለሚረዱህም ሰላም ይሁን” አለ። ዳዊትም ተቀበላቸው፤ የጭፍራም አለቆች አደረጋቸው።'),
  ('dae806bd-9ba4-58f7-a191-423f4051997c', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'febfe8db-3e78-599f-ac0c-5dd7cbbcd7ec', 1, 19, 'ዳዊትም ከፍልስጥኤማውያን ጋር ሳኦልን ሊወጋ በመጣ ጊዜ ከምናሴ ወገን ሰዎች ወደ ዳዊት ከዱ፤ የፍልስጥኤማውያን አለቆች ግን፥ “በራሳችን ላይ ጉዳት አድርጎ ወደ ጌታው ወደ ሳኦል ይመለሳል” ሲሉ ተማክረው ሰድደውታልና እርሱ አልረዳቸውም።'),
  ('47d6baea-f34d-5604-a6bd-49f754006d53', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'febfe8db-3e78-599f-ac0c-5dd7cbbcd7ec', 2, 20, 'ዳዊትም ወደ ሴቄላቅ ሲሄድ ከምናሴ ወገን የምናሴ ሻለቆች የነበሩ ዓድና፥ ዮዛባት፥ ይዲኤል፥ ሚካኤል፥ ዮዛባት፥ ኤሊሁና ጼልታይ ወደ እርሱ ከዱ።'),
  ('9486408d-aee9-54f0-a672-574333067475', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'febfe8db-3e78-599f-ac0c-5dd7cbbcd7ec', 3, 21, 'ሁሉም ጽኑዓን ኀያላንና በሠራዊቱ ላይ አለቆች ነበሩና በአደጋ ጣዮች ላይ ዳዊትን አገዙት።'),
  ('82f42bde-d4ac-5be4-a04b-68b0f78a0141', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'febfe8db-3e78-599f-ac0c-5dd7cbbcd7ec', 4, 22, 'እንደ እግዚአብሔርም ሠራዊት ታላቅ ሠራዊት እስኪሆን ድረስ ዳዊትን ለመርዳት ዕለት ዕለት ይመጡ ነበር።'),
  ('297ad4f2-c630-54ac-a3c4-3908acfe0016', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 1, 23, 'እንደ እግዚአብሔርም ቃል የሳኦልን መንግሥት ወደ እርሱ ይመልሱ ዘንድ በኬብሮን ሳለ ወደ ዳዊት የመጡት የሠራዊቱ አለቆች ቍጥር ይህ ነው።'),
  ('65218b27-86df-5b41-aaf7-c74d2b7693e9', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 2, 24, 'ጋሻና ጦር ተሸክመው ለሰልፍ የተዘጋጁ የይሁዳ ልጆች ስድስት ሺህ ስምንት መቶ ነበሩ።'),
  ('46fe7356-c4e3-58b1-a370-cba7ab69bf88', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 3, 25, 'ለሰልፍ ጽኑዓን ኀያላን ሰዎች የነበሩ የስምዖን ልጆች ሰባት ሺህ አንድ መቶ ነበሩ።'),
  ('558ea4e1-91f5-528e-af4f-c0b37e42a68a', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 4, 26, 'የሌዊ ልጆች አራት ሺህ ስድስት መቶ ነበሩ።'),
  ('d6a67c13-5d91-5cb8-a527-147f3fe90db7', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 5, 27, 'የአሮንም ቤት አለቃ ዮዳሄ ነበረ፤ ከእርሱም ጋር ሦስት ሺህ ሰባት መቶ ነበሩ፤'),
  ('0885cbde-c349-5b5a-a275-54f111ab3dd7', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 6, 28, 'ከእርሱም ጋር ጽኑዕ ኀያል ጐልማሳ ሳዶቅ ነበረ፤ ከአባቱም ቤት ሃያ ሁለት አለቆች ነበሩ።'),
  ('fd391dfb-9dbd-5be3-a950-9ba9c2b72e40', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 7, 29, 'የሳኦልም ወንድሞች ከሆኑ ከብንያም ልጆች ሦስት ሺህ ነበሩ። የሚበልጠው ክፍል የሳኦልን ቤት ይጠብቁ ነበሩ።'),
  ('14b3ac89-b583-537c-a1ac-fd3cba5e734e', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 8, 30, 'ጽኑዓን ኀያላን የሆኑ በአባቶቻቸውም ቤት የታወቁ የኤፍሬም ልጆች ሃያ ሺህ ስምንት መቶ ነበሩ።'),
  ('35ea8c07-16cf-51a3-aa7b-8f5aed7e79ff', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 9, 31, 'በየስማቸው የተጻፉ ዳዊትን ያነግሡት ዘንድ የመጡ የምናሴ ነገድ እኩሌታ ዐሥራ ስምንት ሺህ ነበሩ።'),
  ('08a4c3d6-672c-5e7b-a578-8c3fb517fd6a', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 10, 32, 'እስራኤልም የሚገባውን ያደርግ ዘንድ ዘመኑን የሚያውቁ ጥበበኞች ሰዎች የይሳኮር ልጆች አለቆች ሁለት መቶ ነበሩ፤ ወንድሞቻቸውም ሁሉ ከእነርሱ ጋር ነበሩ።'),
  ('0b652dad-7439-5fdb-aefb-3f69f68cc491', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 11, 33, 'በጭፍራውም ውስጥ ዳዊትን ለመርዳት የወጡ የተዘጋጁ፥ መሣሪያም ሁሉ የያዙ የዛብሎን ሰዎች አምሳ ሺህ ነበሩ፤ ከእነርሱ አንድስ እንኳ ደካማ አልነበረም።'),
  ('7a5fec53-26e4-565d-a19f-ebec3812e049', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 12, 34, 'የንፍታሌምም አለቆች አንድ ሺህ ነበሩ፥ ከእነርሱም ጋር ጋሻና ጦር የሚይዙ ሠላሳ ሰባት ሺህ ነበሩ።'),
  ('eb6cb560-4608-55dd-affe-74fcc0489fa2', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 13, 35, 'ለሰልፍም የተዘጋጁ የዳን ሰዎች ሃያ ስምንት ሺህ ስድስት መቶ ነበሩ።'),
  ('a72a3897-9b49-530d-a663-c2f85f75ce64', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 14, 36, 'በጭፍራውም ውስጥ የሚወጡ፥ ለሰልፍም የተዘጋጁ የአሴር ሰዎች አርባ ሺህ ነበሩ።'),
  ('5c842131-fd28-5797-a8c9-5c8a162a4d99', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 15, 37, 'በዮርዳኖስም ማዶ ካሉ ከሮቤልና ከጋድ ሰዎች ከምናሴም ነገድ እኩሌታ የጦር መሣሪያንም ሁሉ ይዘው የመጡ መቶ ሃያ ሺህ ነበሩ።'),
  ('984a4de9-d9e2-59d3-a620-9ae5ad413939', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 16, 38, 'እነዚህ ሁሉ ዳዊትን በእስራኤል ሁሉ ላይ ያነግሡት ዘንድ አርበኞችና ሰልፈኞች እየሆኑ በፍጹም ልባቸው ወደ ኬብሮን መጡ፤ ደግሞም ከእስራኤል የቀሩት ሁሉ ዳዊትን ያነግሡት ዘንድ አንድ ልብ ነበሩ።'),
  ('5e3120b9-24cc-512d-aa74-fc3f9a8451ad', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 17, 39, 'ወንድሞቻቸውም አዘጋጅተውላቸው ነበርና እየበሉና እየጠጡ በዚያ ከዳዊት ጋር ሦስት ቀን ተቀመጡ።'),
  ('2f0f1c25-2453-57e5-a15a-c5eeae403451', 'a8a8e60e-ba29-525f-a0e2-17eb386c636a', 'ea4ef293-68e9-51a5-a7d5-3eec2bfba397', 18, 40, 'ደግሞም በእስራኤል ዘንድ ደስታ ሆኖአልና እስከ ይሳኮርና እስከ ዛብሎን እስከ ንፍታሌምም ድረስ ለእርሱ አቅራቢያ የነበሩ በአህያና በግመል በበቅሎና በበሬ ላይ እንጀራና ዱቄት የበለስ ጥፍጥፍና የዘቢብ ዘለላ የወይንም ጠጅ፥ ዘይትም በሬዎችንና በጎችንም፥ ፍየሎችንም በብዙ አድርገው ያመጡ ነበር።'),
  ('adbc040d-8f33-5e65-a6c9-24015a4a2c48', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 1, 1, 'ዳዊትም ከሻለቆችና ከመቶ አለቆች፥ ከአለቆቹም ሁሉ ጋር ተማከረ።'),
  ('e9c87c12-3f80-5fb7-a7ea-fca8454db97c', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 2, 2, 'ዳዊትም የእስራኤልን ጉባኤ ሁሉ፥ “መልካም መስሎ የታያችሁ እንደ ሆነ፥ አምላካችን እግዚአብሔርም ፈቅዶ እንደ ሆነ፥ በእስራኤል ሀገር ሁሉ ለቀሩት ወንድሞቻችን በከተሞቻቸውና በመሰማሪያዎቻቸው ለሚቀመጡ ካህናትና ሌዋውያን ወደ እኛ ይሰበሰቡ ዘንድ እንላክ።'),
  ('83099c73-cc5d-55ad-acb0-49dc88a1de10', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 3, 3, 'ከሳኦልም ዘመን ጀምሮ አልፈለጓትምና የአምላካችን የእግዚአብሔርን ታቦት ወደ እኛ እንመልሳት” አላቸው።'),
  ('02cc694f-5462-5fbf-a8be-c13eb629cf4f', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 4, 4, 'ነገሩም በሕዝቡ ሁሉ ዐይን ዘንድ ቅን ነበረና የእስራኤል ጉባኤ ሁሉ፥ “እንዲሁ እናደርጋለን” አሉ።'),
  ('d719c338-7979-5fb3-a971-1ce44728dbe7', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 5, 5, 'የእግዚአብሔርንም ታቦት ከቂርያትይዓሪም ያመጡ ዘንድ ዳዊት እስራኤልን ሁሉ ከግብፅ ዳርቻ ጀምሮ እስከ ኤማት መግቢያ ድረስ ሰበሰበ።'),
  ('734ef044-4cb7-5e59-afa7-a87d5111b008', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 6, 6, 'ዳዊትም፥ እስራኤልም ሁሉ በኪሩቤል ላይ የተቀመጠውን፥ ስሙም በእርስዋ የተጠራባትን የአምላክን የእግዚአብሔርን ታቦት ከዚያ ያወጡ ዘንድ በይሁዳ ወዳለችው ቂርያትይዓሪም ሄዱ።'),
  ('dec9e0df-9d3c-5adb-a4e0-b02433666f66', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 7, 7, 'የእግዚአብሔርንም ታቦት ከአሚናዳብ ቤት በተገኘ በአዲስ ሰረገላ ላይ አኖሩአት። ዖዛና ወንድሞቹም ሰረገላውን ይነዱ ነበር።'),
  ('9b15bff8-b165-500e-a9a6-e284bcf6a995', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 8, 8, 'ዳዊትና እስራኤል ሁሉ ከመዘምራን ጋር በበገና፥ በመሰንቆና በከበሮ፥ በጸናጽልና በመለከት በእግዚአብሔር ፊት በሙሉ ኀይላቸው ይዘምሩ ነበር።'),
  ('30a73180-f060-5653-a66b-2d8c5e8a67d8', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 9, 9, 'ወደ አውድማ ዳርም በደረሱ ጊዜ ላሞቹ ሰረገላውን ሲስቡ የእግዚአብሔር ታቦት ዘንበል ብላለችና ታቦቷን ሊይዝ ዖዛ እጁን ዘረጋ።'),
  ('88350644-8d89-585d-a754-ff9ed23735a8', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 10, 10, 'እግዚአብሔርም በዖዛ ላይ ተቈጣ። እጁንም ወደ እግዚአብሔር ታቦት ስለ ዘረጋ ቀሠፈው፤ በዚያም በእግዚአብሔር ፊት ሞተ።'),
  ('23059cce-9057-5120-a133-af06199b1bad', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 11, 11, 'እግዚአብሔርም ዖዛን ስለ ሰበረው ዳዊት አዘነ፤ እስከ ዛሬም ድረስ የዚያን ስፍራ ስም “የዖዛ ስብራት” ብሎ ጠራው።'),
  ('e985f99f-c70c-5f1e-a1f5-b99b51f10760', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 12, 12, 'በዚያም ቀን ዳዊት፥ “የእግዚአብሔርን ታቦት ወደ እኔ እንዴት አመጣለሁ?” ብሎ እግዚአብሔርን ፈራ።'),
  ('beae7860-162e-561b-ade7-b044ec537ebb', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 13, 13, 'ዳዊትም የእግዚአብሔርን ታቦት ወደ ጌት ሰው ወደ አቢዳራ ቤት አሳለፋት እንጂ ወደ እርሱ ወደ ዳዊት ከተማ አላመጣትም።'),
  ('59a11143-aeb0-5b45-a002-c38e7f625b69', '165aac8d-de5f-55eb-a31d-6653cff4bfe4', '32fa8abe-6111-5e3f-a06a-8033ab2f0609', 14, 14, 'የእግዚአብሔርም ታቦት በጌት ሰው በአቢዳራ ቤት ውስጥ ሦስት ወር ተቀመጠች፤ እግዚአብሔርም አቢዳራንና ቤተ ሰቡን ሁሉ ባረከ።'),
  ('6033e33e-c22f-5f0c-acb6-b0aa0fe8cab2', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', 'ea5e3558-0ec5-5101-a358-2e6a9d0210aa', 1, 1, 'የጢሮስም ንጉሥ ኪራም ቤት ይሠሩለት ዘንድ መልእክተኞችን፥ የዝግባ እንጨትንም፥ ጠራቢዎችንም፥ አናጢዎችንም ወደ ዳዊት ላከ።'),
  ('16c20770-ec6b-58a3-a126-0e1b1fd4b914', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', 'ea5e3558-0ec5-5101-a358-2e6a9d0210aa', 2, 2, 'ስለ ሕዝቡም ስለ እስራኤል፥ መንግሥቱ እጅግ ከፍ ብሎአልና እግዚአብሔር በእስራኤል ላይ ንጉሥ እንዲሆን እንዳዘጋጀው ዳዊት ዐወቀ።'),
  ('9736dd82-1021-522a-ad36-d7e52245aef2', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', 'ea5e3558-0ec5-5101-a358-2e6a9d0210aa', 3, 3, 'ዳዊትም በኢየሩሳሌም ሌሎች ሚስቶችን ጨምሮ አገባ፤ ሌሎች ወንዶችና ሴቶች ልጆችም ተወለዱለት።'),
  ('994f17c8-5eb6-541f-a3d5-c3506de3634b', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', 'ea5e3558-0ec5-5101-a358-2e6a9d0210aa', 4, 4, 'በኢየሩሳሌምም የተወለዱለት የልጆቹ ስም ይህ ነው፤ ሳማ፥ ሶባብ፥ ናታን፥ ሰሎሞን፤'),
  ('b726ef30-70cc-5e06-ad2b-43b012a9d65c', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', 'ea5e3558-0ec5-5101-a358-2e6a9d0210aa', 5, 5, 'በዓር፥ ኤሊሳዒ፥ ኤሌፋላት፤'),
  ('d62e1045-26a8-5534-aaaa-68bae393b867', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', 'ea5e3558-0ec5-5101-a358-2e6a9d0210aa', 6, 6, 'ናጌት፥ ናፋት፥ ያፍያ፥'),
  ('6491a3f1-c353-53a5-a1d9-e4d609a74aaf', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', 'ea5e3558-0ec5-5101-a358-2e6a9d0210aa', 7, 7, 'ኤሊሳማ፥ በለዓዳ፥ ኤሊፋላት።'),
  ('62245788-f15f-5a48-a782-b295108056dd', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 1, 8, 'ፍልስጥኤማውያንም ዳዊት በእስራኤል ሁሉ ላይ ንጉሥ ሆኖ እንደ ተቀባ ሰሙ፤ ፍልስጥኤማውያንም ሁሉ ዳዊትን ሊፈልጉ ወጡ፤ ዳዊትም በሰማ ጊዜ ሊጋጠማቸው ወጣ።'),
  ('0aa47091-8ab9-50ad-a788-c7ba781eec6a', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 2, 9, 'ፍልስጥኤማውያንም መጥተው በኀያላን ሸለቆ ተሰበሰቡ።'),
  ('e4db3867-9c96-5da4-a304-5c5377edb9f2', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 3, 10, 'ዳዊትም፥ “ወደ ፍልስጥኤማውያን ልውጣን? በእጄስ አሳልፈህ ትሰጣቸዋለህን?” ብሎ እግዚአብሔርን ጠየቀ። እግዚአብሔርም፥ “በእጅህ አሳልፌ እሰጣቸዋለሁና ውጣ” አለው።'),
  ('d5bf44ca-1076-50cf-a8f5-d751c4d131d4', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 4, 11, 'ዳዊትም ወደ በኣልፐራሲን ወጣ፤ በዚያም ዳዊት ፍልስጥኤማውያንን መታቸው። ዳዊትም፥ “ውኃ እንዲያጠፋ እግዚአብሔር ጠላቶቼን በእጄ አጠፋቸው” አለ። ስለዚህም የዚያን ስፍራ ስም በኣልፐራሲን ብለው ጠሩት።'),
  ('7fe78f5f-f644-5997-a038-8b71c317099a', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 5, 12, 'አማልክቶቻቸውንም በዚያ ተዉ፤ ዳዊትም፥ “በእሳት አቃጥሉአቸው” ብሎ አዘዘ።'),
  ('15fb9783-c41e-56cb-aac0-6f893ee5517c', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 6, 13, 'ፍልስጥኤማውያንም ደግሞ በኀያላን ሸለቆ ተሰበሰቡ።'),
  ('8f6cfc41-2ee5-5c9f-a291-e603fa2f4d17', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 7, 14, 'ዳዊትም እንደ ገና እግዚአብሔርን ጠየቀ፤ እግዚአብሔርም፥ “አትውጣ፥ በኋላቸውም አትከተላቸው፤ ነገር ግን ከኋላቸው ዙረህ ቅረባቸው።'),
  ('3d3d0284-6c81-54ce-af95-16df86abebe0', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 8, 15, 'በሾላውም ዛፍ ራስ ውስጥ የሽውሽውታ ድምፅ ስትሰማ የፍልስጥኤማውያንን ጭፍራ ሊመታ እግዚአብሔር በፊትህ ይወጣልና በዚያን ጊዜ ወደ ሰልፍ ውጣ” አለው።'),
  ('6b2e8dca-9357-5600-ac29-04f1794e1883', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 9, 16, 'ዳዊትም አምላኩ እግዚአብሔር እንዳዘዘው አደረገ፤ ከገባዖንም ጀምሮ እስከ ጌዝር ድረስ የፍልስጥኤማውያንን ጭፍራ መታ።'),
  ('65925dee-8446-58bd-ac46-83c95d9f0d8b', 'fdb3d28f-69c7-5a06-a5fc-3b676f89d2cf', '73498ec7-2076-5e42-a3cb-0a52864acc82', 10, 17, 'የዳዊትም ዝና በየሀገሩ ሁሉ ወጣ፤ መፈራቱንም እግዚአብሔር በአሕዛብ ሁሉ ዘንድ አደረገ።'),
  ('5e1eb251-0c42-5983-ab8b-c0f8e2b4d0ea', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 1, 1, 'ዳዊትም በከተማው ለራሱ ቤቶችን ሠራ፤ ለእግዚአብሔርም ታቦት ስፍራ አዘጋጀ፤ ድንኳንም ተከለላት።'),
  ('8fcf6015-f9b2-5dd5-ab26-5942e2fb0e06', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 2, 2, 'በዚያን ጊዜም ዳዊት፥ “የእግዚአብሔርን ታቦት ይሸከሙ ዘንድ፥ ለዘለዓለሙም ያገለግሉት ዘንድ እግዚአብሔር ከመረጣቸው ከሌዋውያን በቀር ማንም የእግዚአብሔርን ታቦት ይሸከም ዘንድ አይገባውም” አለ።'),
  ('f6573a87-8b54-52d1-ab9c-e6daae44a6b1', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 3, 3, 'ዳዊትም ወዳዘጋጀላት ስፍራ የእግዚአብሔርን ታቦት ያመጣ ዘንድ እስራኤልን ሁሉ ወደ ኢየሩሳሌም ሰበሰበ።'),
  ('79f460d2-8a78-53d0-a496-11dff7466bf4', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 4, 4, 'ዳዊትም የአሮንን ልጆችና ሌዋውያንን ሰበሰበ።'),
  ('a25373f3-6358-5c54-a1cc-ee4712b99b23', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 5, 5, 'ከቀዓት ልጆች፤ አለቃው ኡርኤል፥ ወንድሞቹም መቶ ሃያ፤'),
  ('1bc63bd4-15a3-553c-a131-99856b692e67', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 6, 6, 'ከሜራሪ ልጆችም፤ አለቃው ዓሣያ፥ ወንድሞቹም ሁለት መቶ ኀምሳ፤'),
  ('cd6f1fce-89ad-5414-a9a2-b8b2e45f27bf', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 7, 7, 'ከጌድሶን ልጆች፤ አለቃው ኢዮሔት፥ ወንድሞቹም መቶ ሠላሳ፤'),
  ('83b4d8cf-996d-5f96-ae49-da54db9c6b5f', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 8, 8, 'ከኤልሳፋን ልጆች፤ አለቃው ሰማያ፥ ወንድሞቹም ሁለት መቶ፤'),
  ('50ec4cbf-f70d-510b-ad22-d54c799c416e', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 9, 9, 'ከኬብሮን ልጆች፤ አለቃው ኢዮሔል፥ ወንድሞቹም ሰማንያ፤'),
  ('03cec8dc-1bc0-54dd-a3c5-9b094b4f9079', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 10, 10, 'ከዑዝኤል ልጆች፤ አለቃው አሚናዳብ፥ ወንድሞቹም መቶ ዐሥራ ሁለት።'),
  ('d3ebc304-753d-5b12-abdf-aaba9d01244e', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 11, 11, 'ዳዊትም ካህናቱን ሳዶቅንና አብያታርን፥ ሌዋውያንንም፥ ኡርኤልን፥ ዓሣያን፥ ኢዮኤልን፥ ሰማያን፥ ኤሊኤልን፥ አሚናዳብንም ጠርቶ፦'),
  ('8787d094-70fa-5891-a45b-2976b037e436', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 12, 12, '“እናንተ የሌዋውያን አባቶች ቤቶች አለቆች ናችሁ፤ ወዳዘጋጀሁላት ስፍራ የእስራኤልን አምላክ የእግዚአብሔርን ታቦት ታመጡ ዘንድ እናንተና ወንድሞቻችሁ ተቀደሱ።'),
  ('e8014116-4cf0-5f28-aba3-8c23910a371a', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 13, 13, 'በቀድሞ ሥራችን አምላካችን እግዚአብሔር እርስ በርሳችን አላጠፋንም፤ በጦር አልፈለገንምና” አላቸው።'),
  ('3aa90d80-4689-5467-adbf-28f7ae86f792', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 14, 14, 'የእስራኤልንም አምላክ የእግዚአብሔርን ታቦት ያመጡ ዘንድ ካህናቱና ሌዋውያኑ ራሳቸውን አነጹ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2a60cf0c-40ea-5d36-acfd-7c16b58ffe7c', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 15, 15, 'በመጽሐፍም እንደ ተጻፈ ሙሴ በእግዚአብሔር ቃል እንደ አዘዛቸው የሌዋውያን ልጆች የእግዚአብሔርን ታቦት በትከሻቸው ላይ በመሎጊያዎቹ ተሸከሙ። መባእና ቍርባንም ከእነርሱ ጋር ነበረ።'),
  ('1fe28097-b755-5050-a8af-fe11e3576947', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 16, 16, 'ዳዊትም በዜማ ዕቃ፥ በመሰንቆና በበገና፥ በጸናጽልም እንዲያዜሙ፥ ድምፃቸውንም በደስታ ከፍ እንዲያደርጉ መዘምራኑን “ወንድሞቻችሁን ሹሙ” ብሎ ለሌዋውያን አለቆች ተናገረ።'),
  ('7985077f-60bc-5ccb-abda-ba48d9412e10', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 17, 17, 'ሌዋውያኑም የኢዩኤልን ልጅ ኤማንን፥ ከወንድሞቹም የበራክያን ልጅ አሳፍን፥ ከወንድሞቻቸውም ከሜራሪ ልጆች የቂሳንን ልጅ ኢታንን፥'),
  ('1fdf8861-158a-5652-a83e-bf8e80ed3f14', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 18, 18, 'ከእነርሱም ጋር በሁለተኛው ተራ የሆኑትን ወንድሞቻቸውን ዘካርያስን፥ ቤንን፥ አዝኤልን፥ ስሜራሞትን፥ ኢያሄልን፥ ኡኒን፥ ኤልያብን፥ በናእያን፥ መዕሤያን፥ መታትያን፥ ኤልፋይን፥ ሜቄድያን፥ በረኞችንም አብዲዶምን፥ ኢያኤልንና ዖዝያስን አቆሙ።'),
  ('8a842504-e25c-5ef1-af18-e45ecd82ea8b', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 19, 19, 'መዘምራንም ኤማንና አሳፍ ኤታንም በናስ ጸናጽል ከፍ አድርገው ያሰሙ ነበር።'),
  ('fe0203fe-59ef-5d45-a50e-9d651e1ba85b', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 20, 20, 'ዘካርያስ፥ አዝኤል፥ ሰሚራሞት፥ ኢያሔል፥ ዑኒ፥ ኤልያብ፥ መዕሤያ፥ በናያስ በመሰንቆ በልዑል ቃል ያዜሙ ነበር።'),
  ('0637c84d-21ca-5578-a869-53d6e205c34d', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 21, 21, 'ማታትያስ፥ ኤልፋላይ፥ ሜቄድያስ፥ አብዴዶም፥ ይዒኤል፥ ዖዝያስም ስምንት አውታር ባለው በገና ይዘምሩ ነበር።'),
  ('5041e0ea-3d7a-5d04-a27a-b1c324107bbf', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 22, 22, 'የሌዋውያኑም አለቃ ኮነንያስ በዜማ ላይ ተሾሞ ነበር። ብልሃተኛ ነበረና።'),
  ('57e0c902-c98c-5f1e-abee-4be54fe967b6', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 23, 23, 'በራክያና ሕልቃናም ለታቦቷ በረኞች ነበሩ።'),
  ('0a12a1df-13c0-53cc-a0b2-26598f8db8c7', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 24, 24, 'ካህናቱም ሰበንያ፥ ኢዮሣፍጥ፥ ናትናኤል፥ ዓማሣይ፥ ዘካርያስ፥ በናያስ፥ አልዓዛርም በእግዚአብሔር ታቦት ፊት መለከት ይነፉ ነበር። አብዲዶምና ኢያኤያም የእግዚአብሔር ታቦት በረኞች ነበሩ።'),
  ('86479238-5bb4-5410-a86d-9628cd025d78', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 25, 25, 'ዳዊትም፥ የእስራኤልም ሽማግሌዎች፥ የሻለቆችም የእግዚአብሔርን የቃል ኪዳኑን ታቦት ከአቢዳራ ቤት በደስታ ያመጡ ዘንድ ሄዱ።'),
  ('7c861753-3a4e-5c93-a46d-4c69f6de4687', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 26, 26, 'የእግዚአብሔርንም ቃል ኪዳን ታቦት የተሸከሙትን ሌዋውያንን እግዚአብሔር በአበረታቸው ጊዜ ሰባት በሬዎችንና ሰባት አውራ በጎችን ሠዉ።'),
  ('fdd35749-427c-565e-afb0-f0399398a1bf', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 27, 27, 'ዳዊትም፥ የእግዚአብሔርን የቃል ኪዳኑን ታቦት የተሸከሙ ሌዋውያንም ሁሉ፥ መዘምራኑም፥ የመዘምራኑም አለቃ ኮኖንያስ የጥሩ በፍታ ቀሚስ ለብሰው ነበር፤ ዳዊትም የከበረ ልብስ ለብሶ ነበረ።'),
  ('6d3b3b56-61c9-589f-a96c-15a63ff1d334', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 28, 28, 'እንዲሁ እስራኤል ሁሉ በይባቤ፥ ቀንደ መለከትና እንቢልታ እየነፉ፥ ጸናጽልና መሰንቆም፥ በገናም እየመቱ፥ የእግዚአብሔርን የቃል ኪዳን ታቦት አመጡ።'),
  ('4a25703e-403e-5c63-a5f6-01d3d88249ab', '4e918093-c0f3-59bd-a1a3-811d02ce64bd', '109826b9-0ce7-5261-a8b1-3c3b1ee0e5c6', 29, 29, 'የእግዚአብሔርም ቃል ኪዳን ታቦት ወደ ዳዊት ከተማ በደረሰች ጊዜ የሳኦል ልጅ ሜልኮል በመስኮት ሆና ተመለከተች፤ ንጉሡም ዳዊት ሲዘፍንና ሲጫወት አይታ በልብዋ ናቀችው።'),
  ('d9995e26-2339-5070-a238-6e87323b026f', 'e8f5910e-e16e-5816-adaa-7c0332159415', '4ca07c61-1df2-5a81-a624-073d1cfaf5c0', 1, 1, 'የእግዚአብሔርንም ታቦት ይዘው ገቡ፤ ዳዊትም በተከለላት ድንኳን ውስጥ አኖሩአት፤ የሚቃጠለውን መሥዋዕትና የደኅንነቱን መሥዋዕትም በእግዚአብሔር ፊት አቀረቡ።'),
  ('d449bc33-4a5f-5588-afe2-9259b2624958', 'e8f5910e-e16e-5816-adaa-7c0332159415', '4ca07c61-1df2-5a81-a624-073d1cfaf5c0', 2, 2, 'ዳዊትም የሚቃጠለውን መሥዋዕትና የደኅንነቱን መሥዋዕት ማቅረብ በፈጸመ ጊዜ በእግዚአብሔር ስም ሕዝቡን ባረከ።'),
  ('e172d28a-6686-5784-a692-6e6ee43523b7', 'e8f5910e-e16e-5816-adaa-7c0332159415', '4ca07c61-1df2-5a81-a624-073d1cfaf5c0', 3, 3, 'ለእስራኤልም ለወንዱም ለሴቱም ለእያንዳንዱ አንዳንድ እንጀራ፥ አንዳንድም ቍራጭ ሥጋ፥ አንዳንድም የዘቢብ ጥፍጥፍ አካፈለ።'),
