  ('51a13d94-7aac-52ad-a8df-c8ffe1f7d5c6', 'e8f5910e-e16e-5816-adaa-7c0332159415', '91b63b53-3594-542d-abc8-5fb78c99165f', 1, 37, 'እንዲሁም በየቀኑ እንደሚገባቸው በታቦቱ ፊት ዘወትር ያገለግሉ ዘንድ አሳፍንና ወንድሞቹን ተዋቸው።'),
  ('29d9bf61-e98e-5daf-afee-b2005cc6fdf3', 'e8f5910e-e16e-5816-adaa-7c0332159415', '91b63b53-3594-542d-abc8-5fb78c99165f', 2, 38, 'አብዲዶምንም፥ ስድሳ ስምንቱንም ወንድሞቻቸውን፤ የኤዶታምም ልጅ አብዲዶምና ሖሳ በረኞች ይሆኑ ዘንድ ተዋቸው፤'),
  ('87fad678-4312-58d8-ae1d-e5a1cb0e1387', 'e8f5910e-e16e-5816-adaa-7c0332159415', '91b63b53-3594-542d-abc8-5fb78c99165f', 3, 39, 'ካህኑን ሳዶቅንና ካህናቱን ወንድሞቹን በገባዖን በኮረብታው መስገጃ ባለው በእግዚአብሔር ማደሪያ ፊት አቆማቸው፥'),
  ('7e9b9495-b1b7-5add-a8a9-df1342e6e6d0', 'e8f5910e-e16e-5816-adaa-7c0332159415', '91b63b53-3594-542d-abc8-5fb78c99165f', 4, 40, 'ለእስራኤልም ልጆች ይነግራቸው ዘንድ አገልጋዩ ሙሴን እንደ አዘዘው በእግዚአብሔር ሕግ እንደ ተጻፈ ሁሉ ለሚቃጠለው መሥዋዕት በሚሆነው መሠዊያ ላይ የሚቃጠለውን መሥዋዕት ሁልጊዜ ጥዋትና ማታ ለእግዚአብሔር ያቀርቡ ዘንድ።'),
  ('d6c8dbae-af5f-5759-a7ff-1b592376d936', 'e8f5910e-e16e-5816-adaa-7c0332159415', '91b63b53-3594-542d-abc8-5fb78c99165f', 5, 41, 'ምሕረቱም ለዘለዓለም ነውና እግዚአብሔርን ያመሰግኑ ዘንድ ኤማንንና ኤዶታምን፥ በስማቸው የተጻፉትን ተመርጠው የቀሩትን ከእነርሱ ጋር አቆመ።'),
  ('efcf4b85-ca5d-54f6-afef-46c933da66fb', 'e8f5910e-e16e-5816-adaa-7c0332159415', '91b63b53-3594-542d-abc8-5fb78c99165f', 6, 42, 'ከእነርሱም ጋር ካህናቱ ከፍ አድርገው ለማሰማት መለከትና ጸናጽል ለእግዚአብሔርም መዝሙራት የዜማ ዕቃ ይዘው ነበር፤ የኤዶታም ልጆች ግን በረኞች ነበሩ።'),
  ('99142c01-64ab-542f-aae6-8013659bf3a0', 'e8f5910e-e16e-5816-adaa-7c0332159415', '91b63b53-3594-542d-abc8-5fb78c99165f', 7, 43, 'ሕዝቡ ሁሉ እያንዳንዱ ወደ ቤቱ ሄደ፤ ዳዊትም ቤቱን ይባርክ ዘንድ ተመለሰ።'),
  ('1c153ad7-2d68-5283-aea9-6cfff476af39', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 1, 1, 'እንዲህም ሆነ፤ ዳዊት በቤቱ በተቀመጠ ጊዜ ዳዊት ነቢዩ ናታንን፥ “እነሆ፥ ከዝግባ በተሠራ ቤት ተቀምጫለሁ፤ የእግዚአብሔር ቃል ኪዳን ታቦት ግን በመጋረጃዎች ውስጥ ተቀምጣለች” አለው።'),
  ('8b021154-d9b7-50c6-aea8-1f7e05634db9', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 2, 2, 'ናታንም ዳዊትን፥ “እግዚአብሔር ከአንተ ጋር ነውና በልብህ ያለውን ሁሉ አድርግ” አለው።'),
  ('4f295496-21b2-5e90-acea-dee985872747', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 3, 3, 'በዚያም ሌሊት የእግዚአብሔር ቃል ወደ ናታን መጣ፤ እንዲህም አለው፦'),
  ('93b2441e-af6a-5055-a1f0-a6ca3d73a3bb', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 4, 4, '“ሂድ፥ ለአገልጋዬ ለዳዊት ንገረው፦ እግዚአብሔር እንዲህ ይላል፦ በውስጡ እኖርበት ዘንድ ቤትን የምትሠራልኝ አንተ አይደለህም፤'),
  ('27b3bc15-a1cf-54a6-a393-92bfb55b2986', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 5, 5, 'ሕዝቤን እስራኤልን ከግብፅ ምድር ካወጣሁበት ቀን ጀምሮ እስከ ዛሬ ድረስ በድንኳንና በማደሪያ ኖርሁ እንጂ በቤት ውስጥ አልኖርሁም።'),
  ('e1c28900-450e-5eb9-a53d-47451db1841a', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 6, 6, 'ከእስራኤል ሁሉ ጋር ባለፍሁበት ስፍራ ሁሉ፥ ስለ ምን ቤትን ከዝግባ እንጨት አልሠራችሁልኝም? ብዬ ሕዝቤን ይጠብቅ ዘንድ ከእስራኤል ፈራጆች ላዘዝሁት ለአንዱ በውኑ ተናግሬአለሁን?'),
  ('a6e0566e-8bd6-5d92-afec-774ce5636867', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 7, 7, 'አሁንም አገልጋዬን ዳዊትን እንዲህ በለው፦ ሁሉን ቻይ እግዚአብሔር እንዲህ ይላል፦ አንተ መንጋውን ስትከተል በሕዝቤ በእስራኤል ላይ አለቃ ትሆን ዘንድ ከበግ ጥበቃ መርጬ ወሰድሁህ።'),
  ('4da16eb4-e82d-521d-a05f-5ee81acbb952', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 8, 8, 'በሄድህበትም ሁሉ ከአንተ ጋር ነበርሁ፥ ጠላቶችህንም ሁሉ ከፊትህ አጠፋሁ፤ በምድርም ላይ እንዳሉ እንደ ታላላቆች ስም ለአንተ ስምን አደረግሁ።'),
  ('11af1436-f24b-5c62-a954-6b95cb0b5873', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 9, 9, 'ለሕዝቤም ለእስራኤል ስፍራ አደርግለታለሁ፥ በዚያም እተክለዋለሁ፥ በስፍራውም ይቀመጣል፤ ከዚያም በኋላ አይናወጥም፤ የኀጢአትም ልጆች እንደ ቀድሞው አያስጨንቁትም፤'),
  ('73e5759d-3dff-5c9b-aec0-6b63ee788c29', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 10, 10, 'በሕዝቤም በእስራኤል ላይ ፈራጆችን ካስነሣሁበት ጊዜ ጀምሮ ጠላቶችህን ሁሉ አዋርዳቸዋለሁ፤ አንተንም ከፍ ከፍ አደርግሃለሁ። እግዚአብሔር ደግሞ ቤትን ይሠራልሃል።'),
  ('664adc44-da91-5f87-a29d-8cd956c92951', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 11, 11, 'ወደ አባቶችህም ትሄድ ዘንድ ዕድሜህ በተፈጸመ ጊዜ ከአብራክህ የተወለደ ዘርህን ከአንተ በኋላ አስነሣለሁ ፤ መንግሥቱንም አጸናለሁ።'),
  ('e535417a-c80e-5849-a561-fa32f40ced7b', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 12, 12, 'እርሱ ቤትን ይሠራልኛል ፤ ዙፋኑንም ለዘለዓለም አጸናለሁ።'),
  ('d74cca94-473e-5816-a8f6-c2f8f57bb831', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 13, 13, 'እኔም አባት እሆነዋለሁ፤ እርሱም ልጄ ይሆነኛል፤ ከአንተ አስቀድሞ ከነበሩት እንዳራቅሁ፥ ምሕረቴን ከእርሱ አላርቅም።'),
  ('123ae848-6f70-5133-a8ee-1c562a0af039', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 14, 14, 'ለቤቴም ታማኝ አደርገዋለሁ መንግሥቱም ለዘለዓለም ነው፤ ዙፋኑም ለዘለዓለም ይጸናል።”'),
  ('598d3a5c-912c-5ae7-a2bf-d5ce90a91f68', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '5330e80b-ebc8-5a84-aa31-dca09e951cd7', 15, 15, 'እንደዚህ ነገር ሁሉ እንደዚህም ራእይ ሁሉ ነቢዩ ናታን ለዳዊት ነገረው።'),
  ('38fe9797-06fa-5049-a143-67df452c47b9', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 1, 16, 'ንጉሡም ዳዊት ገባ፤ በእግዚአብሔርም ፊት ተቀምጦ እንዲህ አለ፥ “አቤቱ አምላክ ሆይ፥ ለዘለዓም የወደድኸኝ እኔ ማን ነኝ? ቤቴስ ምንድን ነው?'),
  ('cb6cf19e-0f87-5d68-afc9-9d7953e9f197', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 2, 17, 'አምላክ ሆይ፥ ይህ በፊትህ ጥቂት ነበረ፤ ስለ አገልጋይህ ቤት ደግሞ ለሩቅ ዘመን ተናገርህ፤ እንደ አንድ ባለ ማዕረግ ሰው ተመለከትኸኝ። አቤቱ፥ አምላክ ሆይ፥ ከፍ ከፍ አደረግኸኝ።'),
  ('dd874f68-e3db-54ad-aadc-34a7a1130691', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 3, 18, 'አንተ ባሪያህን ታውቀዋለህና ለባሪያህ ስለ ተደረገው ክብር ዳዊት ጨምሮ የሚለው ምንድን ነው?'),
  ('e97d0bad-c21b-52a3-a77d-7523deb83aeb', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 4, 19, 'እንደ ልብህም ይህን ታላቅ ነገር ሁሉ ለእኔ አደረግህ።'),
  ('92a95fd7-a43d-5dba-a1ff-4b9af6ae6ec2', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 5, 20, 'አቤቱ፥ እንዳንተ ያለ የለም፤ በጆሮአችንም እንደ ሰማን ሁሉ ከአንተ በቀር አምላክ የለም።'),
  ('6abdcbf1-bd37-5975-add0-3ed8aa117c0e', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 6, 21, 'አንተ እግዚአብሔር ከግብፅ ካወጣኸው ከሕዝብህ ፊት አሕዛብን በማሳደድ ታላቅና የከበረ ስምን ለአንተ ታደርግ ዘንድ፥ ለአንተም ሕዝብ ትቤዥ ዘንድ እንደ መራኸው እንደ አንተ ሕዝብ እንደ እስራኤል ያለ በምድር ላይ ሌላ ሕዝብ የለም።'),
  ('d2e4647a-2b7f-58e7-a2c3-b03bcfc73d2e', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 7, 22, 'ሕዝብህንም እስራኤልን ለዘለዓለም ሕዝብህ አደረግኸው፤ አንተም አቤቱ፥ አምላክ ሆንሃቸው።'),
  ('0a90d12d-3c6f-5ed4-a3cc-736242dfbcff', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 8, 23, 'አሁንም፥ አቤቱ፥ ስለ ባሪያህና ስለ ቤቱ የተናገርኸው ቃል ለዘለዓለም የታመነ ይሁን፤ እንደ ተናገርህም አድርግ።'),
  ('166296d9-d581-5485-ab55-8cf694ba92d9', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 9, 24, 'ሁሉን የሚገዛ እግዚአብሔር እርሱ የእስራኤል አምላክ ነው፤ በእውነት የእስራኤል አምላክ ነው ይባል ዘንድ ስምህ ለዘለዓለም ጽኑና ታላቅ ይሁን፤ የአገልጋይህም የዳዊት ቤት በፊትህ የጸና ይሁን።'),
  ('b5123bdf-0d80-5fc4-ae27-a5cd48fd3091', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 10, 25, 'አምላኬ ሆይ፥ ቤት እንድትሠራለት ለባሪያህ በጆሮው ገልጠሃልና ስለዚህ አገልጋይህ ወደ አንተ ይጸልይ ዘንድ ባለሟልነትን አገኘ።'),
  ('90d67d98-e3e5-525b-a910-f2d0f0f54199', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 11, 26, 'አሁንም፥ አቤቱ፥ አንተ አምላክ ነህ፤ ይህንም መልካም ነገር ለባሪያህ ተናግረሃል።'),
  ('4baa77b2-8bb9-5e42-ab34-d2b5ef5110e5', 'da9c6a0f-9c9f-5b77-abde-552736b34cee', '0c29551f-effb-531e-a922-a292f934634f', 12, 27, 'አሁንም በፊትህ ለዘለዓለም ይኖር ዘንድ የአገልጋይህን ቤት ትባርክ ዘንድ ጀምረሃል፤ አንተም አቤቱ፥ ባርከኸዋል፤ ለዘለዓለምም ቡሩክ ይሆናል።”'),
  ('39329ab5-8053-5d59-a398-28cdb4c0038f', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 1, 1, 'ከዚህም በኋላ ዳዊት ፍልስጥኤማውያንን መታ፤ አዋረዳቸውም፤ ከፍልስጥኤማውያንም እጅ ጌትንና መንደሮችዋን ወሰደ።'),
  ('752cd881-65fd-54d6-a81b-4e92fabfb36b', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 2, 2, 'ሞዓብንም መታ፤ ሞዓባውያንም ለዳዊት ገባሮች ሆኑ፤ ግብርም አመጡለት።'),
  ('cbe5d6c5-0d85-5ecb-a09a-d743c0afb48c', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 3, 3, 'ዳዊትም በኤፍራጥስ ወንዝ አጠገብ የነበረውን ግዛቱን ለማጽናት በሄደ ጊዜ ሔማታዊውን የሱባን ንጉሥ አድርአዛርን መታ።'),
  ('25572be0-9112-5d77-af6c-2b242ddfc50f', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 4, 4, 'ዳዊትም ከእርሱ አንድ ሺህ ሰረገሎች፥ ሰባት ሺህም ፈረሰኞች፥ ሃያ ሺህም እግረኞች ወሰደ፤ ዳዊትም ለመቶ ሰረገሎች የሚሆኑትን ብቻ አስቀርቶ የሰረገሎቹን ፈረሶች ቋንጃ ቈረጠ።'),
  ('df3acd01-949c-5588-a65c-659bb351c3b9', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 5, 5, 'ከደማስቆም ሶርያውያን የሱባን ንጉሥ አድርአዛርን ሊረዱ በመጡ ጊዜ ዳዊት ከሶርያውያን ሃያ ሁለት ሺህ ሰዎችን ገደለ።'),
  ('dad09632-eb25-53f6-a7ff-dd1a23709d0a', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 6, 6, 'ዳዊትም በደማስቆ ሶርያ ጭፍሮችን አኖረ፤ ሶርያውያንም ለዳዊት ገባሮች ሆኑ፤ ግብርም አመጡለት። እግዚአብሔርም ዳዊትን በሄደበት ሁሉ ያድነው ነበር።'),
  ('fd86d3be-47be-5964-a9bb-33937651c906', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 7, 7, 'ዳዊትም ለአድርአዛር አገልጋዮች የነበሩትን የወርቅ ማርዳዎች ወሰደ፤ ወደ ኢየሩሳሌምም ይዞአቸው መጣ።'),
  ('d2ab9eb1-bb14-5b5c-a57d-b579376075a0', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 8, 8, 'ከሚጢብሐትና ከተመረጡት ከአድርአዛር ከተሞች ዳዊት እጅግ ብዙ ናስ ወሰደ፤ ከዚህም ሰሎሞን የናሱን ኩሬና ዓምዶች የናሱንም ዕቃ ሠራ።'),
  ('3a6c745f-05d8-53ad-ae06-c4f65d17731c', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 9, 9, 'የኤማትም ንጉሥ ቶዑ ዳዊት የሱባን ንጉሥ አድርአዛርን፥ ጭፍራውንም ሁሉ እንደ መታ ሰማ።'),
  ('25c99303-87e2-5659-a5dc-6bdea2d222da', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 10, 10, 'ቶዑም ከአድርአዛር ጋር ሁልጊዜ ይዋጋ ነበርና ዳዊት አድርአዛርን ወግቶ ስለ መታው ደኅንነቱን ይጠይቀውና ይመርቀው ዘንድ ልጁን አዶራምን ወደ ዳዊት ላከው፤ ከእርሱም ጋር የወርቅና የብር፥ የናስም ዕቃ ነበረ።'),
  ('cc965a39-52e4-51ff-acd7-1b43dd127395', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 11, 11, 'ንጉሡም ዳዊት ከአሕዛብ ሁሉ ከኤዶምና ከሞዓብ፥ ከአሞንም ልጆች፥ ከፍልስጥኤማውያንም፥ ከአማሌቅም ከማረከው ብርና ወርቅ ጋር እነዚህን ደግሞ ለእግዚአብሔር ቀደሰ።'),
  ('d9b2b1c0-ef49-5178-a03d-f17dc63492ba', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 12, 12, 'ደግሞ የሶርህያ ልጅ አቢሳ ከኤዶማውያን በጨው ሸለቆ ውስጥ ዐሥራ ስምንት ሺህ ሰዎች ገደለ።'),
  ('6588238b-458a-520b-ae93-a99cce71c877', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 13, 13, 'በዚያም ሸለቆ ምሽግ ሠርቶ ጭፍሮችን አኖረ፥ ኤዶማውያንም ሁሉ ለዳዊት ገባሮች ሆኑ። እግዚአብሔርም ዳዊትን በሄደበት ሁሉ ያድነው ነበር።'),
  ('87f64ed3-d08b-5b12-a747-2d6f9c2a8b7d', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 14, 14, 'ዳዊትም በእስራኤል ሁሉ ላይ ነገሠ፤ ለሕዝቡም ሁሉ ፍርድንና ጽድቅን አደረገላቸው።'),
  ('5173ae77-244a-5a57-a36f-e9c96c57fc5d', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 15, 15, 'የሶርህያ ልጅ ኢዮአብም የሠራዊት አለቃ ነበረ፤ የአሔሉድም ልጅ ኢዮሣፍጥ ታሪክ ጸሓፊ ነበረ።'),
  ('70e35f29-1033-5ef5-a9eb-097d34b7c7ef', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 16, 16, 'የአኪጦብም ልጅ ሳዶቅና የአብያታር ልጅ አቤሜሌክ ካህናት ነበሩ፤ ሱሳ ጸሓፊ ነበረ።'),
  ('1b74ab36-e7b5-5624-a99c-e840647cb0d4', '99f09366-d65e-52fd-ac41-225d8b3b786d', 'f16a0e03-3d30-5228-a08e-15c103b788fa', 17, 17, 'የዮዳሄ ልጅ በናያስ በከሊታውያንና በፈሊታውያን ላይ ሹም ነበረ፤ የዳዊትም ልጆች በንጉሡ አጠገብ አለቆች ነበሩ።'),
  ('8852365a-6aff-504a-ae5a-2cb43d3ecf64', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 1, 1, 'ከዚህም በኋላ እንዲህ ሆነ፤ የአሞን ልጆች ንጉሥ ናዖስ ሞተ፤ ልጁም በእርሱ ፋንታ ነገሠ።'),
  ('3f151c36-e825-5231-a86e-cc98dd97102e', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 2, 2, 'ዳዊትም፥ “አባቱ ስላደረገልኝ ወረታ እኔ ለናዖስ ልጅ ለሐናን ቸርነት አደርጋለሁ” አለ። ዳዊትም አባቱ ስለ ሞተ ሊያጽናናው መልእክተኞችን ላከ፤ የዳዊትም አገልጋዮች ሊያጽናኑት ወደ ሐናን ወደ አሞን ልጆች ምድር መጡ።'),
  ('cb53bbc8-919c-5d44-a61d-0952ed1c4a29', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 3, 3, 'የአሞን ልጆች አለቆች ግን ሐናንን፥ “ዳዊት የሚያጽናኑህን ወደ አንተ የላከ አባትህን በማክበር ነውን? አገልጋዮቹስ ከተማዪቱን ለመመርመርና ሀገሪቱንም ለመሰለል ወደ አንተ የመጡ አይደሉምን?” አሉት።'),
  ('5b4aeaac-53fa-5457-a0cb-8ced15bf7437', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 4, 4, 'ሐናንም የዳዊትን አገልጋዮች ወስዶ የጢማቸውን ግማሽ አስላጫቸው፤ ልብሳቸውንም እስከ ወገባቸው ድረስ ለሁለት ቀድዶ ሰደዳቸው።'),
  ('25a63f03-bcb6-5167-aafe-cac856533e10', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 5, 5, 'ሰዎችም ሄደው በሰዎቹ ላይ የተደረገውን ለዳዊት አስታወቁት። ሰዎቹም በብዙ አፍረዋልና ይቀበሏቸው ዘንድ ሰዎችን ላኩ፤ ንጉሡም፥ “ጢማችሁ እስኪያድግ ድረስ በኢያሪኮ ተቀመጡ፥ ከዚያም በኋላ ተመለሱ” አለ።'),
  ('c9c7243d-a4a2-59f3-a6e5-b271098acb87', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 6, 6, 'የአሞንም ልጆች የዳዊት ሰዎች እንዳፈሩ ባዩ ጊዜ ሐናን የአሞን ልጆች ንጉሥ ከሶርያ መስጴጦምያ፥ ከሶርያ ሞዓካ፥ ከሱባም ሰረገሎችንና ፈረሰኞችን ይቀጥሩ ዘንድ አንድ ሺህ መክሊት ብር ላከ።'),
  ('08d7efac-641b-57cc-ae58-2fa6faaa2d61', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 7, 7, 'ሠላሳ ሁለትም ሺህ ሰረገሎችን የሞዓካን ንጉሥና ሕዝቡንም ቀጠሩ፤ መጥተውም በሜድባ ፊት ለፊት ሰፈሩ። የአሞንም ልጆች ከየከተሞቻቸው ተሰብስበው ወደ ሰልፍ መጡ።'),
  ('339ba3ca-9643-5da1-a8ca-766503555603', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 8, 8, 'ዳዊትም ይህን በሰማ ጊዜ ኢዮአብንና የኀያላኑን ሠራዊት ሁሉ ላከ።'),
  ('801d0540-4ce6-5bca-a4ce-93f9835cc77d', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 9, 9, 'የአሞንም ልጆች ወጥተው በከተማዪቱ በር አጠገብ ተሰለፉ፤ የመጡትም ነገሥታት ለብቻቸው በሜዳው ላይ ሰፈሩ።'),
  ('bb390bd4-b662-5a38-a843-8557dc5d1ce1', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 10, 10, 'ኢዮአብም በፊቱና በኋላው ሰልፍ እንደ ከበበው ባየ ጊዜ ከእስራኤል ጐልማሶችን መረጠ፤ እነርሱም ከሶርያውያን ጋር ተዋጉ።'),
  ('b49de3ef-4bff-5e66-ab34-dd18c09ddb2f', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 11, 11, 'የቀረውንም ሕዝብ ለወንድሙ ለአቢሳ ሰጠው፤ እነርሱም በአሞን ልጆች ላይ ተሰለፉ።'),
  ('bff5502a-4ea1-5d24-a738-51a441002776', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 12, 12, 'ኢዮአብም፥ “ሶርያውያን ቢበረቱብኝ ርዳኝ፤ የአሞንም ልጆች ቢበረቱብህ እረዳሃለሁ።'),
  ('03f17441-fb29-5700-ad1f-486cf81576e6', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 13, 13, 'አይዞህ፥ በርታ፤ ስለ ሕዝባችንና ስለ አምላካችንም ከተሞች እንበርታ፤ እግዚአብሔርም በፊቱ ደስ ያሰኘውን ያድርግ” አለ።'),
  ('e5f5a5de-9089-5722-a150-f1f81a1d4acd', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 14, 14, 'ኢዮአብና ከእርሱም ጋር የነበረው ሕዝብ ከሶርያውያን ጋር ተዋጉ፤ እነርሱም ከፊታቸው ሸሹ።'),
  ('c67b4030-b317-561f-af90-7dd85edb754b', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 15, 15, 'የአሞንም ልጆች ሶርያውያን ከኢዮአብ ፊት እንደ ሸሹ ባዩ ጊዜ እነርሱ ደግሞ ከወንድሙ ከአቢሳ ፊት ሸሹ፤ ወደ ከተማዪቱም ገቡ። ኢዮአብም ወደ ኢየሩሳሌም መጣ።'),
  ('e0258843-f77b-559e-a006-567f99822403', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 16, 16, 'ሶርያውያንም እስራኤል ድል እንዳደረጓቸው ባዩ ጊዜ መልእክተኞችን ልከው በወንዝ ማዶ የነበሩትን ሶርያውያን አስመጡ፤ የአድርአዛርም ሠራዊት አለቃ ሶፋክ በፊታቸው ነበረ።'),
  ('9786f0d9-2024-57d7-a882-74cbe22c58f9', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 17, 17, 'ዳዊትም በተነገረው ጊዜ እስራኤልን ሁሉ ሰበሰበ፤ ዮርዳኖስንም ተሻግሮ መጣባቸው፥ ከእነርሱም ጋር ተዋጋ፤ ዳዊትም ከሶርያውያን ጋር ተዋጋ፥ እነርሱም ከእርሱ ጋር ተዋጉ።'),
  ('5fa2da5b-6e5c-5403-a6da-10bf5682c36c', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 18, 18, 'ሶርያውያንም ከዳዊት ፊት ሸሹ፤ ዳዊትም ከሶርያውያን ሰባት ሺህ ሰረገለኞችን፥ አርባ ሺህም እግረኞችን ገደለ፥ የሠራዊቱንም አለቃ ሶፋክን ገደለ።'),
  ('6ee84ef2-d1d5-5f8e-ae16-a52cf3e6c037', '31f2105c-5b3d-5d8f-a1e1-e2a3e78ac4bb', 'b1ab25a0-de51-542c-a1cf-3bea196509c1', 19, 19, 'የአድርአዛርም አገልጋዮች በእስራኤል ፊት እንደ ተሸነፉ ባዩ ጊዜ ከዳዊት ጋር ታረቁ፤ ተገዙለትም፤ ሶርያውያንም ከዚያ ወዲያ የአሞንን ልጆች ይረዱ ዘንድ እንቢ አሉ።'),
  ('6d57d8b4-c86f-593b-a41f-f24bb3af2c7a', '1e5ba6f8-149c-5c4f-aa92-63d9ef3d8f9f', 'd7fad515-0013-55d9-a96f-695bf0c87c08', 1, 1, 'እንዲህም ሆነ፤ በዓመት መጨረሻ ነገሥታት ወደ ሰልፍ በሚወጡበት ጊዜ ኢዮአብ የሠራዊቱን ኀይል አወጣ፤ የአሞንንም ልጆች ሀገር አጠፋ፤ መጥቶም አራቦትን ከበበ። ዳዊትም በኢየሩሳሌም ተቀምጦ ነበር። ኢዮአብም አራቦትን መትቶ አፈረሳት።'),
  ('24475831-c6a1-57bd-a37e-a6f071a303ce', '1e5ba6f8-149c-5c4f-aa92-63d9ef3d8f9f', 'd7fad515-0013-55d9-a96f-695bf0c87c08', 2, 2, 'ዳዊትም የንጉሣቸውን የሞልኮልን ዘውድ ከራሱ ላይ ወሰደ፤ ክብደቱም አንድ መክሊት ወርቅ ያህል ሆኖ ተገኘ፤ ክቡር ዕንቍም ነበረበት፤ በዳዊትም ራስ ላይ አስቀመጡት፤ ከከተማዪቱም እጅግ ብዙ ምርኮ ወሰደ።'),
  ('9be14b2b-ce6a-5417-a011-dcec1e6649fe', '1e5ba6f8-149c-5c4f-aa92-63d9ef3d8f9f', 'd7fad515-0013-55d9-a96f-695bf0c87c08', 3, 3, 'በውስጥዋም የነበሩትን ሕዝብ አውጥተው በመጋዝ ተረተሩአቸው፤ በመጥረቢያም ቈራረጡአቸው። ዳዊትም በአሞን ልጆች ከተሞች ሁሉ እንዲሁ አደረገ። ዳዊትም ሕዝቡም ሁሉ ወደ ኢየሩሳሌም ተመለሱ።'),
  ('72eb7963-16c0-554c-ab1a-c4212963a7ce', '1e5ba6f8-149c-5c4f-aa92-63d9ef3d8f9f', 'd7fad515-0013-55d9-a96f-695bf0c87c08', 4, 4, 'ከዚህም በኋላ በጋዜር ላይ ከፍልስጥኤማውያን ጋር ጦርነት እንደ ገና ሆነ፤ ያንጊዜም ኡሳታዊው ሴቦቃይ ከኀያላን ወገን የነበረውን ሲፋይን ገድሎ ጣለው።'),
  ('3826a69e-e9d4-576f-a624-16793e54255f', '1e5ba6f8-149c-5c4f-aa92-63d9ef3d8f9f', 'd7fad515-0013-55d9-a96f-695bf0c87c08', 5, 5, 'ደግሞም ከፍልስጥኤማውያን ጋር ሰልፍ ነበረ፤ የያዔርም ልጅ ኤልያናን የጌት ሰው የጎልያድን ወንድም ለሕሜን ገደለ። የጦሩ የቦም እንደ ሸማኔ መጠቅለያ ሆኖ ተገኘ።'),
  ('3dff54a6-b15d-5e71-af27-e9da99d27abb', '1e5ba6f8-149c-5c4f-aa92-63d9ef3d8f9f', 'd7fad515-0013-55d9-a96f-695bf0c87c08', 6, 6, 'ደግሞ በጌት ላይ ሰልፍ ሆነ ፤ በዚያም በእጁና በእግሩ ስድስት ስድስት ጣቶች በጠቅላላው ሃያ አራት ጣቶች ያሉት አንድ ረዥም ሰው ነበረ፤ እርሱም ደግሞ ከኀያላን የተወለደ ነበረ።'),
  ('b5c0c8e9-b4c8-5450-a8f8-b1d0cf9b0147', '1e5ba6f8-149c-5c4f-aa92-63d9ef3d8f9f', 'd7fad515-0013-55d9-a96f-695bf0c87c08', 7, 7, 'እስራኤልንም በተገዳደረ ጊዜ የዳዊት ወንድም የሳምዓ ልጅ ዮናታን ገደለው።'),
  ('99a03fdd-a172-50a9-afaf-b54f27d6eecc', '1e5ba6f8-149c-5c4f-aa92-63d9ef3d8f9f', 'd7fad515-0013-55d9-a96f-695bf0c87c08', 8, 8, 'እነዚህም በጌት ውስጥ ከኀያላን የተወለዱ ነበሩ፤ እነርሱም አራት ኀያላን ነበሩ፤ በዳዊትም እጅ በአገልጋዮቹም እጅ ወደቁ።'),
  ('6c71c3cd-ee1a-5b70-a222-545585ff17f8', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 1, 1, 'ያንጊዜም ሰይጣን በእስራኤል ላይ ተነሣ፤ እስራኤልንም ይቈጥር ዘንድ ዳዊትን አነሣሣው።'),
  ('4cb92802-dcdd-508c-a104-3ff767332d49', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 2, 2, 'ዳዊትም ኢዮአብንና የሕዝቡን አለቆች ሁሉ፥ “ሂዱ፥ ከቤርሳቤህ ጀምሮ እስከ ዳን ድረስ እስራኤልን ቍጠሩ፤ ድምራቸውንም አውቅ ዘንድ አስታውቁኝ” አላቸው።'),
  ('8d439734-a45a-5c9e-a038-cb882628f693', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 3, 3, 'ኢዮአብም፥ “እግዚአብሔር በሕዝቡ ላይ አሁን ባለበት መቶ እጥፍ ይጨምር፤ የጌታዬ የንጉሥ ዐይኖችም ይዩ፤ ሁሉም የጌታዬ አገልጋዮች ናቸው፤ በእስራኤል ላይ በደል ይሆን ዘንድ ይህን ነገር ጌታዬ ለምን ይሻል?” አለ።'),
  ('d40cffa6-8a56-5910-afda-3a7e031cafd6', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 4, 4, 'ነገር ግን የንጉሡ ቃል በኢዮአብ ላይ አሸነፈ፤ ኢዮአብም ወጥቶ በእስራኤል ሁሉ ላይ ተዘዋወረ፤ ወደ ኢየሩሳሌምም መጣ።'),
  ('dc1df617-5878-56a0-a5d0-1a43e7200b79', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 5, 5, 'ኢዮአብም የቈጠራቸውን የሕዝቡን ድምር ለዳዊት ሰጠ፤ ከእስራኤልም ሁሉ አንድ ሚሊዮን አንድ መቶ ሺህ ሰይፍ የሚመዝዙ ሰዎች ተገኙ፤ ከይሁዳም አራት መቶ ሰባ ሺህ ሰይፍ የሚመዝዙ ሰዎች ተገኙ።'),
  ('a8106c60-d53c-5a9b-a303-b0c5dea12c26', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 6, 6, 'የንጉሡ ትእዛዝ ግን በኢዮአብ ዘንድ የተጠላ ነበረና ሌዊና ብንያም ከእነርሱ ጋር አልተቈጠሩም።'),
  ('c8b6f130-953e-5310-a58f-02ea9ee82614', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 7, 7, 'ይህም ነገር በእግዚአብሔር ፊት ክፉ ሆነ፤ በእስራኤልም ላይ መቅሠፍትን አመጣ።'),
  ('251212c9-54de-578f-ab41-ff9769e2c2b7', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 8, 8, 'ዳዊትም እግዚአብሔርን፥ “ይህን በማድረግ እጅግ በድያለሁ፤ አሁንም ታላቅ ስንፍና አድርጌአለሁና የባሪያህን ኀጢአት ታስወግድ ዘንድ እለምንሃለሁ” አለው።'),
  ('9ffda5dc-24dc-5080-a98e-f265681507a9', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 9, 9, 'እግዚአብሔርም ለነቢዩ ለጋድ እንዲህ አለው፦'),
  ('52af108f-8595-56f0-aaaa-6c181554e424', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 10, 10, '“ሂድ፥ ለዳዊት፦ እግዚአብሔር እንዲህ ይላል፦ ሦስቱን ነገሮች በፊትህ አኖራለሁ፤ አደርግብህ ዘንድ ከእነርሱ አንዱን ምረጥ ብለህ ንገረው።”'),
  ('2f3bdcb7-78fb-5f8f-ac2c-c66d0771da95', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 11, 11, 'ጋድም ወደ ዳዊት መጥቶ፥ “እግዚአብሔር እንዲህ ይላል፦ የምትወድደውን ምረጥ።'),
  ('7ba2b8c7-f891-5915-ad3a-a362cca72669', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 12, 12, 'የሦስት ዓመት ራብ፥ ወይም ሦስት ወር የጠላቶችህ ሰይፍ እንዲያገኝህ ከጠላቶችህ መሰደድን፥ ወይም ሦስት ቀን የእግዚአብሔር ሰይፍ፥ ቸነፈርም በምድር ላይ መሆንን፥ የእግዚአብሔርም መልአክ በእስራኤል ምድር ሁሉ ማጥፋትን ምረጥ፤ አሁንም ለላከኝ ምን እንደምመልስ አስረዳኝ” አለው።'),
  ('8ffa0392-fe74-5e6b-ae73-3d63fa930606', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 13, 13, 'ዳዊትም ጋድን፥ “እነዚህ ሦስት ነገሮች እጅግ ይከብዱኛል፥ እጅግም ተጨንቄአለሁ፤ አሁንም ምሕረቱ ብዙ ነውና በእግዚአብሔር እጅ መውደቅ ይሻለኛል፤ በሰው እጅ ግን አልውደቅ” አለው።'),
  ('1459a493-2018-586d-aca4-d1c79bc5dc34', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 14, 14, 'እግዚአብሔርም በእስራኤል ላይ ቸነፈርን ሰደደ፤ ከእስራኤልም ሰባ ሺህ ሰዎች ወደቁ።'),
  ('83281120-4998-5231-a6d8-78f96559a6d0', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 15, 15, 'እግዚአብሔርም ያጠፋት ዘንድ ወደ ኢየሩሳሌም መልአክን ሰደደ፤ ሊያጠፋትም በቀረበ ጊዜ እግዚአብሔር አይቶ ከመቅሠፍቱ ይቅር አለ፤ የሚያጠፋውንም መልአክ፥ “በቃህ፤ አሁን እጅህን መልስ” አለው። የእግዚአብሔርም መልአክ በኢያቡሳዊው በኦርና አውድማ አጠገብ ቆሞ ነበር።'),
  ('843743e3-54ee-53af-ad2e-c3297947c7ac', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 16, 16, 'ዳዊትም ዐይኖቹን አነሣ፤ የእግዚአብሔርም መልአክ በምድርና በሰማይ መካከል ቆሞ፥ የተመዘዘም ሰይፍ በእጁ ሆኖ ወደ ኢየሩሳሌም ተዘርግቶ አየ። ዳዊትና ሽማግሌዎቹም ማቅ ለብሰው በግንባራቸው ተደፉ።'),
  ('47ed62ce-3496-5591-ac1f-c6b045a2e4ef', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 17, 17, 'ዳዊትም እግዚአብሔርን፥ “ሕዝቡ ይቈጠር ዘንድ ያዘዝሁ እኔ አይደለሁምን? የበደልሁና ክፉ የሠራሁ እኔ ነኝ፤ እነዚህ በጎች ግን ምን አድርገዋል? አቤቱ አምላኬ ሆይ፥ እጅህ በእኔና በአባቴ ቤት ላይ ትሁን፤ ነገር ግን አቤቱ በሕዝብህ ላይ ለጥፋት አትሁን” አለው።'),
  ('6c64f57a-ce9d-5588-a651-9a20be2461d0', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 18, 18, 'የእግዚአብሔርም መልአክ ዳዊት ወጥቶ በኢያቡሳዊው በኦርና አውድማ ላይ ለእግዚአብሔር መሠዊያ ይሠራ ዘንድ ለዳዊት እንዲነግረው ጋድን አዘዘው።'),
  ('219ff52b-4fe4-53d0-a9b4-9fa0c9e8a6d1', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 19, 19, 'ዳዊትም በእግዚአብሔር ስም እንደ ተናገረው እንደ ጋድ ነገር ወጣ።'),
  ('fa4e7125-fea8-5e67-a505-6bc3b278a5b1', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 20, 20, 'ኦርናም ዘወር ብሎ ንጉሡ ዳዊትን፥ ከእርሱም ጋር ተሸሽገው የነበሩ አራቱን ብላቴኖቹን አየ። ኦርናም ስንዴ ያበራይ ነበር።'),
  ('b48953d4-cb83-59e9-a00b-d6e63fe152c1', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 21, 21, 'ዳዊትም ወደ ኦርና መጣ፤ ኦርናም ከአውድማው ወጥቶ ዳዊትን ተቀበለው። በምድርም ላይ ወድቆ ሰገደለት።'),
  ('1b6649f5-8866-5646-ab3a-15efb66059b9', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 22, 22, 'ዳዊትም ኦርናን፥ “በላዩ ለእግዚአብሔር መሠዊያ እሠራ ዘንድ ይህን የአውድማ ስፍራ ስጠኝ፤ በሙሉ ዋጋ ሽጥልኝ፤ መቅሠፍቱም ከሕዝቤ ይከለከላል” አለው።'),
  ('5db69397-d2f4-530d-ad48-444ee34a73ef', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 23, 23, 'ኦርናም ዳዊትን፥ “ለአንተ ውሰደው፤ ጌታዬ ንጉሡም በፊቱ ደስ የሚያሰኘውን ያድርግ፤ እነሆ፥ ለሚቃጠለው መሥዋዕት በሬዎቹን፥ ለእንጨትም የአውድማውን ዕቃ፥ ለእህልም ቍርባን ስንዴውን እሰጥሀለሁ፥ ሁሉን እሰጣለሁ” አለው።'),
  ('e6beb05b-3b3d-5b91-aedd-3b69a310f10f', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 24, 24, 'ንጉሡም ዳዊት ኦርናን፥ “አይደለም፥ ነገር ግን ለአንተ ያለውን ለእግዚአብሔር አምጥቼ የሚቃጠል መሥዋዕት በከንቱ አላቀርብምና በተገቢው ዋጋ እገዛዋለሁ” አለው።'),
  ('d37cd13c-d927-5171-a38f-b30e467cf550', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 25, 25, 'ዳዊትም ስለ ስፍራው ስድስት መቶ ሰቅል ወርቅ በሚዛን ለኦርና ሰጠው።'),
  ('6316a7e6-d25a-5e7a-a5bb-d372b6e3c74f', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 26, 26, 'ዳዊትም በዚያ ለእግዚአብሔር መሠዊያ ሠራ፤ የሚቃጠለውን መሥዋዕትና የደኅንነቱንም መሥዋዕት አቀረበ፤ እግዚአብሔርንም ጠራ፤ ከሰማይም ለሚቃጠለው መሥዋዕት በሚሆነው መሠዊያ ላይ በእሳት መለሰለት፤ እሳቱም የሚቃጠለውን መሥዋዕት በላ።'),
  ('e9a1011e-71c1-5201-a7aa-28fea9b69289', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 27, 27, 'እግዚአብሔርም መልአኩን አዘዘው፤ ሰይፉንም በአፎቱ ከተተው።'),
  ('8cb90347-53e6-5b9f-afd0-9e24b9d1d9ed', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 28, 28, 'በዚያም ጊዜ እግዚአብሔር በኢያቡሳዊው በኦርና አውድማ እንደ ሰማው ዳዊት ባየ ጊዜ፥ በዚያ መሥዋዕትን ሠዋ።'),
  ('e821f7e8-25f0-5b73-a989-6b4e09a7da4b', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 29, 29, 'ሙሴም በምድረ በዳ የሠራት የእግዚአብሔር ማደሪያና ለሚቃጠል መሥዋዕት የሚሆነው መሠዊያ በዚያን ጊዜ በገባዖን ባለው በኮረብታው መስገጃ ነበሩ።'),
  ('76517e6c-3d36-5994-a769-1ca669fc7fab', '7fbd6bf0-cae0-5505-aa11-6003e2d6b76c', '337bb204-471d-5c93-a3e9-218202aa9ad8', 30, 30, 'ዳዊት ግን ከእግዚአብሔር መልአክ ሰይፍ የተነሣ ስለ ፈራ እግዚአብሔርን ለመጠየቅ ወደዚያ ይሄድ ዘንድ አልቻለም።'),
  ('fd2df77d-bba2-503e-a45b-c79093aaa8fd', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 1, 1, 'ዳዊትም፥ “ይህ የአምላኬ የእግዚአብሔር ቤት ነው፤ ይህም ለእስራኤል ለሚቃጠል መሥዋዕት የሚሆነው መሠዊያ ነው” አለ።'),
  ('8310ffda-50f3-576f-aa5c-c896a7034534', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 2, 2, 'ዳዊትም በእስራኤል ምድር የነበሩትን መጻተኞች ይሰበስቡ ዘንድ አዘዘ፤ የእግዚአብሔርንም ቤት ለመሥራት የሚወቀሩትን ድንጋዮች ይወቅሩ ዘንድ ጠራቢዎችን አኖረ።'),
  ('0bd73b41-5f50-564c-a6a1-84c70dddfca6', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 3, 3, 'ዳዊትም ለበሮቹ ሳንቃ ለሚሆኑ ለምስማርና ለመጠረቂያ ብዙ ብረት፥ ከብዛቱም የተነሣ የማይመዘን ናስ አዘጋጀ።'),
  ('ba45b342-a5d9-542d-ae60-cc35a036dcac', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 4, 4, 'ሲዶናውያንና የጢሮስ ሰዎችም ብዙ የዝግባ እንጨት ለዳዊት ያመጡ ነበርና ቍጥር የሌላቸውን የዝግባ እንጨቶች አዘጋጀ።'),
  ('2aeba3c1-7dc4-5061-a879-9af85aee1d62', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 5, 5, 'ዳዊትም፥ “ልጄ ሰሎሞን ታናሽና ለጋ ብላቴና ነው፤ ለእግዚአብሔርም የሚሠራው ቤት እጅግ ማለፊያና በሀገሩ ሁሉ ስሙና ክብሩ እንዲጠራ ይሆን ዘንድ ይገባል፤ ስለዚህ አዘጋጅለታለሁ” አለ። ዳዊትም ሳይሞት አስቀድሞ ብዙ አዘጋጀ።'),
  ('57a6ecdc-0ea0-5613-a6b7-7da919bba3e1', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 6, 6, 'ልጁንም ሰሎሞንን ጠርቶ ለእስራኤል አምላክ ለእግዚአብሔር ስም ቤት ይሠራ ዘንድ አዘዘው።'),
  ('4b192dc3-617a-5937-aa95-6c579d3e8f49', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 7, 7, 'ዳዊትም ሰሎሞንን እንዲህ አለው፥ “ልጄ ሆይ፥ እኔ ለእስራኤል አምላክ ለእግዚአብሔር ስም ቤት እሠራ ዘንድ በልቤ አስቤ ነበር።'),
  ('f6ed80e1-12fe-51e0-a495-c5cbff9cb746', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 8, 8, 'ነገር ግን የእግዚአብሔር ቃል እንዲህ ሲል ወደ እኔ መጣ፦ እጅግ ብዙ ደም አፍስሰሃል፤ ታላቅም ሰልፍ አድርገሃል፤ በፊቴም በምድር ላይ ብዙ ደም አፍስሰሃልና ለስሜ ቤት አትሠራም።'),
  ('8c5b22ec-169c-5fe8-a14b-6e865334058e', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 9, 9, 'እነሆ፥ ልጅ ይወለድልሃል፤ የዕረፍት ሰውም ይሆናል፤ በዙሪያውም ካሉ ከጠላቶቹ ሁሉ አሳርፈዋለሁ፤ ስሙ ሰሎሞን ይባላልና፥ በዘመኑም ሰላምንና ጸጥታን ለእስራኤል እሰጣለሁ።'),
  ('75576abd-7379-5712-ae2c-eebbd3ee9756', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 10, 10, 'እርሱ ለስሜ ቤት ይሠራል፤ ልጅም ይሆነኛል፤ እኔም አባት እሆነዋለሁ፤ የመንግሥቱንም ዙፋን በእስራኤል ላይ ለዘለዓለም አጸናለሁ።'),
  ('1b7701d0-f6d2-5884-a342-38c318b4c269', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 11, 11, 'አሁንም ልጄ ሆይ፥ እግዚአብሔር ከአንተ ጋር ይሁን፤ ስለ አንተም እንደ ተናገረው ያከናውንልህ፤ የአምላክህንም የእግዚአብሔርን ቤት ሥራ።'),
  ('27b80f56-2f94-5d66-ac5f-cb565513b115', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 12, 12, 'ብቻ የአምላክህን የእግዚአብሔርን ሕግ ትጠብቅና ታደርግ ዘንድ እግዚአብሔር ጥበብንና ማስተዋልን ይስጥህ፤ መንግሥትህንም በእስራኤል ላይ ያጽና።'),
  ('41da7a6a-1ce8-5940-a83c-b86bf39d61f1', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 13, 13, 'እግዚአብሔር ስለ እስራኤል ሙሴን ያዘዘውን ሥርዐትና ፍርድ ትጠብቅና ታደርግ ዘንድ ብትጠነቀቅ በዚያን ጊዜ ይከናወንልሃል፤ አይዞህ፥ በርታ፤ አትፍራ፤ አትደንግጥም።'),
  ('50cdd9c2-8ea4-52cd-aee7-e66218eddb4a', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 14, 14, 'አሁንም፥ እነሆ፥ በድህነቴ ለእግዚአብሔር ቤት መቶ ሺህ መክሊት ወርቅና አንድ ሚሊዮን መክሊት ብር፥ ሚዛንም የሌላቸው ብዙ ናስና ብረት አዘጋጅቻለሁ፤ ደግሞም የማይቈጠር ብዙ የዝግባ እንጨትና ድንጋዮች አዘጋጅቻለሁ፤ አንተም ልጄ ከዚያ በላይ ጨምር።'),
  ('13155bf2-672f-5631-a992-435af83f0f95', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 15, 15, 'አንተም ብዙ ሠራተኞችን፥ ድንጋይና እንጨት ወቃሪዎችንና ጠራቢዎችን፥ ሥራውንም ሁሉ ለማድረግ ጠቢባን ሰዎችን አብዝተህ ጨምር።'),
  ('fc02ca83-6e2e-5fb3-acf8-0947f4d59708', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 16, 16, 'ቍጥር በሌለው በወርቅና ብር፥ በናስና ብረት ተነሥተህ ሥራ፤ እግዚአብሔርም ከአንተ ጋር ይሁን።”'),
  ('2aa62c27-6451-51f6-a8e0-b17af149d945', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 17, 17, 'ዳዊትም ደግሞ ልጁን ሰሎሞንን ይቀበሉትና ያግዙት ዘንድ የእስራኤልን አለቆች ሁሉ እንዲህ ሲል አዘዛቸው፦'),
  ('6cd2b71a-06be-59d4-a8b5-4b4690466888', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 18, 18, '“አምላካችሁ እግዚአብሔር ከእናንተ ጋር አይደለምን? በምድርም የሚቀመጡትን በእጃችሁ አሳልፎ ሰጥቶአልና፥ ምድርም በእግዚአብሔርና በሕዝቡ ፊት ተገዝታለችና በዙሪያችሁ ከአሉ ጠላቶቻችሁም ሁሉ ዕረፍትን ሰጥቶአችኋል።'),
  ('a4e72ee6-e277-5954-aad5-6efd0f4a5b84', 'c6ac2fc6-038f-519b-a722-d4ea5b0c8657', '55a29a1c-9f6c-50d9-a64d-fe0ccafe4ce9', 19, 19, 'አሁንም አምላካችሁን እግዚአብሔርን ትፈልጉ ዘንድ ልባችሁንና ነፍሳችሁን ስጡ፤ ለእግዚአብሔርም ስም ወደሚሠራው ቤት የእግዚአብሔርን የቃል ኪዳኑን ታቦትና የእግዚአብሔርን ንዋየ ቅድሳት ታመጡ ዘንድ ተነሥታችሁ የአምላክን የእግዚአብሔርን መቅደስ ሥሩ።”'),
  ('501429bb-34b4-5bd8-a107-21fdea063438', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 1, 1, 'ዳዊትም በሸመገለ ጊዜ፥ ዕድሜንም በጠገበ ጊዜ ልጁን ሰሎሞንን በእርሱ ፋንታ በእስራኤል ላይ አነገሠው።'),
  ('41f92ee6-f48a-5b15-a877-66a77ebdaf60', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 2, 2, 'የእስራኤልንም አለቆች ሁሉ፥ ካህናቱንም፥ ሌዋውያኑንም ሰበሰበ።'),
  ('3cf30a35-50a2-51bf-a04c-9cdf46e5efaf', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 3, 3, 'ሌዋውያንም ከሠላሳ ዓመት ዕድሜ ጀምሮ ወደ ላይ ተቈጠሩ፤ ቍጥራቸውም በእያንዳንዱ ነፍስ ወከፍ ሲቈጠሩ ሠላሳ ስምንት ሺህ ነበረ።'),
  ('195caee2-578c-518c-a2e1-50a4f08f472a', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 4, 4, 'ከእነዚህም ውስጥ የእግዚአብሔርን ቤት ሥራ የሚያሠሩት ሃያ አራት ሺህ ነበሩ፤ ስድስቱ ሺህም ጻፎችና ፈራጆች ነበሩ።'),
  ('4d01f7ae-ce01-547d-ab06-bf7b256503a2', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 5, 5, 'አራቱ ሺህም በረኞች ነበሩ፤ አራቱ ሺህም ለምስጋና በተሠሩት በዜማ ዕቃዎች እግዚአብሔርን ያመሰግኑ ነበር።'),
  ('fca52692-c22d-51eb-a941-468d85619326', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 6, 6, 'ዳዊትም እንደ ሌዊ ልጆች እንደ ጌድሶንና እንደ ቀዓት እንደ ሜራሪም በየሰሞናቸው መደባቸው።'),
  ('f563761b-5d0e-5445-a5ce-854ce88857fd', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 7, 7, 'ከጌድሶናውያን ለአዳንና ሰሜኢ ነበሩ።'),
  ('f59165c2-4fa5-50c5-a6e3-008744cc104c', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 8, 8, 'የለአዳን ልጆች አለቃው አድሔኤል፥ ዜቶም፥ ዮሔል ሦስት ነበሩ።'),
  ('c6ea4749-c1b5-5fee-a270-93a75bc92e26', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 9, 9, 'የሰሜኢ ልጆች ሰሎሚት፥ ሐዝኤል፥ ሐራን ሦስት ነበሩ። እነዚህ የለያአዳን አባቶች ቤቶች አለቆች ነበሩ።'),
  ('5d2b4d0e-2a42-53b2-a619-abe99a951096', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 10, 10, 'የሰሜኢ ልጆች ኤኢት፥ ዚዛ፥ ኢያአስ፥ በሪዓ ነበሩ። እነዚህ አራቱ የሰሜኢ ልጆች ነበሩ።'),
  ('751838fb-f006-52f4-a2ff-afde8e3cee52', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 11, 11, 'አለቃው ኤኢት ነበረ፤ ሁለተኛው ዚዛ ነበረ፤ ኢያአስና በሪዓ ግን ብዙ ልጆች አልነበሩአቸውም፤ ስለዚህ እንደ አንድ አባት ቤት ሆነው ተቈጠሩ።'),
  ('1ee52dcf-ce98-5caa-a81a-7b5d7d0f4fbe', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 12, 12, 'የቀዓት ልጆች እንበረም፥ ይስዓር፦ ኬብሮን፥ ዑዝኤል አራት ነበሩ።'),
  ('c61cd92a-c46f-5e06-ac63-2dfcbc3f93b0', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 13, 13, 'የእንበረም ልጆች አሮንና ሙሴ ነበሩ፤ አሮንም ለቅድስተ ቅዱሳን የተቀደሰ ይሆን ዘንድ ተመረጠ፤ እርሱና ልጆቹ ለዘለዓለም በእግዚአብሔር ፊት ያጥኑና ያገለግሉ ነበር፤ በስሙም ለዘለዓለም ይባርኩ ነበር።'),
  ('04b8de5b-a6ab-51bd-a061-71d3fc24b567', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 14, 14, 'የእግዚአብሔርም ሰው ሙሴና ልጆቹ በሌዊ ነገድ ተቈጠሩ።'),
  ('c9ba3e32-7d2e-50cb-a2bd-c5b826cb77c6', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 15, 15, 'የሙሴ ልጆችም ጌርሳምና አልዓዛር ነበሩ።'),
  ('3a5cfcc2-8877-52a4-a07e-712bacc34cea', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 16, 16, 'የጌርሳም ልጆች አለቃ ሱባኤል ነበረ።'),
  ('e2e36a3a-078d-530d-a2f4-3e70e2b6b132', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 17, 17, 'የአልዓዛርም ልጆች አለቃ ረዓብያ ነበረ፤ አልዓዛርም ሌሎች ልጆች አልነበሩትም፤ የረዓብያ ልጆች እጅግ ብዙ ነበሩ።'),
  ('72cdbdb0-4a26-5147-a7c7-12c55ca97de8', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 18, 18, 'የይስዓር ልጆች አለቃው ሰሎሚት ነበረ።'),
  ('bc97c79f-2d42-5894-a699-243f8a0ec2c0', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 19, 19, 'የኬብሮን ልጆች አለቃው ኢያኤርያ፥ ሁለተኛው አማርያ፥ ሦስተኛው ኢያዝሔል፥ አራተኛው ኢያቄምያስ ነበሩ።'),
  ('7756cd6b-d368-5d46-af4a-8e6c2bdf3017', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 20, 20, 'የዑዝኤል ልጆች አለቃው ሚካ፥ ሁለተኛው ይስያ ነበሩ።'),
  ('36d3258b-35b4-530d-a263-36eb7cc5dde9', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 21, 21, 'የሜራሪ ልጆች ሞዓሊና ሐሙሲ ነበሩ። የሞዓሊ ልጆች አልዓዛርና ቂስ ነበሩ።'),
  ('1f8ade53-810e-52de-abfd-bf087ee45228', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 22, 22, 'አልዓዛርም ሴቶች ልጆች ብቻ እንጂ ወንዶች ልጆች ሳይወልድ ሞተ፤ ወንድሞቻቸውም የቂስ ልጆች አገቡአቸው።'),
  ('ac55422d-b4b1-54db-a181-4316aa17c7ef', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 23, 23, 'የሐሙሲ ልጆች፤ ሞዓሊ፥ አዴር፥ ኢያሪሞት ሦስት ነበሩ።'),
  ('474fd90e-1d22-56ef-a0ac-0b033da61a49', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 24, 24, 'የእግዚአብሔርን ቤት አገልግሎት በሠሩ ከሃያ አምስት ዓመት ዕድሜ ጀምሮ ወደ ላይ በነበሩ በእያንዳንዳቸው በስማቸው በተቈጠሩት ላይ የአባቶች ቤት አለቆች የሆኑት በየአባቶቻቸው ቤት የሌዊ ልጆች እነዚህ ነበሩ።'),
  ('f2075b57-e680-5c9e-a196-8680c5541c26', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 25, 25, 'ዳዊትም እንዲህ አለ፥ “የእስራኤል አምላክ እግዚአብሔር ለሕዝቡ ዕረፍት ሰጥቶአል፤ በኢየሩሳሌምም ለዘለዓለም ይቀመጣል።'),
  ('dfbb9e1b-3cc7-5405-a29b-b588afd2a28d', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 26, 26, 'ሌዋውያንም ከእንግዲህ ወዲህ ማደሪያውንና የማገልገያ ዕቃውን ሁሉ አይሽከሙም።”'),
  ('919e82a3-03e9-548b-aa19-df519b7af64a', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 27, 27, 'በመጨረሻውም በዳዊት ትእዛዝ ከሃያ አምስት ዓመት ዕድሜ ጀምሮ ከዚያም በላይ ያሉት የሌዊ ልጆች ተቈጠሩ።'),
  ('10633738-cf3f-5f89-a1fa-819fefca5059', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 28, 28, 'የእግዚአብሔርንም ቤት በየአደባባዩና በየመጋረጃው ውስጥ ለማገልገል፥ ቅዱሱንም ዕቃ ሁሉ ለማንጻት፥ የእግዚአብሔርንም ቤት አገልግሎት ለመሥራት ከአሮን ልጆች እጅ በታች ሹሞአቸው ነበር።'),
  ('6e6431d5-94d0-52df-ac36-01a6e56c2cc0', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 29, 29, 'ደግሞም ገጸ ኅብስት፥ ስስ ቂጣም ቢሆን፥ በምጣድም ቢጋገር፥ ቢለወስም ለእህል ቍርባን በሆነው በመልካሙ ዱቄት በመስፈሪያና በልክ ሁሉ ያገለግሉ ዘንድ ሹሞአቸው ነበር።'),
  ('1fa4b75d-d294-579e-a1af-3beb225df4f7', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 30, 30, 'በየጥዋቱና በየማታው ቆመው እግዚአብሔርን ለማመስገንና ለማክበር፥'),
  ('9f9b95a7-46f6-53be-a274-ee61444b962a', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 31, 31, 'በየሰንበታቱም፥ በየመባቻዎቹም፥ በየበዓላቱም እንደ ሥርዐቱ ቍጥር በእግዚአብሔር ፊት ዘወትር ለእግዚአብሔር የሚቃጠለውን መሥዋዕት ሁሉ ለማቅረብ፥'),
  ('7dbb26ac-75ed-543e-a729-3e8569dfea21', 'df0da09a-5059-5ea5-a658-1637460ca06e', 'c38571ab-90c2-57f6-ac03-02e180c8e7dc', 32, 32, 'ለእግዚአብሔርም ቤት አገልግሎት የምስክሩን ድንኳን ሥርዐት፥ የወንድሞቻቸውን የአሮንን ልጆች ሥርዐት ለመጠበቅ ሹሞአቸው ነበር።'),
  ('c85884f5-d81d-5a31-abe9-e948d69562eb', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 1, 1, 'የአሮንም ልጆች ሰሞን ይህ ነው። የአሮን ልጆች ናዳብ፥ አብዩድ፥ አልዓዛር፥ ኢታምር ነበሩ።'),
  ('e4ea9dcd-4ef1-5a64-ae7d-89c6539f5522', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 2, 2, 'ናዳብና አብዩድ ግን ልጆች ሳይወልዱ ከአባታቸው በፊት ሞቱ፤ የአሮን ልጆች አልዓዛርና ኢታምርም ካህናት ሆነው አገለገሉ።'),
  ('f4310bc1-cd63-5d3d-a9ad-83fcbc32cc51', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 3, 3, 'ዳዊትም ከአልዓዛር ልጆች ሳዶቅን፥ ከኢታምርም ልጆች አቤሜሌክን እንደ ቍጥራቸው፥ እንደ አገልግሎታቸውና እንደ እየአባቶቻቸው ቤቶች ከፍሎ መደባቸው።'),
  ('333d09e1-2932-5360-a371-07adddf10711', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 4, 4, 'የአልዓዛርም ልጆች አለቆች ከኢታምር ልጆች አለቆች በልጠው ተገኙ፤ እንዲህም ተመደቡ፤ ከአልዓዛር ልጆች እንደ አባቶቻቸው ቤቶች ዐሥራ ስድስት አለቆች፥ ከኢታምርም ልጆች እንደ አባቶቻቸው ቤቶች ስምንት አለቆች ነበሩ።'),
  ('bcf4d335-1a09-5158-abea-f386973595c6', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 5, 5, 'ከአልዓዛርና ከኢታምርም ልጆች መካከል የንዋያተ ቅዱሳቱና የእግዚአብሔር ቤት አለቆች ነበሩና እነዚህና እነዚያ እንዲህ በዕጣ ተመደቡ።'),
  ('30e84690-6472-54ec-a992-f86bc019d078', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 6, 6, 'ከሌዋውያንም ወገን የነበረው የናትናኤል ልጅ ጸሓፊው ሳምያስ በንጉሡና በአለቆቹ ፊት ፥ በካህኑ በሳዶቅና በአብያታርም ልጅ በአቤሜሌክ ፊት ፥ በካህናቱና በሌዋውያኑ አባቶች ቤቶች አለቆች ፊት ጻፋቸው፤ አንዱንም የአባት ቤት ለአልዓዛር፥ አንዱንም ለኢታምር ጻፈ።'),
  ('73d9f7f9-aca3-55c2-a8c9-5de251c58f1b', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 7, 7, 'መጀመሪያውም ዕጣ ለኢያሬብ ወጣ፤ ሁለተኛውም ለኢያድያ፥'),
  ('d840ced1-97af-5922-ac37-42819cdff064', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 8, 8, 'ሦስተኛውም ለካሬም፥ አራተኛውም ለሴዓሪን፥'),
  ('cab8f05d-5e7b-5b5a-acb0-5f2718466eaf', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 9, 9, 'አምስተኛውም ለመልክያ፥ ስድስተኛውም ለሜዒያኢም፥'),
  ('558b0d85-88fe-54cc-af3a-1b71e1f73b25', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 10, 10, 'ሰባተኛውም ለአቆስ፥ ስምንተኛው ለአብያ፥'),
  ('f31436ca-9cf6-5826-a8cc-cbf0a4e9d5fd', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 11, 11, 'ዘጠነኛው ለኢያሱ፥ ዐሥረኛው ለሴኬንያ፥'),
  ('0f1f0b37-afe9-5fd7-a6c3-0e3cd0593cd1', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 12, 12, 'ዐሥራ አንደኛው ለኤልያሴብ፥ ዐሥራ ሁለተኛው ለኤልያቄም፥'),
  ('9ba47c50-9ce4-521e-a32f-9c721ed71b43', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 13, 13, 'ዐሥራ ሦስተኛው ለኦፋዕ፥ ዐሥራ አራተኛው ለኤሳባእ፥'),
  ('db778c5b-1cfd-5f31-a2e4-06df45aa7ce0', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 14, 14, 'ዐሥራ አምስተኛው ለቤልጋዕ፥ ዐሥራ ስድስተኛው ለኤሜር፥'),
  ('87ebd397-707c-56e5-aabb-9483c89fe27f', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 15, 15, 'ዐሥራ ሰባተኛው ለኢያዜር፥ ዐሥራ ስምንተኛው ለአፌስ፥'),
  ('07c0523d-3c99-5cc1-a89e-560683ef2ade', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 16, 16, 'ዐሥራ ዘጠነኛው ለፈታሕያ፥ ሃያኛው ለሕዝቄል፥'),
  ('72a4b32a-814e-5a5b-aa2c-a083065b164f', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 17, 17, 'ሃያ አንደኛው ለአኬኖ፥ ሃያ ሁለተኛው ለጋሙሄል፥'),
  ('f00235a9-dbf7-553b-a172-582e9d3d5b7f', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 18, 18, 'ሃያ ሦስተኛው ለደላኢያ፥ ሃያ አራተኛው ለሙዓዚ።'),
  ('17f21a25-6629-5ba2-a6d8-462a65aa4974', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', '95d2526c-5a0a-51d5-aff3-8ead1dc3ca3d', 19, 19, 'የእስራኤል አምላክ እግዚአብሔር እንዳዘዘ፥ በአባታቸው በአሮን እጅ እንደ ተሰጣቸው ሥርዐት ወደ እግዚአብሔር ቤት ይገቡ ዘንድ እንደ እየአገልግሎታቸው ቍጥራቸው ይህ ነበረ።'),
  ('995a7574-ce72-56dd-a022-cfd2efd5a9bb', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 1, 20, 'ከቀሩትም የሌዊ ልጆች፤ ከእንበረም ልጆች ስባሄል፤ ከስባሄል ልጆች ኢያዳእያ፤'),
  ('a574b0b7-aac1-58ae-ad3d-003af1caea30', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 2, 21, 'ከአረብያም ልጆች የአረብያ ልጅ አራድያ፥ አለቃው ኢያስያስ፤'),
  ('afaa4b8e-0693-5551-a72b-12434612d573', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 3, 22, 'ከኢስዓራውያን ሰሎሞት፤ ከሰሎሞት ልጆች ኤናት፤'),
  ('74ab3ccb-f434-535d-a79a-d44561de458e', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 4, 23, 'ከኢዩዲዩ ልጆች አለቃው ይሪያ፥ ሁለተኛው አማርያ፥ ሦስተኛው ኢያዚሄል፥ አራተኛው ኢያቁምያ፤'),
  ('c1a0eae8-df49-528d-a254-eb25268fb867', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 5, 24, 'የኢያዝሄል ልጅ ሚካ፤ የሚካ ልጅ ሳሜር፤'),
  ('0f226bbb-7311-5a68-aae2-698f04288449', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 6, 25, 'የሚካ ወንድም ኢሳእያ፤ የኢሳእያ ልጅ ዘካርያስ፤'),
  ('864c5ab6-dc6d-551d-afd2-9bd3d0a37614', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 7, 26, 'የሜራሪ ልጆች ሞዓሊና ሐሙሲ፤ የዖዝያስ ልጅ ባኒ፤'),
  ('0bb8e04f-f09f-512c-a15c-276507bcac50', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 8, 27, 'የሜራሪ ልጆች፤ ከዖዝያ ይሰዓም፥ ዝኩር፥ አብዲ፤'),
  ('c510ccb7-a808-551e-a7e2-a06e440af556', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 9, 28, 'የሞዓሊ ልጅ አልዓዛር፥ እርሱም ልጆች አልነበሩትም፤'),
  ('a64bc8c9-4976-5355-a304-7cfbd5f8082d', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 10, 29, 'ከቂስ፤ የቂስ ልጅ አራሜሄል፤'),
  ('f77e2386-ee21-5562-adb1-5ad5c89a700e', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 11, 30, 'የሐሙሲ ልጆች፤ ሞዓሊ፥ ኤዳር፥ ኢያሪሞት። እነዚህ እንደ አባቶቻቸው ቤቶች የሌዋውያን ልጆች ነበሩ።'),
  ('1e4f9ee9-4072-5665-a391-e1f98f4ba7d2', 'e313d324-2a05-5cfe-afae-666e0bb7a0d7', 'c17653c3-6210-5319-a035-e41663c3e061', 12, 31, 'እነዚህም ደግሞ በንጉሡ በዳዊትና በሳዶቅ በአቤሜሌክም በሌዋውያንና በካህናት አባቶች ቤቶች አለቆች ፊት፥ ታላላቆች እንደ ታናናሽ ወንድሞቻቸው፥ እንደ ወንድሞቻቸው እንደ አሮን ልጆች ዕጣ ተጣጣሉ።'),
  ('cbd581cd-7437-50fd-a4ce-100b0fd81047', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 1, 1, 'ዳዊትና የሠራዊቱ አለቆችም ከአሳፍና ከኤማን ከኤዶትምም ልጆች በመሰንቆና በበገና፥ በጸናጽልም የሚዘምሩ ሰዎችን ለማገልገል ለዩ፤ በየአገልግሎታቸውም ሥራ የሚሠሩ ሰዎች ቍጥር ይህ ነበረ።'),
  ('40b2b505-2041-5cc7-a727-eb7c397c57df', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 2, 2, 'ከአሳፍ ልጆች፤ ዘኩር፥ ዮሴፍ፥ ናታንያ፥ ኤራኤል፤ እነዚህ የአሳፍ ልጆች የንጉሡ ቀራቢዎች ነበሩ።'),
  ('8db2b554-f8ac-5ac9-a44a-75f903086fbd', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 3, 3, 'ከኤዶትም የኤዶትም ልጆች፤ ጎዶልያስ፥ ሱሪ፥ የሻያ፥ ሰሜኢ፥ ሐሸብያ፥ መታትያ፥ እነዚህ ስድስቱ ከአባታቸው ከኤዶትም ጋር በበገና እየዘመሩ እግዚአብሔርን ያመሰግኑ ነበር።'),
  ('f6ff82c2-85fc-520d-a819-67887dc5581b', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 4, 4, 'ከኤማን የኤማን ልጆች፤ ቡቅያ፥ መታንያ፥ ዓዛርዔል፥ ሱባኤል፥ ኢየሪሙት፥ ሐናንያ፥ ሐናኒ፥ ኤልያታ፥ ጌዶላቲ፥ ሮማንቴዔዜር፥ ዮስብቃሳ፥ ሜኤላቴ፥ ሆቴር፥ መሐዝዮት፤'),
  ('eb42db78-c959-5744-aa8b-a58565419655', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 5, 5, 'እነዚህ ሁሉ ቀንደ መለከቱን ከፍ ያደርጉ ዘንድ በእግዚአብሔር ቃል በንጉሡ ፊት የሚዘምረው የኤማን ልጆች ነበሩ። እግዚአብሔርም ለኤማን ዐሥራ አራት ወንዶች ልጆችንና ሦስት ሴቶች ልጆችን ሰጠው።'),
  ('5ef2316d-c202-5e47-a3b4-56f7b87c8b0a', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 6, 6, 'እነዚህ ሁሉ በእግዚአብሔር ቤት በጸናጽልና በበገና፥ በመሰንቆም ከአባታቸው ጋራ የእግዚአብሔርን ቤት ለማገልገል ወደ ንጉሡ ቀርበው ያመሰግኑ ነበር። አሳፍም ኤዶትምም ኤማንም ያመሰግኑ ነበር።'),
  ('d29a48bd-32c2-5ef1-a1ba-cd1ee2f37c3b', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 7, 7, 'የብልሃተኞቹም ቍጥር እግዚአብሔርን ለማመስገን ከሚያውቁ ከወንድሞቻቸው ጋር ሁለት መቶ ሰማንያ ስምንት ነበረ።'),
  ('86ef2080-c707-57c1-a709-e7ab3152b4a0', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 8, 8, 'ሁሉም ተካክለው፥ ታናሹም ታላቁም፥ ለሰሞናቸው ዕጣ ተጣጣሉ እነርሱም ፍጹማንና የተማሩ ነበሩ።'),
  ('b4a5f8ce-335b-5f02-ab9e-100612abebb9', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 9, 9, 'የመጀመሪያው ዕጣ ለአሳፍ ወገን ለዮሴፍ ለወንድሞቹና ለልጆቹ ለዐሥራ ሁለቱ ደረሳቸው፤ ሁለተኛውም ዕጣ ለጎዶልያስ ለልጆቹና ለወንድሞቹ ለዐሥራ ሁለቱ ደረሳቸው፤')
